var MASTER_EAU_B04 = {
  'MASTER-EAU-039': {
    id: 'MASTER-EAU-039',
    titre: 'Modèles conceptuels des systèmes aquifères',
    fiche: {
      intro: "Un aquifère est une formation géologique perméable capable de stocker et de transmettre l'eau souterraine en quantités exploitables. La classification des systèmes aquifères (libre, captif, semi-captif) et la compréhension de leur structure géologique sont les fondements de l'hydrogéologie. Les modèles conceptuels guident toute étude quantitative.",
      sections: [
        { titre: "Types d'aquifères et leurs caractéristiques", sous_sections: [
          { titre: "Aquifère libre, captif et semi-captif", contenu: "L'aquifère libre (phréatique) a sa surface piézométrique libre, en contact avec la zone non saturée. Sa charge hydraulique varie selon les recharges et prélèvements. L'aquifère captif est entièrement saturé et confiné entre deux couches imperméables (aquitards). Sa pression peut dépasser la pression atmosphérique (artésianisme). L'aquifère semi-captif est délimité par des aquitards semi-perméables qui permettent des transferts verticaux (drainance). Cette classification conditionne les équations de débit et les tests de pompage." },
          { titre: "Classification lithologique des aquifères", contenu: "Les aquifères poreux (sables, graviers alluviaux) stockent l'eau dans les pores intergranulaires. Leur perméabilité (Ks = 10⁻⁵ à 10⁻² m/s) est relativement homogène. Les aquifères fracturés (granite, schiste) transmettent principalement l'eau par les fractures, avec une double porosité (matrice + fractures). Les aquifères karstiques (calcaires, dolomies) présentent une triple porosité (pores, fractures, conduits karstiques) avec une perméabilité extrêmement variable (10⁻⁶ à 10² m/s). La distinction entre ces types conditionne les méthodes d'investigation et de modélisation." }
        ]},
        { titre: "Paramètres hydrodynamiques fondamentaux", sous_sections: [
          { titre: "Porosité, conductivité hydraulique et transmissivité", contenu: "La porosité totale n = Vvides/Vtotal est la fraction volumique des vides. La porosité efficace ne (drainage libre) est inférieure à n (eau retenue par capillarité). La conductivité hydraulique K (m/s) représente la facilité d'écoulement (Darcy). La transmissivité T = K × b (m²/s) intègre l'épaisseur b de l'aquifère. Des valeurs typiques : alluvions T = 10⁻³ à 10⁻¹ m²/s, craie T = 10⁻⁴ à 10⁻² m²/s, granite fracturé T = 10⁻⁶ à 10⁻⁴ m²/s." },
          { titre: "Coefficient d'emmagasinement et drainance", contenu: "Le coefficient d'emmagasinement S est le volume d'eau libéré par unité de surface pour une baisse piézométrique de 1m. Pour un aquifère libre, S ≈ ne (5-30%). Pour un aquifère captif, S = Ss × b avec Ss = compressibilité spécifique (10⁻⁶ à 10⁻⁴ m⁻¹), donnant S ≈ 10⁻⁵ à 10⁻³. La drainance r' = K'/b' (s⁻¹) d'un aquitard semi-perméable conditionne les transferts verticaux entre aquifères superposés." }
        ]},
        { titre: "Structure géologique et modèle conceptuel", sous_sections: [
          { titre: "Construction du modèle conceptuel", contenu: "Le modèle conceptuel intègre la géologie (stratigraphie, structures, failles), l'hydrogéologie (niveaux piézométriques, directions d'écoulement), la géochimie (faciès hydrochimiques, isotopes) et les données de forage (logs, essais). Il définit les limites du système (imperméables, frontières à flux imposé, rivière), les zones de recharge et de décharge, et les connexions entre unités. Ce modèle conceptuel est préalable indispensable à tout modèle numérique." },
          { titre: "Cartes piézométriques et directions d'écoulement", contenu: "La carte piézométrique représente les lignes de même charge hydraulique (équipotentielles). Le flux souterrain est orthogonal aux équipotentielles (en milieu isotrope). La vitesse de Darcy q = -K × grad(h). Le gradient hydraulique entre deux points est I = Δh/L. La carte piézométrique permet d'identifier les zones de recharge (niveaux hauts), de décharge (niveaux bas = rivières, sources) et les directions d'écoulement dominant." }
        ]},
        { titre: "Bilan et alimentation des aquifères", sous_sections: [
          { titre: "Termes du bilan hydrogéologique", contenu: "Le bilan d'un aquifère s'écrit : Recharge (R) = Prélèvements (P) + Décharge naturelle (D) + Variation de stock (ΔS). La recharge provient des infiltrations directes (pluies efficaces), des transferts depuis les rivières (alimentation par la berge) et des apports latéraux. La décharge naturelle alimente les sources, les cours d'eau (débit de base) et l'évapotranspiration des zones saturées peu profondes. Les prélèvements par pompages constituent le terme anthropique." },
          { titre: "Variabilité saisonnière et tendances pluriannuelles", contenu: "Le niveau piézométrique fluctue saisonnièrement selon le régime de recharge. En zone tempérée : hautes eaux en hiver-printemps, basses eaux en été-automne. L'amplitude saisonnière est 1-2 m pour les grands aquifères, > 10 m pour les aquifères peu épais. Les tendances pluriannuelles de baisse piézométrique indiquent un déficit chronique (prélèvements > recharge). La France a subi des déficits piézométriques records en 2021-2023 dans les grandes nappes (Beauce, Alsace, Rhône-Alpes)." }
        ]}
      ],
      points: ["Aquifère libre : surface piézométrique libre. Captif : artésien. Semi-captif : drainance par aquitards.", "Transmissivité T = K × b (m²/s) = capacité de débit par unité de largeur.", "Coefficient S captif : 10⁻⁵ à 10⁻³. Libre : 5-30% (≈ porosité efficace).", "Drainance r' = K'/b' caractérise les transferts verticaux.", "Le modèle conceptuel (géologie + piézométrie + géochimie) précède tout modèle numérique.", "Les équipotentielles sont perpendiculaires aux lignes de courant en milieu isotrope.", "Bilan : Recharge = Prélèvements + Décharge + ΔS.", "Déficits piézométriques records en France 2021-2023.", "Aquifère karstique : triple porosité (pores + fractures + conduits).", "Porosité efficace ne < porosité totale n (eau retenue capillairement)."],
      formules: [
        { nom: "Loi de Darcy", expression: "q = -K × I = -K × (dh/dl)", variables: "q = vitesse de Darcy (m/s), K = conductivité hydraulique, I = gradient hydraulique" },
        { nom: "Transmissivité", expression: "T = K × b", variables: "b = épaisseur saturée de l'aquifère (m), T en m²/s" },
        { nom: "Coefficient d'emmagasinement captif", expression: "S = Ss × b = (ρg(α + nβ)) × b", variables: "Ss = compressibilité spécifique (m⁻¹), α = compressibilité de la matrice, β = eau" },
        { nom: "Drainance", expression: "r' = K' / b'", variables: "K' = conductivité hydraulique de l'aquitard, b' = épaisseur de l'aquitard" },
        { nom: "Vitesse réelle de l'eau souterraine", expression: "v = q / ne = -K × I / ne", variables: "ne = porosité efficace (cinématique), v = vitesse de transport des solutés" }
      ],
      retenir: "Le modèle conceptuel d'un aquifère identifie son type (libre/captif), ses paramètres (K, T, S), ses limites et ses bilans. La transmissivité T et l'emmagasinement S sont les deux paramètres clés des tests de pompage. La piézométrie cartographie les directions d'écoulement. Tout modèle numérique doit reposer sur un modèle conceptuel robuste construit à partir de données géologiques, hydrogéologiques et géochimiques."
    },
    exercices: [
      { id: 1, enonce: "Un aquifère alluvial a K = 5×10⁻³ m/s et une épaisseur saturée b = 12 m. Calculez T.", correction: "T = K × b = 5×10⁻³ × 12 = 6×10⁻² m²/s = 60 ×10⁻³ m²/s. Transmissivité élevée, aquifère très productif." },
      { id: 2, enonce: "Le gradient hydraulique entre deux piézomètres distants de 500 m est Δh = 1,8 m. K = 2×10⁻³ m/s. Calculez la vitesse de Darcy et la vitesse réelle (ne = 0,20).", correction: "I = 1,8/500 = 3,6×10⁻³. q = K×I = 2×10⁻³ × 3,6×10⁻³ = 7,2×10⁻⁶ m/s. v = q/ne = 7,2×10⁻⁶/0,20 = 3,6×10⁻⁵ m/s ≈ 3,1 m/j." },
      { id: 3, enonce: "Un aquifère captif a Ss = 2×10⁻⁵ m⁻¹ et b = 30 m. Calculez S et comparez à un aquifère libre de ne = 0,15.", correction: "S_captif = Ss × b = 2×10⁻⁵ × 30 = 6×10⁻⁴. S_libre ≈ ne = 0,15. L'aquifère libre relâche 250× plus d'eau par mètre de baisse piézométrique." },
      { id: 4, enonce: "Un aquitard de 5 m d'épaisseur a K' = 10⁻⁸ m/s. Calculez la drainance r' et estimez le flux vertical pour une différence de charge Δh = 3 m entre les deux aquifères.", correction: "r' = K'/b' = 10⁻⁸/5 = 2×10⁻⁹ s⁻¹. Flux q_v = K'/b' × Δh = 2×10⁻⁹ × 3 = 6×10⁻⁹ m/s = 0,19 mm/an. Très faible drainance, aquifère quasi-captif." },
      { id: 5, enonce: "Citez les 5 informations indispensables à un modèle conceptuel d'aquifère.", correction: "1. Géologie et stratigraphie (identification des aquifères et aquitards). 2. Piézométrie (niveaux statiques, fluctuations saisonnières). 3. Paramètres hydrodynamiques (K, T, S). 4. Limites du système (frontières imperméables, rivières, frontières à flux constant). 5. Termes de bilan (recharge, prélèvements, décharge naturelle)." },
      { id: 6, enonce: "Une carte piézométrique montre des équipotentielles convergeant vers une rivière. Que signifie-t-il ?", correction: "La rivière est une zone de décharge de la nappe (alimentation de la rivière par la nappe = nappe à décharge). C'est une rivière 'gagnante' hydrauliquement. En étiage, le débit de base de la rivière est soutenu par la nappe. Si les équipotentielles divergent depuis la rivière vers la nappe, la rivière alimente la nappe (rivière perdante)." },
      { id: 7, enonce: "Qu'est-ce que l'artésianisme et quelles en sont les conditions géologiques ?", correction: "L'artésianisme est la situation où la charge hydraulique d'un aquifère captif dépasse la cote du terrain : l'eau jaillit naturellement du forage. Conditions : aquifère captif incliné, zone de recharge à altitude plus élevée que la zone de forage, absence de fuite vers des aquifères inférieurs. Exemple : bassin de Paris (Jurassique captif), bassin Artois (d'où le nom)." },
      { id: 8, enonce: "Calculez la recharge annuelle d'un aquifère de 500 km² si le bilan montre : prélèvements 15 Mm³/an, décharge vers rivières 8 Mm³/an, baisse piézométrique 0,5 m/an, ne = 0,10.", correction: "ΔS = -ne × Δh × A = -0,10 × 0,5 × 500×10⁶ = -25 Mm³/an (baisse = déstockage). Bilan : R = P + D + ΔS = 15 + 8 + (-25) = -2 Mm³/an. La recharge est R = 15 + 8 - 25 = -2, soit une situation de déficit (recharge < prélèvements + décharge naturelle). Vérification : R doit être positif → erreur de raisonnement : R = P + D - ΔS (déstockage compense). R = 15 + 8 - 25 = -2 (déficit). Soit recharge naturelle = P + D - |ΔS déstockage| = 15 + 8 - 25 = -2 → situation impossible si R ≥ 0. La nappe est en déficit structural." }
    ],
    flashcards: [
      { question: "Différence entre aquifère libre et captif", reponse: "Libre : surface piézométrique libre, en contact avec la zone non saturée. S ≈ ne = 5-30%. Captif : entièrement saturé, confiné entre deux aquitards. S = Ss×b = 10⁻⁵ à 10⁻³. La baisse de charge en captif ne libère de l'eau que par compression (eau + matrice)." },
      { question: "Qu'est-ce que la transmissivité T ?", reponse: "T = K × b (m²/s). Capacité de l'aquifère à transmettre l'eau horizontalement par unité de largeur. T > 10⁻² m²/s : très bon aquifère. T < 10⁻⁵ m²/s : aquifère médiocre. Paramètre clé des tests de pompage." },
      { question: "Loi de Darcy : domaine de validité", reponse: "q = -K × grad(h). Valide pour les écoulements laminaires (Re = qd/ν < 1-10). Non valide : karst (écoulements turbulents), fissures très ouvertes. Dans les aquifères poreux classiques, la loi de Darcy est généralement respectée." },
      { question: "Qu'est-ce que la drainance ?", reponse: "r' = K'/b' (s⁻¹). Coefficient caractérisant les transferts verticaux à travers un aquitard semi-perméable. r' élevée → aquifère semi-captif avec échanges significatifs. r' très faible → aquifère quasi-captif. Modifie la réponse aux pompages sur le long terme." },
      { question: "Triple porosité des aquifères karstiques", reponse: "1. Porosité de matrice (pores intergranulaires). 2. Porosité de fractures (diaclases, failles). 3. Porosité de conduits (chenaux karstiques élargis par dissolution). Ces 3 porosités ont des conductivités très différentes (10⁻⁶ à 10² m/s). La réponse aux pompages est complexe et non-darcienne dans les conduits." },
      { question: "Composantes du bilan d'un aquifère", reponse: "Recharge (R) = infiltration directe + transferts depuis rivières + apports latéraux. Décharge (D) = sources + débit de base des rivières + ETP sur zones saturées. Prélèvements (P) = pompages. Bilan : R = P + D + ΔS. Surexploitation si R < P + D → baisse piézométrique chronique." }
    ]
  },

  'MASTER-EAU-040': {
    id: 'MASTER-EAU-040',
    titre: 'Propriétés hydrodynamiques des formations',
    fiche: {
      intro: "Les propriétés hydrodynamiques des aquifères (conductivité hydraulique K, transmissivité T, coefficient d'emmagasinement S) sont les paramètres centraux de toute modélisation hydrogéologique. Leur estimation par des méthodes de terrain (essais de pompage, essais de slug, corrélations pétrophysiques) et leur variabilité spatiale (hétérogénéité, anisotropie) conditionnent la fiabilité des modèles.",
      sections: [
        { titre: "Conductivité hydraulique et ses déterminants", sous_sections: [
          { titre: "Facteurs lithologiques et structuraux", contenu: "K dépend de la taille et de la forme des pores (loi de Kozeny-Carman : K ∝ d²n³/(1-n)²), de la tortuosité et de la connectivité du réseau poral. Dans les milieux granulaires, K varie de 10⁻¹⁰ m/s (argile) à 10⁻² m/s (gravier). La perméabilité intrinsèque k (m²) est indépendante du fluide : K = k × ρg/μ. Les fractures contribuent selon la loi cubique : K_frac = (a³ × g)/(12ν × L) où a est l'ouverture de la fracture. L'anisotropie (Kh >> Kv dans les sédiments) est fréquente." },
          { titre: "Variabilité spatiale et hétérogénéité", contenu: "K varie sur plusieurs ordres de grandeur même au sein d'une même formation (coefficient de variation CV > 100%). La distribution de K est généralement log-normale : ln(K) est approximativement gaussien. La conductivité effective pour les écoulements horizontaux est la moyenne géométrique Kgéo = exp(μlnK). La variabilité spatiale est décrite par le variogramme de lnK. La longueur de corrélation (portée du variogramme) varie de quelques mètres à plusieurs kilomètres selon la formation." }
        ]},
        { titre: "Méthodes d'estimation in situ", sous_sections: [
          { titre: "Essais de slug et bail test", contenu: "Le slug test introduit ou retire rapidement un volume d'eau dans un puits et enregistre le retour à l'équilibre. La méthode Bouwer-Rice analyse la récession et estime K directement. Le bail test consiste à pomper instantanément puis observer la remontée. Ces méthodes sont rapides et économiques mais mesurent K au voisinage immédiat du puits (1-10 m). Elles sont sensibles aux effets de puits (colmatage, enveloppe) et nécessitent une bonne connaissance de la géométrie du puits." },
          { titre: "Essais Lefranc et Lugeon", contenu: "L'essai Lefranc mesure K par injection ou absorption d'eau dans un trou de sonde sous charge constante : K = Q/(C × L × Δh) où C est un facteur de forme. L'essai Lugeon (Lugeon units, LU) mesure l'absorptivité hydraulique des roches fissurées : 1 LU = 1 L/min/m sous 1 MPa. Ces essais sont réalisés par tranche de 5 m de forage et permettent de profiler la perméabilité verticale. 1 LU ≈ 10⁻⁷ m/s en ordre de grandeur." }
        ]},
        { titre: "Approches géostatistiques et modélisation stochastique", sous_sections: [
          { titre: "Simulation stochastique des champs de K", contenu: "La simulation stochastique génère des réalisations équiprobables de la distribution spatiale de K respectant les observations aux forages et le variogramme modélisé. Les méthodes séquentielles gaussiennes (SGS) ou par retournement de gaussiennes (TGS) produisent des champs de K géologiquement plausibles. Chaque réalisation peut être utilisée dans un modèle d'écoulement, produisant un ensemble de simulations qui quantifient l'incertitude liée à l'hétérogénéité de K. Cette approche est l'état de l'art pour les études de transport de contaminants." },
          { titre: "Pédo-transfert et corrélations pétrophysiques", contenu: "En l'absence d'essais, les corrélations pétrophysiques (Hazen : K = C×d₁₀², Kozeny-Carman) estiment K à partir de la granulométrie. ROSETTA est le logiciel de référence pour les sols. Les corrélations avec les carottes sismiques (impédance acoustique) et les diagraphies (gamma-ray, neutron-densité) permettent de relier les propriétés hydrauliques aux mesures géophysiques. Ces approches sont utiles pour régionaliser K entre les forages." }
        ]},
        { titre: "Anisotropie et tenseur de conductivité", sous_sections: [
          { titre: "Tenseur de conductivité hydraulique", contenu: "Dans un milieu anisotrope, la loi de Darcy s'écrit vectoriellement : q = -K̲ × grad(h) où K̲ est le tenseur symétrique de conductivité. Dans les repères principaux, K̲ = diag(Kx, Ky, Kz). Pour les sédiments stratifiés, Kh (horizontal) >> Kv (vertical), avec Kh/Kv de 10 à 1000. Cette anisotropie est critique pour modéliser les échanges verticaux et la propagation des contaminants denses (DNAPLs qui s'enfoncent selon Kv)." },
          { titre: "Représentativité des mesures et changement d'échelle", contenu: "L'essai de pompage mesure K à l'échelle de quelques dizaines à centaines de mètres (zone d'influence du puits). Les corrélations granulométriques mesurent K à l'échelle du centimètre. Ces différentes échelles de mesure ne sont pas directement comparables (changement d'échelle, up-scaling). La règle générale est que la moyenne géométrique de K mesurée en laboratoire sous-estime K effectif à grande échelle (car les chemins préférentiels sont absents dans les petits échantillons)." }
        ]}
      ],
      points: ["K varie de 10⁻¹⁰ m/s (argile) à 10⁻² m/s (gravier). Distribution log-normale.", "Loi de Kozeny-Carman : K ∝ d²n³/(1-n)². Loi de Hazen : K = C × d₁₀².", "Loi cubique pour les fractures : K_frac ∝ a³ (ouverture de fracture).", "Slug test (Bouwer-Rice) : mesure locale de K dans le voisinage du puits.", "1 LU (Lugeon) ≈ 10⁻⁷ m/s. Test d'absorptivité dans les roches fracturées.", "SGS génère des champs de K stochastiques respectant le variogramme.", "Kh/Kv de 10 à 1000 dans les sédiments stratifiés (anisotropie).", "Kgéo = exp(moyenne de lnK) est la conductivité effective pour les flux horizontaux.", "Le changement d'échelle (up-scaling) est un défi majeur en hydrogéologie.", "ROSETTA estime K des sols à partir de la texture et de la densité apparente."],
      formules: [
        { nom: "Loi de Hazen", expression: "K = C × d₁₀²", variables: "d₁₀ = diamètre efficace (cm), C = 100-150 cm⁻¹s⁻¹ pour sable propre, K en cm/s" },
        { nom: "Loi de Kozeny-Carman", expression: "K = (ρg/μ) × (d²/180) × n³/(1-n)²", variables: "d = diamètre moyen des grains, n = porosité, ρ = densité eau, μ = viscosité dynamique" },
        { nom: "Loi cubique (fractures)", expression: "K_frac = (a² × g) / (12ν)", variables: "a = ouverture de la fracture (m), ν = viscosité cinématique (m²/s)" },
        { nom: "Loi de Darcy anisotrope (tenseur)", expression: "q = -K̲ · grad(h)", variables: "K̲ = tenseur 3×3 de conductivité hydraulique. Diagonalisable en repères principaux." },
        { nom: "Conductivité effective (milieu hétérogène, flux horizontal)", expression: "Keff = exp(μlnK + σ²lnK/2 × (1 - 2/d))", variables: "μlnK = moyenne de lnK, σ²lnK = variance, d = dimension (2D ou 3D)" }
      ],
      retenir: "K est le paramètre clé des aquifères, variable sur 10 ordres de grandeur et de distribution log-normale. Les méthodes in situ (essais de pompage, slug, Lugeon) mesurent K à différentes échelles. La simulation stochastique représente l'incertitude spatiale. L'anisotropie Kh >> Kv est quasi-universelle dans les sédiments stratifiés. Le changement d'échelle (up-scaling vers les modèles) reste un défi méthodologique central."
    },
    exercices: [
      { id: 1, enonce: "Un sable a d₁₀ = 0,15 mm = 0,015 cm. Estimez K par la formule de Hazen (C = 120 cm⁻¹s⁻¹).", correction: "K = 120 × (0,015)² = 120 × 2,25×10⁻⁴ = 0,027 cm/s = 2,7×10⁻⁴ m/s. Sable moyen à haute conductivité." },
      { id: 2, enonce: "Une fracture a une ouverture a = 0,5 mm = 5×10⁻⁴ m et ν = 10⁻⁶ m²/s. Calculez la conductivité hydraulique de la fracture.", correction: "K_frac = a²g/(12ν) = (5×10⁻⁴)² × 9,81/(12 × 10⁻⁶) = 2,5×10⁻⁷ × 9,81/1,2×10⁻⁵ = 2,45×10⁻⁶/1,2×10⁻⁵ = 0,204 m/s. Fracture très conductrice." },
      { id: 3, enonce: "10 mesures de log₁₀(K) sur un transect donnent : -4,2; -3,8; -5,1; -4,0; -3,5; -4,8; -4,1; -3,9; -4,3; -4,7. Calculez la conductivité géométrique effective.", correction: "Moyenne de log₁₀(K) = (-4,2-3,8-5,1-4,0-3,5-4,8-4,1-3,9-4,3-4,7)/10 = -42,4/10 = -4,24. Kgéo = 10^(-4,24) = 5,75×10⁻⁵ m/s." },
      { id: 4, enonce: "L'essai Lugeon d'une roche calcaire donne 15 LU à une profondeur de 50 m. Estimez K en m/s.", correction: "1 LU ≈ 10⁻⁷ m/s. K ≈ 15 × 10⁻⁷ = 1,5×10⁻⁶ m/s. Roche faiblement fracturée mais avec quelques fractures conductrices. Travaux de consolidation par injection ciment recommandés (< 3 LU pour des barrages)." },
      { id: 5, enonce: "Un aquifère a Kh = 5×10⁻³ m/s et Kh/Kv = 50. Calculez Kv et estimez si un polluant dense peut atteindre une nappe sous-jacente en 10 ans à travers 20 m d'aquifère.", correction: "Kv = 5×10⁻³/50 = 10⁻⁴ m/s. Gradient vertical i = 1 (cas extrême). Vitesse Darcy = 10⁻⁴ m/s. Avec ne = 0,25 : v = 4×10⁻⁴ m/s = 12,6 km/an. 20 m en 20/12600 = 0,0016 an ≈ 0,6 jour. Oui, un polluant dense peut atteindre rapidement une nappe sous-jacente (bien que le gradient vertical réel soit bien inférieur à 1)." },
      { id: 6, enonce: "Expliquez pourquoi la mesure de K au laboratoire sur carotte sous-estime généralement K mesurable par essai de pompage.", correction: "Le laboratoire mesure K sur un échantillon de quelques cm (pores inter-granulaires uniquement, sans fractures ni macrostructures). L'essai de pompage intègre les hétérogénéités à l'échelle de quelques dizaines à centaines de mètres, incluant les fractures et chenaux préférentiels qui contribuent fortement à K effectif. La moyenne géométrique à grande échelle est donc supérieure à la moyenne des mesures ponctuelles en laboratoire." },
      { id: 7, enonce: "Qu'est-ce que la simulation stochastique séquentielle gaussienne (SGS) et à quoi sert-elle ?", correction: "SGS génère des champs de K spatialement corrélés respectant : les données aux forages, le variogramme de lnK modélisé, et la distribution statistique (log-normale). Chaque réalisation est un champ de K possible. L'ensemble des réalisations quantifie l'incertitude liée à l'hétérogénéité. Utilisée pour : simulation du transport de polluants (quantifier l'incertitude du panache), conception de réseaux de surveillance." },
      { id: 8, enonce: "Pourquoi l'anisotropie Kh >> Kv est-elle quasi-universelle dans les sédiments marins ou fluviaux ?", correction: "Le dépôt sédimentaire stratifié crée des couches d'alternance granulométrique (sables fins/grossiers, argiles/sables). Les perméabilités élevées sont horizontales (par les couches grossières continues). Verticalement, les couches argileuses discontinues créent des barrières et dominent Kv (K harmonie pour les flux série). La règle K horizontal = K arithmétique >> K vertical = K harmonique justifie Kh/Kv >> 1." }
    ],
    flashcards: [
      { question: "Loi de Hazen pour estimer K", reponse: "K = C × d₁₀² (C ≈ 100-150 cm⁻¹s⁻¹). d₁₀ = diamètre à 10% de la courbe granulométrique (diamètre efficace). Valide pour les sables propres. Donne K en cm/s. Simple et rapide à partir d'une analyse granulométrique." },
      { question: "Loi cubique des fractures", reponse: "K_frac = a²g/(12ν). La conductivité croît avec le carré de l'ouverture a. Une fracture de 1 mm a K ≈ 0,1 m/s, de 0,1 mm → K ≈ 10⁻³ m/s. L'ouverture est le paramètre le plus influent, expliquant la variabilité extrême de K dans les milieux fracturés." },
      { question: "Qu'est-ce que l'essai Lugeon ?", reponse: "Test d'absorptivité hydraulique par injection d'eau sous pression dans des tronçons de forage. 1 LU = 1 L/min/m/MPa ≈ 10⁻⁷ m/s. < 1 LU : pratiquement imperméable (barrage possible). > 10 LU : traitement par injection nécessaire. Profil de perméabilité verticale tous les 5 m." },
      { question: "Conductivité effective en milieu hétérogène", reponse: "Pour les flux horizontaux : Keff ≈ Kgéo = exp(μlnK). Pour les flux verticaux (couches en série) : Keff = K harmonique << Kgéo. L'anisotropie apparente d'un milieu hétérogène résulte de cette différence entre K arithmetic (H) et K harmonic (V)." },
      { question: "Slug test vs essai de pompage : différences", reponse: "Slug test : perturbation instantanée, récession vers l'équilibre. Rapide, local (1-10 m). Bouwer-Rice. Essai de pompage : pompage prolongé, analyse du rabattement. Représentatif de quelques dizaines à centaines de mètres. Plus fiable pour T et S. Les deux sont complémentaires." },
      { question: "Distribution de K et implications", reponse: "K est log-normalement distribué : ln(K) gaussien. Quelques valeurs très élevées dominent la moyenne arithmétique. La moyenne géométrique représente mieux le comportement effectif. Coefficient de variation CV > 100% typique. Un seul forage ne représente pas l'aquifère." }
    ]
  },

  'MASTER-EAU-041': {
    id: 'MASTER-EAU-041',
    titre: "Équations de l'écoulement souterrain",
    fiche: {
      intro: "Les équations gouvernant l'écoulement souterrain découlent de la combinaison de la loi de conservation de la masse et de la loi de Darcy. Leur résolution analytique n'est possible que pour des géométries simples, mais elles constituent le fondement de tous les modèles numériques d'aquifères. La maîtrise de ces équations est indispensable pour interpréter les tests de pompage et dimensionner les exploitations.",
      sections: [
        { titre: "Équation de diffusivité (aquifère captif)", sous_sections: [
          { titre: "Dérivation et signification physique", contenu: "En combinant la loi de Darcy et la conservation de la masse pour un aquifère captif, on obtient l'équation de diffusivité hydraulique : T × ∇²h = S × ∂h/∂t. Elle est formellement analogue à l'équation de diffusion thermique. Le rapport T/S est la diffusivité hydraulique D (m²/s), qui gouverne la vitesse de propagation des perturbations de charge. D grand → la perturbation se propage rapidement (aquifère réactif). La solution de Theis (1935) résout cette équation pour un pompage en régime transitoire." },
          { titre: "Solutions analytiques de base", contenu: "La solution de Theis pour un pompage Q en milieu infini, en régime transitoire : s(r,t) = Q/(4πT) × W(u) avec u = r²S/(4Tt), W(u) = ∫[u→∞] e⁻ᵘ/u du. Pour u < 0,05 (Cooper-Jacob) : s ≈ Q/(4πT) × [ln(2,25Tt/r²S)]. Ces formules permettent d'estimer T et S à partir des mesures de rabattement dans des piézomètres d'observation." }
        ]},
        { titre: "Aquifère libre et équation de Boussinesq", sous_sections: [
          { titre: "Équation de Boussinesq non-linéaire", contenu: "Pour un aquifère libre, l'épaisseur saturée h est variable et l'équation devient non-linéaire : ∂(h×∂h/∂x)/∂x + ∂(h×∂h/∂y)/∂y = (ne/K) × ∂h/∂t - R/K. La linéarisation par la transformation de Dupuit (h ≈ h₀ + s, s << h₀) conduit à l'équation de diffusion classique avec T = K×h₀ et S = ne. Cette approximation est valide si les rabattements restent petits devant l'épaisseur initiale (s/h₀ < 0,25)." },
          { titre: "Flux vers les puits : équation de Theis vs Hantush-Jacob", contenu: "Pour un aquifère semi-captif (Hantush-Jacob), la drainance de l'aquitard modifie la solution analytique. Le facteur de drainance B = √(T/r') conditionne la portée de l'influence. Pour r >> B, le régime se stabilise grâce à la drainance. La solution de Hantush W(u,r/B) généralise la fonction de puits de Theis. Ces solutions analytiques sont utilisées pour l'analyse des essais de pompage multi-puits." }
        ]},
        { titre: "Méthodes de résolution numérique", sous_sections: [
          { titre: "Méthode des différences finies (MODFLOW)", contenu: "MODFLOW (McDonald & Harbaugh, USGS) est le code de modélisation des eaux souterraines le plus utilisé. Il discrétise l'équation de diffusivité sur une grille régulière (différences finies centrées) avec des blocs de cellules. La résolution est implicite (Crank-Nicolson ou fully implicit). MODFLOW utilise des packages pour représenter les puits, les rivières (RIV), la recharge (RCH), le drainage (DRN) et l'évapotranspiration (EVT). La version MODFLOW 6 est la référence actuelle." },
          { titre: "Méthode des éléments finis et éléments analytiques", contenu: "La méthode des éléments finis (FEFlow, FEFLOW, FEMWATER) utilise un maillage triangulaire non structuré, plus adapté aux frontières complexes et à la concentration de maillage. Elle résout les équations en forme faible par fonctions de forme. La méthode des éléments analytiques (MODAEM, GFLOW) superpose des solutions analytiques élémentaires (puits, rivières, frontières) : élégante pour les aquifères régionaux 2D avec frontières simples. Chaque méthode a ses domaines d'excellence." }
        ]},
        { titre: "Conditions aux limites et termes sources", sous_sections: [
          { titre: "Types de conditions aux limites", contenu: "Les conditions aux limites sont : Dirichlet (charge imposée h = h₀ : rivière, lac, frontière imperméable lointaine), Neumann (flux imposé ∂h/∂n = q : recharge, frontière imperméable si q=0), Cauchy (relation mixte flux-charge : drainance, échange rivière-nappe). Le choix des conditions aux limites est crucial : une mauvaise condition biaise toutes les simulations. Les limites Dirichlet sont numériquement stables mais peuvent créer des sources/puits artificiels non physiques." },
          { titre: "Termes sources et puits dans MODFLOW", contenu: "MODFLOW représente explicitement les puits (package WEL : débit imposé Q), la recharge diffuse (RCH : flux par unité de surface), les rivières (RIV : échange head-dépendant avec ψ(h-riv) si h > rbot, 0 sinon), le drainage (DRN : flux proportionnel à h-dalt si h > dalt), et l'ET (EVT). Ces termes sont intégrés dans la matrice d'équations. La résolution est itérative (SIP, PCG, GMG) pour les systèmes non-linéaires (aquifère libre)." }
        ]}
      ],
      points: ["Équation de diffusivité captif : T∇²h = S∂h/∂t. Paramètre T/S = diffusivité.", "Solution de Theis : s = Q/(4πT) × W(u), u = r²S/(4Tt).", "Approximation de Cooper-Jacob valide si u < 0,05.", "Équation de Boussinesq (aquifère libre) : non-linéaire car T = K×h(x,y,t).", "MODFLOW (USGS) : code de référence mondial en différences finies.", "FEFlow/FEM : maillage non-structuré, adapté aux frontières complexes.", "Conditions Dirichlet (h imposé), Neumann (flux imposé), Cauchy (mixte).", "Facteur de drainance B = √(T/r') dans les aquifères semi-captifs.", "Hantush-Jacob généralise Theis aux aquifères semi-captifs.", "MODFLOW 6 est la version de référence actuelle (USGS)."],
      formules: [
        { nom: "Équation de diffusivité (aquifère captif, 2D)", expression: "T(∂²h/∂x² + ∂²h/∂y²) = S × ∂h/∂t - R", variables: "T = transmissivité, S = emmagasinement, h = charge hydraulique, R = recharge" },
        { nom: "Solution de Theis (puits en milieu infini)", expression: "s(r,t) = Q/(4πT) × W(u),  u = r²S/(4Tt)", variables: "s = rabattement (m), Q = débit de pompage (m³/s), W(u) = fonction de puits" },
        { nom: "Approximation de Cooper-Jacob (u < 0,05)", expression: "s = Q/(4πT) × [ln(2.25Tt / r²S)]", variables: "Valide après un temps suffisamment long ou pour de faibles r" },
        { nom: "Facteur de drainance (aquifère semi-captif)", expression: "B = √(T/r') = √(T × b'/K')", variables: "r' = K'/b' = conductance de l'aquitard, B en mètres" },
        { nom: "Équation de Dupuit (aquifère libre, 1D)", expression: "K × d(h × dh/dx)/dx + R = ne × dh/dt", variables: "h = niveau piézométrique = épaisseur saturée, R = recharge" }
      ],
      retenir: "L'équation de diffusivité T∇²h = S∂h/∂t est le fondement de la modélisation des aquifères captifs. La solution de Theis permet d'estimer T et S par les tests de pompage. Les aquifères libres obéissent à l'équation de Boussinesq non-linéaire. MODFLOW (différences finies) est le code de référence. La définition correcte des conditions aux limites et des termes sources est aussi importante que la résolution numérique."
    },
    exercices: [
      { id: 1, enonce: "Un aquifère captif a T = 8×10⁻³ m²/s, S = 4×10⁻⁴. Un puits pompe Q = 0,05 m³/s. Calculez u et s à r = 100 m et t = 24h = 86400 s. W(u=0,07) ≈ 2,03.", correction: "u = r²S/(4Tt) = 100²×4×10⁻⁴/(4×8×10⁻³×86400) = 4/(2764,8) = 1,45×10⁻³. u << 0,05 → Cooper-Jacob applicable. s = Q/(4πT)×ln(2,25Tt/r²S) = 0,05/(4π×8×10⁻³)×ln(2,25×8×10⁻³×86400/100²×4×10⁻⁴) = 0,497×ln(1554) = 0,497×7,35 = 3,65 m." },
      { id: 2, enonce: "Après 1000 m de pompage continu, la courbe s = f(log t) donne une pente Δs/Δlog(t) = 0,52 m (Cooper-Jacob). Q = 0,02 m³/s. Calculez T.", correction: "Cooper-Jacob : s = Q/(4πT) × 2,303 × log(2,25Tt/r²S). Pente = Q×2,303/(4πT) = 0,52. T = Q×2,303/(4π×0,52) = 0,02×2,303/6,534 = 0,0461/6,534 = 7,06×10⁻³ m²/s." },
      { id: 3, enonce: "Expliquez pourquoi l'équation de Boussinesq est non-linéaire et quelle est la condition de validité de sa linéarisation.", correction: "Non-linéaire car T = K×h varie dans le temps et l'espace (l'épaisseur saturée h change avec le pompage). La linéarisation (T ≈ K×h₀) est valide si s/h₀ < 0,25 (rabattement < 25% de l'épaisseur initiale). Au-delà, l'erreur sur T croît et il faut corriger le rabattement : s_corrigé = s_observé - s²/(2h₀) (correction de Jacob)." },
      { id: 4, enonce: "MODFLOW utilise le package RIV pour simuler les échanges rivière-nappe. Expliquez la logique du terme source RIV.", correction: "QRIV = CRIV × (hriv - h) si h > rbot (fond de rivière). QRIV = CRIV × (hriv - rbot) si h ≤ rbot (décollement). CRIV = Krivière × L × W / b (conductance de l'interface). Ce terme représente l'échange bidirectionnel : positif → la rivière alimente la nappe, négatif → la nappe alimente la rivière." },
      { id: 5, enonce: "Calculez le facteur de drainance B pour T = 5×10⁻³ m²/s et un aquitard de K' = 10⁻⁸ m/s, b' = 3 m.", correction: "r' = K'/b' = 10⁻⁸/3 = 3,33×10⁻⁹ s⁻¹. B = √(T/r') = √(5×10⁻³/3,33×10⁻⁹) = √(1,5×10⁶) = 1225 m. B = 1,2 km. L'influence du pompage se propage jusqu'à ~1,2 km avant d'être limitée par la drainance." },
      { id: 6, enonce: "Quels sont les avantages de la méthode des éléments finis (FEM) sur les différences finies (FDF) pour la modélisation des aquifères ?", correction: "FEM : maillage non structuré → adaptation aux frontières courbes (côtes, failles). Raffinement local facile (autour des puits, zones contaminées). Plus précis pour les géométries complexes. FDF (MODFLOW) : plus simple à mettre en œuvre, grille régulière, bibliothèque de packages étendue, communauté utilisateurs plus large. FEM préférable en géométries complexes, FDF en aquifères régionaux à géométrie simple." },
      { id: 7, enonce: "Qu'est-ce qu'une condition aux limites de Cauchy et donnez un exemple hydrogéologique.", correction: "Condition Cauchy (ou Robin) : relation linéaire entre le flux et la charge à la frontière : q = C × (h_ext - h). Exemples : échange nappe-rivière (flux proportionnel à la différence de charge), drainance par un aquitard (flux = r' × (h_nappe_sup - h)), fontaines ou drains (flux proportionnel à la charge si h > seuil). Plus réaliste que Dirichlet ou Neumann car représente une résistance de l'interface." },
      { id: 8, enonce: "Un aquifère libre est pompé à 0,05 m³/s. Après 1 mois, le rabattement maximal est 4 m dans un aquifère initialement saturé sur 15 m. La correction de Jacob est-elle nécessaire ?", correction: "s/h₀ = 4/15 = 0,267 ≈ 27% > 25%. La correction de Jacob est nécessaire. s_corrigé = 4 - 4²/(2×15) = 4 - 0,53 = 3,47 m. Sans correction, T serait sous-estimé. La correction est : s_corrigé = s_obs - s²_obs/(2h₀)." }
    ],
    flashcards: [
      { question: "Équation de diffusivité hydraulique et paramètre clé", reponse: "T∇²h = S∂h/∂t. Diffusivité hydraulique D = T/S (m²/s). D grand → perturbations de charge se propagent rapidement. Analogie exacte avec l'équation de diffusion thermique." },
      { question: "Solution de Theis : paramètres et domaine de validité", reponse: "s = Q/(4πT)×W(u), u = r²S/(4Tt). Hypothèses : aquifère homogène, isotrope, infini, captif, puits parfait. Valide en régime transitoire avant atteinte des frontières. Cooper-Jacob (u<0,05) est l'approximation linéaire logarithmique." },
      { question: "Qu'est-ce que MODFLOW ?", reponse: "Code de modélisation des eaux souterraines par différences finies (USGS, depuis 1984). Grille rectangulaire, résolution implicite. Packages : WEL, RIV, RCH, DRN, EVT. MODFLOW 6 : version actuelle. Standard mondial de facto. Open source. Interface avec GIS (ModelMuse, FloPy)." },
      { question: "Condition de Cooper-Jacob (u < 0,05)", reponse: "W(u) ≈ -0,5772 - ln(u) pour u < 0,05. Donne s ≈ Q/(4πT)×ln(2,25Tt/r²S). Valide après temps suffisant (t > 25r²S/T) ou à faible distance du puits. Permet l'analyse graphique : s = f(log t) donne une droite de pente Q/(4πT)×2,303." },
      { question: "Facteur de drainance B dans un aquifère semi-captif", reponse: "B = √(T/r') = √(T×b'/K'). Rayon d'influence de la drainance. Pour r << B : réponse comme aquifère captif. Pour r >> B : régime permanent établi par la drainance. Hantush W(u,r/B) généralise Theis." },
      { question: "Types de conditions aux limites en MODFLOW", reponse: "Dirichlet : charge imposée (CH : Constant Head). Neumann : flux nul sur frontière imperméable (par défaut). Cauchy : échange head-dépendant (RIV, DRN, GHB). Le choix des CL est aussi important que les paramètres : une CL Dirichlet mal placée crée des artefacts numériques." }
    ]
  },

  'MASTER-EAU-042': {
    id: 'MASTER-EAU-042',
    titre: "Piézométrie et réseaux d'observation",
    fiche: {
      intro: "La piézométrie est la mesure et le suivi des charges hydrauliques dans les aquifères. Les réseaux de piézomètres fournissent les données fondamentales pour la gestion des eaux souterraines, la détection des tendances et le calage des modèles. L'instrumentation moderne (capteurs de pression communicants, systèmes télémesure) a transformé le suivi des nappes en outil de gestion en temps réel.",
      sections: [
        { titre: "Mesure et instrumentation piézométrique", sous_sections: [
          { titre: "Capteurs de pression et enregistreurs autonomes", contenu: "Les capteurs de pression piézorésistifs ou à jauge de contrainte mesurent la pression de l'eau avec une précision de 1-5 mm d'eau. Les data loggers autonomes (Solinst, Schlumberger Mini-Diver) enregistrent le niveau à pas de temps programmable (1 min à 1 h), avec une autonomie de 1-5 ans. La correction barométrique est indispensable pour les piézomètres captifs : les variations de pression atmosphérique sont enregistrées par un logger baro et soustraites. L'efficacité barométrique BE = Δh/Δatm renseigne sur la compressibilité de l'aquifère." },
          { titre: "Méthodes de mesure directe et télémesure", contenu: "La mesure manuelle par sonde électrique (contact électrique eau-sonde) est la référence de terrain (précision 5-10 mm). Les systèmes télémesure (GSM/4G, LoRaWAN, Sigfox) transmettent les données en temps réel vers des serveurs centraux. Les réseaux nationaux (ADES en France, NWIS aux USA) centralisent les données piézométriques publiques. La mesure acoustique (sonde acoustique) est utilisée pour les puits tubés ou très profonds (> 100 m). Les fibres optiques (DTS) permettent des profils de température continus qui renseignent sur les flux thermiques et les échanges nappe-rivière." }
        ]},
        { titre: "Réseaux de surveillance et conception", sous_sections: [
          { titre: "Conception d'un réseau piézométrique", contenu: "Un réseau piézométrique est conçu pour répondre à des objectifs précis : surveillance de l'état quantitatif (niveaux et tendances), calage de modèles, détection de contamination, gestion de captages. La densité de points dépend de la variabilité spatiale (variogramme de h). Pour les grands aquifères stratégiques (Beauce, Crau), 1 piézomètre par 50-100 km² est typique. Les points existants (forages d'eau, puits agricoles) sont souvent instrumentés pour réduire les coûts. La représentativité hydrologique (zone non saturée vs saturée, forages équipés à la bonne nappe) est critique." },
          { titre: "Bases de données nationales (ADES, BSS)", contenu: "La banque de données sous-sol (BSS France) recense plus de 500 000 forages et ouvrages. ADES (Accès aux Données sur les Eaux Souterraines, BRGM) centralise les mesures piézométriques de plus de 3 000 points de surveillance. Ces données sont librement accessibles en ligne. L'European Groundwater Watch (EGW) agrège les données nationales européennes pour le suivi des aquifères transfrontaliers (Rhine, Danube, Chalk). Ces bases permettent la détection des tendances à long terme et l'évaluation de l'état quantitatif au sens de la DCE." }
        ]},
        { titre: "Analyse piézométrique et tendances", sous_sections: [
          { titre: "Courbes de tendance et tests statistiques", contenu: "Les séries piézométriques présentent des variations saisonnières, des variations interannuelles et des tendances à long terme. La décomposition saisonnière (médiane mensuelle) distingue la variabilité normale de la tendance. Le test de Mann-Kendall est appliqué aux anomalies piézométriques pour détecter les tendances significatives. Des baisses piézométriques de 0,5-2 m/décennie sont observées dans les principaux aquifères français en situation de surexploitation ou de déficit de recharge lié au changement climatique." },
          { titre: "Cartes piézométriques régionales et SIG", contenu: "Les cartes piézométriques régionales sont produites par interpolation spatiale (krigeage ordinaire, krigeage avec dérive externe utilisant le MNT comme auxiliaire). Elles représentent l'état à une date de référence (étiage ou hautes eaux). La différence entre deux cartes piézométriques (ΔN = N2 - N1) donne la carte de variation du niveau, proportionnelle à la variation de stock. La superposition avec les limites des ZPF (Zones à Préserver pour le Futur) guide les décisions de politique de l'eau." }
        ]},
        { titre: "Interactions nappe-atmosphère et marées terrestres", sous_sections: [
          { titre: "Efficacité barométrique et compressibilité", contenu: "La réponse d'un aquifère captif aux variations de pression atmosphérique est caractérisée par l'efficacité barométrique BE = -Δh/ΔPa (sans dimension). BE = Ss_eau/(Ss_eau + Ss_matrice) ≈ 0,3-0,8 pour les aquifères captifs. L'analyse de BE fournit une estimation de la compressibilité de l'aquifère. Les variations piézométriques liées aux marées terrestres (soulèvement élastique de la croûte) permettent d'estimer S in situ sans pompage." },
          { titre: "Effet des précipitations et recharge indirecte", contenu: "Dans les aquifères libres, les précipitations créent des oscillations piézométriques rapides (< 1 h) par effet de charge (poids de la colonne d'eau dans la zone non saturée comprime la nappe) puis une recharge progressive (1-30 jours). La déconvolution de la réponse piézométrique aux précipitations (réponse impulsionnelle, analyse spectrale) estime la recharge et la résidence dans la zone non saturée. Ces analyses sont utiles pour la détection précoce des contaminations et la gestion des ZPPE (Zones de Protection des Périmètres d'alimentation des captages)." }
        ]}
      ],
      points: ["Capteurs Mini-Diver : précision 1-5 mm, autonomie 1-5 ans.", "Correction barométrique obligatoire pour piézomètres captifs.", "ADES (France) : 3000 piézomètres en temps réel, données libres.", "BSS France : 500 000 forages et ouvrages référencés.", "Mann-Kendall sur anomalies piézométriques détecte les tendances.", "Efficacité barométrique BE = -Δh/ΔPa caractérise la compressibilité.", "Krigeage des niveaux piézométriques pour cartes régionales.", "1 piézomètre par 50-100 km² pour les grands aquifères stratégiques.", "Baisses piézométriques de 0,5-2 m/décennie observées en surexploitation.", "LoRaWAN et 4G permettent la télémesure en temps réel des niveaux."],
      formules: [
        { nom: "Efficacité barométrique", expression: "BE = -Δh / ΔPa", variables: "Δh = variation du niveau piézométrique (m), ΔPa = variation de pression atmosphérique (m d'eau). BE ∈ [0,1]" },
        { nom: "Correction barométrique", expression: "h_corrigé = h_mesuré + BE × Pa", variables: "Pa = pression atmosphérique normalisée (m d'eau), BE = efficacité barométrique" },
        { nom: "Variation de stock par carte piézométrique", expression: "ΔV = Sy × A × ΔN  (aquifère libre)", variables: "Sy = rendement spécifique, A = superficie (m²), ΔN = variation du niveau piézométrique (m)" },
        { nom: "Gradient hydraulique régional", expression: "I = (h₁ - h₂) / L", variables: "h₁, h₂ = charges aux points 1 et 2 (m NGF), L = distance (m)" },
        { nom: "Estimation de la recharge par fluctuation piézométrique (WTF)", expression: "R = Sy × ΔN / Δt", variables: "Sy = rendement spécifique, ΔN = montée piézométrique suite à un événement, Δt = durée" }
      ],
      retenir: "La piézométrie est l'outil de base du suivi des eaux souterraines. Les réseaux nationaux (ADES, BSS) fournissent des données précieuses pour la détection des tendances et le calage des modèles. L'instrumentation moderne (data loggers, télémesure) permet un suivi en temps réel. La correction barométrique est indispensable en aquifère captif. Les cartes piézométriques interpolées par krigeage guident la gestion quantitative des aquifères."
    },
    exercices: [
      { id: 1, enonce: "Un piézomètre dans un aquifère captif montre une montée de 0,015 m lors d'une baisse de pression atmosphérique de 0,025 m d'eau. Calculez BE.", correction: "BE = -Δh/ΔPa = -(-0,015)/(-0,025). Attention : une baisse de Pa fait monter h (pression atm. réduite → charge hydraulique augmente). BE = 0,015/0,025 = 0,60. Aquifère captif à compressibilité modérée." },
      { id: 2, enonce: "Un aquifère libre de Sy = 0,12 voit son niveau monter de 0,8 m sur 200 km². Calculez la variation de stock en Mm³.", correction: "ΔV = Sy × A × ΔN = 0,12 × 200×10⁶ × 0,8 = 19,2×10⁶ m³ = 19,2 Mm³." },
      { id: 3, enonce: "Le test de Mann-Kendall sur 30 ans d'anomalies piézométriques d'un point ADES donne Z = -2,45 (Zcrit = 1,96 à 5%). Interprétez.", correction: "Z = -2,45 < -1,96 → tendance négative significative au seuil 5% (p ≈ 0,014). Le niveau piézométrique a tendance à baisser significativement sur 30 ans. Possible surexploitation ou déficit de recharge climatique. Nécessite investigation complémentaire (prélèvements, bilan)." },
      { id: 4, enonce: "Citez 3 sources d'erreur dans la mesure du niveau piézométrique par Mini-Diver.", correction: "1. Dérive du zéro du capteur (± 1-2 mm/mois, nécessite calibration annuelle). 2. Effet barométrique non corrigé (fluctuations jusqu'à 10-20 mm dans les aquifères captifs). 3. Erreur de référence altimétrique (repère de mesure mal nivelé, cote NGF approchée)." },
      { id: 5, enonce: "Deux piézomètres distants de 2500 m ont des cotes piézométriques de 85,3 m NGF et 83,7 m NGF. Calculez le gradient hydraulique et la direction d'écoulement.", correction: "I = (85,3 - 83,7)/2500 = 1,6/2500 = 6,4×10⁻⁴. L'écoulement va du piézomètre à cote 85,3 vers celui à cote 83,7. Direction donnée par la ligne qui relie les deux points, perpendiculaire aux équipotentielles." },
      { id: 6, enonce: "Expliquez pourquoi les données piézométriques de forages agricoles non équipés d'un logger peuvent introduire des biais dans l'analyse des tendances.", correction: "Les forages agricoles sont mesurés irrégulièrement (lors des passages de terrain, souvent liés aux opérations d'irrigation). Cette mesure non aléatoire crée un biais : on mesure souvent en période d'étiage (pompage intense, niveaux bas) → la série est biaisée vers les niveaux bas. Les tendances calculées peuvent sur-estimer la baisse. Les data loggers permettent une mesure continue non biaisée." },
      { id: 7, enonce: "Qu'est-ce qu'ADES et comment l'utiliser pour évaluer l'état quantitatif d'un aquifère ?", correction: "ADES (Accès aux Données Eaux Souterraines, BRGM) est la banque de données piézométriques française (> 3000 stations). Données téléchargeables librement. Pour évaluer l'état quantitatif : extraire les séries longues, calculer les quantiles saisonniers (25e, 50e, 75e percentile), comparer l'état actuel aux quantiles historiques, appliquer Mann-Kendall pour détecter les tendances. L'état est 'bon' (DCE) si les tendances sont stables ou haussières." },
      { id: 8, enonce: "Un aquifère libre reçoit une pluie de 25 mm. Le niveau piézométrique monte de 0,4 m en 3 jours. Calculez la recharge et estimez le délai entre la pluie et la recharge.", correction: "R = Sy × ΔN = 0,12 × 0,4 = 0,048 m = 48 mm. La recharge estimée (48 mm) est supérieure à la pluie (25 mm) : incohérence. Soit la pluie s'est accumulée depuis plusieurs semaines (zone non saturée), soit Sy est surestimé. Délai de réponse : 3 jours → zone non saturée épaisse de quelques mètres avec bonne conductivité." }
    ],
    flashcards: [
      { question: "Qu'est-ce que l'efficacité barométrique BE ?", reponse: "BE = -Δh/ΔPa. Fraction des variations de pression atmosphérique qui se transmettent au niveau piézométrique. BE = 0 : aquifère libre (surface libre répond librement). BE = 1 : aquifère captif parfait (toute pression est transmise). En pratique BE = 0,3-0,8 pour les aquifères captifs. Utilisé pour corriger les séries piézométriques." },
      { question: "Qu'est-ce qu'ADES ?", reponse: "Accès aux Données sur les Eaux Souterraines (BRGM/AFB). Base nationale française des données piézométriques. > 3000 points de surveillance. Données temps réel disponibles en ligne. Permet de détecter les tendances à long terme et d'évaluer l'état quantitatif au sens de la DCE." },
      { question: "Méthode WTF (Water Table Fluctuation)", reponse: "R = Sy × ΔN. Recharge estimée par la montée piézométrique suite à une pluie. Simple et directe mais suppose que toute la montée est due à la recharge locale. Sy doit être connu. Ne fonctionne que pour les aquifères libres (libre = niveau variable = rendement Sy)." },
      { question: "Avantages des capteurs Mini-Diver vs mesure manuelle", reponse: "Mini-Diver : mesure continue (1 min à 1h), données horodatées, pas de déplacement terrain (1 visite/an pour télécharger). Mesure manuelle : précision similaire mais ponctuelle, biaisée temporellement. Mini-Diver capture les oscillations rapides (marées terrestres, pluies, effet barométrique) et permet des études dynamiques." },
      { question: "Densité recommandée d'un réseau piézométrique", reponse: "Dépend de la variabilité spatiale de la nappe. Pour les grands aquifères stratégiques (Beauce, Alsace) : 1 point/50-100 km². Pour des aquifères locaux ou hétérogènes : 1 point/5-20 km². Le variogramme de h oriente la densité : portée courte → réseau dense. Les points existants (forages agricoles, puits AEP) sont instrumentés pour réduire les coûts." },
      { question: "Comment construire une carte piézométrique ?", reponse: "1. Collecter les mesures synchrones (même date) sur tous les piézomètres. 2. Vérifier la cohérence (outliers, forages équipés dans la mauvaise nappe). 3. Interpoler par krigeage ordinaire (ou KED avec MNT). 4. Tracer les équipotentielles. 5. Déduire les directions d'écoulement (perpendiculaires aux équipotentielles). 6. Identifier zones de recharge (N hauts) et décharge (N bas = exutoires)." }
    ]
  },

  'MASTER-EAU-043': {
    id: 'MASTER-EAU-043',
    titre: 'Essais de pompage et estimation des paramètres',
    fiche: {
      intro: "Les essais de pompage sont la méthode de référence pour estimer les paramètres hydrodynamiques des aquifères (T, S) in situ, à l'échelle représentative de quelques dizaines à centaines de mètres. L'interprétation repose sur des solutions analytiques (Theis, Cooper-Jacob, Hantush) et de plus en plus sur des méthodes numériques. La qualité de l'essai et son interprétation conditionnent directement la fiabilité de tout modèle hydrogéologique.",
      sections: [
        { titre: "Protocole d'essai de pompage", sous_sections: [
          { titre: "Essai à débit constant (CD : Constant Discharge)", contenu: "Le protocole standard (norme ISO 14686, NF EN ISO 14686) consiste à pomper à débit constant Q pendant plusieurs heures à plusieurs jours, en mesurant le rabattement dans le puits de pompage et dans des piézomètres d'observation. Les mesures sont rapprochées en début d'essai (1, 2, 5, 10, 20, 30 s puis min) et espacées ensuite. La reprise de niveau après arrêt du pompage (recovery test) fournit une estimation indépendante de T. L'essai par paliers de débit (step test) évalue les pertes de charge dans le puits." },
          { titre: "Essai par paliers et courbe caractéristique du puits", contenu: "L'essai par paliers augmente progressivement Q par étapes (3-6 paliers de 1-2h chacun) et mesure le rabattement spécifique sw/Q = aw + bQ. Le terme aw représente les pertes linéaires (aquifère) et bQ les pertes quadratiques (inertie et turbulence dans le puits). La courbe sp = f(Q) définit la capacité spécifique du puits et son rendement. Le débit optimum correspond à sw/h₀ < 0,5-0,7 pour préserver l'efficacité." }
        ]},
        { titre: "Méthodes d'interprétation analytique", sous_sections: [
          { titre: "Méthode de Theis et Cooper-Jacob", contenu: "La méthode de superposition de Theis utilise des abaques de W(u) = f(u) pour ajuster graphiquement le rabattement mesuré. La méthode de Cooper-Jacob trace s = f(log t) et ajuste une droite : T = Q/(4πT)×2,303/pente, S = 2,25Tt₀/r² où t₀ est l'intersection avec s = 0. La reprise de niveau est analysée par la méthode de Theis-Jacob (s' vs log(1+tp/t')) où tp est la durée de pompage. Ces méthodes nécessitent que u < 0,05 pour Cooper-Jacob." },
          { titre: "Méthodes pour aquifères complexes", contenu: "La méthode d'Hantush-Jacob traite les aquifères semi-captifs (courbe en S, plateau à long terme dû à la drainance). La méthode de Neuman traite les aquifères libres (double déflexion : réponse d'aquifère captif à court terme, puis transition vers débit de base du sol). La méthode de Papadopulos-Cooper adapte Theis aux grands diamètres de puits (effet de stockage dans le puits). Le diagnostic plots (dérivée log-log) est un outil puissant pour identifier le type d'aquifère avant l'interprétation." }
        ]},
        { titre: "Diagnostic plots et interprétation moderne", sous_sections: [
          { titre: "Courbe dérivée et diagnostic du comportement", contenu: "La courbe dérivée ds/d(ln t) tracée en log-log avec le rabattement permet d'identifier le type d'aquifère et les effets de stockage. Signatures caractéristiques : Theis (droite de pente 1/2 sur les deux courbes), Cooper-Jacob (plateau sur la dérivée = T constant), Hantush (hump = bosse sur la dérivée), aquifère libre (deux plateaux + transition), frontière imperméable (pente doublée) ou frontière rechargée (plateau sur la dérivée). Cette approche diagnostique précède l'ajustement du modèle analytique." },
          { titre: "Interprétation numérique par optimisation inverse", contenu: "Les logiciels modernes (AQTESOLV, PEST, ModINV) ajustent les paramètres par optimisation des moindres carrés en utilisant des solutions analytiques ou numériques. L'interprétation numérique est préférable aux méthodes graphiques car elle quantifie l'incertitude des paramètres estimés (intervalles de confiance) et peut tenir compte de plusieurs puits et piézomètres simultanément. La méthode de Levenberg-Marquardt est typiquement utilisée pour l'optimisation locale." }
        ]},
        { titre: "Efficacité hydraulique et protection des puits", sous_sections: [
          { titre: "Efficacité hydraulique et pertes de charge", contenu: "L'efficacité hydraulique E = sw_aquifère/sw_total mesure la fraction du rabattement total attribuable à l'aquifère (vs pertes de charge dans le puits). E > 70% est acceptable, E < 50% indique un puits inefficace (colmatage, mauvaise réalisation). Le facteur de skin SF (Sk = sw_puits - sw_Theis) quantifie l'endommagement supplémentaire. Un Sk négatif indique une stimulation (acidification, fracturation). La réhabilitation des puits (redéveloppement, acidification) améliore E et réduit les coûts d'énergie." },
          { titre: "Zone d'influence et rayon de capture", contenu: "Le rayon d'influence R(t) = √(2,25Tt/S) délimite la zone perturbée par le pompage. À l'état d'équilibre (si atteint), il est délimité par les limites de l'aquifère. Le rayon de capture pour un captage AEP définit la zone en amont hydraulique susceptible d'alimenter le puits. Il est calculé par traçage de lignes de courant dans le modèle numérique. Les PPR (Périmètres de Protection Rapprochés et Éloignés) sont définis réglementairement pour protéger les captages." }
        ]}
      ],
      points: ["Essai CD : pompage à débit constant Q, mesure du rabattement dans puits + piézomètres.", "Reprise de niveau (recovery) : analyse par Theis-Jacob, estimation indépendante de T.", "Cooper-Jacob : s = f(log t) donne T et S par la droite ajustée.", "Diagnostic plots (dérivée log-log) : identifie le type d'aquifère avant interprétation.", "Hantush-Jacob (aquifère semi-captif) : signature en S avec plateau de drainance.", "Neuman (aquifère libre) : double déflexion à court et long terme.", "Efficacité hydraulique E = rabattement aquifère / rabattement total. E > 70% acceptable.", "Rayon d'influence R(t) = √(2,25Tt/S).", "AQTESOLV, PEST : logiciels d'interprétation par optimisation inverse.", "Périmètres de protection (PPR) basés sur le rayon de capture calculé."],
      formules: [
        { nom: "Cooper-Jacob (pente de la droite s vs log t)", expression: "T = 2.303 × Q / (4π × Δs)",  variables: "Δs = variation de rabattement par log-cycle de temps" },
        { nom: "Estimation de S (Cooper-Jacob)", expression: "S = 2.25 × T × t₀ / r²", variables: "t₀ = temps d'intersection de la droite avec s = 0 (m), r = distance au puits (m)" },
        { nom: "Rayon d'influence", expression: "R(t) = √(2.25 × T × t / S)", variables: "t = durée du pompage (s), T = transmissivité (m²/s), S = coefficient d'emmagasinement" },
        { nom: "Pertes de charge dans le puits (étape)", expression: "sw = aw × Q + bw × Q²", variables: "aw = pertes linéaires aquifère (s/m²), bw = pertes turbulentes dans le puits (s²/m⁵)" },
        { nom: "Efficacité hydraulique du puits", expression: "E = sw_Theis / sw_total × 100%", variables: "sw_Theis = rabattement théorique Theis au rayon du puits, sw_total = rabattement mesuré au puits" }
      ],
      retenir: "L'essai de pompage est la méthode de référence pour T et S. L'interprétation par Cooper-Jacob est simple mais nécessite u < 0,05. Le diagnostic plots (dérivée log-log) identifie le type d'aquifère. Les logiciels modernes (AQTESOLV) fournissent l'ajustement et l'incertitude des paramètres. L'efficacité hydraulique et le rayon de capture complètent l'information pour la gestion des puits de captage."
    },
    exercices: [
      { id: 1, enonce: "Cooper-Jacob : un piézomètre à r = 50 m montre Δs = 0,85 m par log-cycle. Q = 0,015 m³/s. Calculez T.", correction: "T = 2,303 × Q / (4π × Δs) = 2,303 × 0,015 / (4π × 0,85) = 0,03455 / 10,68 = 3,23×10⁻³ m²/s." },
      { id: 2, enonce: "La droite Cooper-Jacob intersecte l'axe s = 0 à t₀ = 0,8 min = 48 s. T = 3,23×10⁻³ m²/s, r = 50 m. Calculez S.", correction: "S = 2,25 × T × t₀ / r² = 2,25 × 3,23×10⁻³ × 48 / (50²) = 0,3488 / 2500 = 1,40×10⁻⁴. Aquifère captif (S << 1)." },
      { id: 3, enonce: "Le rayon d'influence après 72h de pompage (T = 3×10⁻³ m²/s, S = 2×10⁻⁴) est ?", correction: "t = 72h = 259200 s. R = √(2,25 × 3×10⁻³ × 259200 / 2×10⁻⁴) = √(2,25×3×259200 / 2) × 10^(-3+4/2) = √(1750320×10⁻³/2×10⁻⁴). Calcul direct : R = √(2,25×0,003×259200/0,0002) = √(1750,32/0,0002... Simplifions : R² = 2,25×3×10⁻³×259200/(2×10⁻⁴) = 2,25×777,6/0,0002 = 1749,6/0,0002 = 8748000. R = 2958 m ≈ 3 km." },
      { id: 4, enonce: "L'essai par paliers d'un puits donne : sw/Q (m/(m³/s)) = 450, 520, 650 pour Q = 0,02, 0,04, 0,06 m³/s. Calculez aw et bw.", correction: "sw = aw×Q + bw×Q². sw/Q = aw + bw×Q. Régression sur (Q; sw/Q) : pente = bw, ordonnée à l'origine = aw. ΔQ = 0,04-0,02 = 0,02, Δ(sw/Q) = 520-450 = 70. bw ≈ 70/0,02 = 3500 s²/m⁵. aw ≈ 450 - 3500×0,02 = 450-70 = 380 s/m². Vérif : sw/Q(0,06) = 380+3500×0,06 = 380+210 = 590 ≈ 650 (acceptable)." },
      { id: 5, enonce: "Décrivez les 3 signatures du diagnostic plot d'un aquifère libre selon Neuman.", correction: "1. Court terme (Phase 1) : réponse comme aquifère captif (S = Ss×b faible), dérivée forme de cloche Theis. 2. Transition : plateau intermédiaire (drainage gravitaire du sol commence). 3. Long terme (Phase 2) : nouvelle dérivée de Theis avec S = Sy (grand) → plateau plus bas que la Phase 1. Ces 3 phases permettent d'estimer Ss, Sy, T et l'anisotropie verticale." },
      { id: 6, enonce: "Expliquez pourquoi il faut attendre que u < 0,05 pour appliquer l'approximation de Cooper-Jacob.", correction: "Cooper-Jacob est une simplification W(u) ≈ -0,5772 - ln(u) valide seulement pour u < 0,05 (u petit). Pour u grand (début d'essai ou grand r), W(u) dévie significativement du logarithme. En pratique, l'exigence u < 0,05 correspond à : t > 25r²S/T. Pour r = 100 m, T = 10⁻² m²/s, S = 10⁻³ : t > 25×100²×10⁻³/10⁻² = 25000 s ≈ 7h. Donc attendez au moins 7h avant d'appliquer Cooper-Jacob." },
      { id: 7, enonce: "Quelle signature sur le diagnostic plot indique une frontière imperméable à l'aquifère ?", correction: "Une frontière imperméable crée un effet image (puits virtuel de pompage du même signe). Le rabattement additionnel double la pente du rabattement. Sur le diagnostic plot (dérivée), la dérivée augmente et tend vers deux fois le palier de Theis (pente ×2 en log-log). La position de la frontière peut être estimée par le temps de déflexion." },
      { id: 8, enonce: "Un puits AEP a E = 45%. Qu'est-ce que cela signifie et quelles actions peut-on envisager ?", correction: "E = 45% < 50% → puits inefficace. 55% du rabattement total est dû aux pertes dans le puits (colmatage, endommagements). Cela augmente le coût énergétique et réduit le débit exploitable. Actions : inspection caméra (état de la crépine), test acoustique. Si colmatage : redéveloppement par air-lift, surpompage, injection de CO2. Si endommagement de la crépine : réhabilitation ou remplacement." }
    ],
    flashcards: [
      { question: "Méthode Cooper-Jacob : principe et conditions", reponse: "s = f(log t) donne une droite dont la pente = Q×2,303/(4πT). Valide si u = r²S/(4Tt) < 0,05 (régime semi-logarithmique établi). T = 2,303Q/(4πΔs), S = 2,25Tt₀/r². Simple mais ne fonctionne qu'après temps suffisant." },
      { question: "Qu'est-ce que le diagnostic plot ?", reponse: "Tracé en log-log de s et ds/d(ln t) vs t/r² (ou t). La dérivée révèle le type d'aquifère : plateau Theis, hump Hantush, double plateau Neuman, pente montante (frontière imperméable), pente descendante (frontière rechargée). Outil indispensable avant le choix du modèle analytique." },
      { question: "Qu'est-ce que l'essai de reprise de niveau ?", reponse: "Après arrêt du pompage, la remontée du niveau vers l'équilibre. Analysée par Theis-Jacob : s' = Q/(4πT) × log(1+tp/t'). tp = durée pompage, t' = temps depuis l'arrêt. Donne T indépendamment (pas S). Utile quand la pompe ne débite pas exactement Q (mesure en descente bruyante)." },
      { question: "Rayon d'influence : formule et signification", reponse: "R(t) = √(2,25Tt/S). Rayon de la zone perturbée par le pompage à l'instant t. Augmente comme √t (diffusion). T grand et S petit → R croît vite. Utile pour estimer l'interférence entre puits et la zone d'influence pour la protection des captages." },
      { question: "Signature Hantush sur le diagnostic plot", reponse: "Hump (bosse) sur la dérivée : la dérivée monte (phase Theis) puis redescend (plateau de drainance) avant de se stabiliser. La drainance de l'aquitard limite l'extension du rabattement. Le facteur de drainance B = √(T/r') conditionne l'amplitude et la position du hump." },
      { question: "Efficacité hydraulique d'un puits", reponse: "E = sw_aquifère/sw_total. sw_aquifère estimé par Theis au rayon du puits. E > 70% : puits efficace. E < 50% : puits dégradé (colmatage, skin positif). E se réduit avec le temps (colmatage progressif). Essai par paliers permet de quantifier E et de distinguer pertes linéaires (aquifère) et quadratiques (turbulence)." }
    ]
  },

  'MASTER-EAU-044': {
    id: 'MASTER-EAU-044',
    titre: 'Recharge et transferts dans la zone non saturée',
    fiche: {
      intro: "La zone non saturée (ZNS), entre la surface du sol et la nappe phréatique, joue un rôle crucial dans le filtrage et le retard des contaminants, et contrôle la recharge des aquifères. L'eau y circule sous l'action conjuguée de la gravité et de la capillarité. La modélisation de la ZNS est complexe (non-linéarité, hétérogénéité) mais indispensable pour évaluer la vulnérabilité des aquifères et dimensionner les périmètres de protection.",
      sections: [
        { titre: "Physique de la zone non saturée", sous_sections: [
          { titre: "Potentiel matriciel et courbe de rétention", contenu: "Dans la ZNS, l'eau est retenue par la capillarité (tension superficielle). Le potentiel matriciel ψ (ou succion h, pression négative) caractérise cette rétention. La courbe de rétention θ(ψ) (courbe de van Genuchten, Brooks-Corey) décrit la relation entre la teneur en eau θ et la succion. Elle est hystérétique (différente en humectation et drainage). À la capacité au champ (pF ≈ 2, ψ ≈ -0,1 bar), l'eau est retenue contre la gravité. Au point de flétrissement permanent (pF ≈ 4,2, ψ ≈ -15 bar), les plantes ne peuvent plus extraire l'eau." },
          { titre: "Conductivité hydraulique non saturée K(θ)", contenu: "La conductivité hydraulique K(θ) décroît de plusieurs ordres de grandeur quand θ diminue depuis la saturation (K = Ks) jusqu'à la valeur résiduelle (K → 0). Les modèles de van Genuchten-Mualem et Brooks-Corey-Burdine permettent d'estimer K(θ) à partir de la courbe de rétention. Cette non-linéarité extrême est la principale source de difficultés dans la modélisation de la ZNS. Les mesures directes de K(θ) sont difficiles (tensiomètre + TDR + bilan) et rarement disponibles." }
        ]},
        { titre: "Méthodes d'estimation de la recharge", sous_sections: [
          { titre: "Méthode lysimétrique et bilan hydrique", contenu: "La recharge est mesurée directement par le drainage lysimétrique (eau percolant sous la zone racinaire, recueillie et pesée). Cette méthode est précise mais coûteuse et peu représentative spatialement. Le bilan hydrique du sol (méthode de Thornthwaite-Mather ou FAO-56) calcule la recharge comme : R = P - ET - ΔS - Qsurface. La comparaison avec la recharge mesurée (fluctuation piézométrique, chlorures) valide le bilan. En France, la recharge interannuelle des grands aquifères est 100-300 mm/an (20-40% des précipitations)." },
          { titre: "Méthode des chlorures et traçage isotopique", contenu: "La méthode des chlorures (CMB : Chloride Mass Balance) suppose que les chlorures sont conservatifs et proviennent uniquement des pluies : R = P × Cl_pluie / Cl_sol. Elle est adaptée aux régions arides (R faible) où la concentration en chlorures dans le sol est mesurable. Les isotopes stables (δ¹⁸O, δ²H) tracent l'origine de la recharge (pluies hivernales vs estivales, altitude). Le tritium (³H) et le carbone 14 (¹⁴C) datent les eaux souterraines et estiment les temps de résidence (voir chapitre 51)." }
        ]},
        { titre: "Vulnérabilité et transfert des contaminants", sous_sections: [
          { titre: "Vitesse de transfert dans la ZNS", contenu: "Le temps de transfert d'un contaminant depuis la surface jusqu'à la nappe dépend de l'épaisseur de la ZNS, de la teneur en eau (vitesse v = R/θ), et des processus de rétention (adsorption sur les argiles et MO). En milieu poreux homogène, le temps de transfert est T_ZNS = z_ZNS × θ / R. Pour une ZNS de 10 m, θ = 0,25 et R = 150 mm/an : T = 10 × 0,25 / 0,15 = 16,7 ans. Les transferts préférentiels (macropores) peuvent court-circuiter la ZNS en quelques heures." },
          { titre: "Méthodes d'évaluation de la vulnérabilité", contenu: "Les méthodes d'indice de vulnérabilité (DRASTIC, GOD, EPIK pour les karsts) évaluent la susceptibilité des aquifères à la contamination. DRASTIC utilise 7 facteurs (Depth to water table, Recharge, Aquifer media, Soil media, Topography, Impact of vadose zone, Conductivity of aquifer). Ces méthodes sont utilisées pour délimiter les zones de protection des captages (PPR, ATPE) et guider les réglementations d'usage des sols." }
        ]},
        { titre: "Modélisation de la ZNS", sous_sections: [
          { titre: "Codes de modélisation (HYDRUS, VS2D)", contenu: "HYDRUS-1D/2D/3D (PC-Progress) résout l'équation de Richards par éléments finis, en simulant la transpiration racinaire, le transport de solutés et l'évaporation. Il est utilisé pour modéliser les périmètres de protection des captages, le transport de pesticides et la recharge de zones humides. VS2D (USGS) résout Richards en 2D axisymétrique. Ces codes nécessitent les paramètres de van Genuchten (θr, θs, α, n, Ks) souvent estimés par pédotransfert (ROSETTA)." },
          { titre: "Approches simplifiées pour les grands aquifères", contenu: "Pour les grands aquifères régionaux (Beauce, Crau), des modèles simplifiés de ZNS (réservoir à fuite, piston) calculent la recharge à partir des données météorologiques. L'approche « BRGM-ZNS » ou « Gardenia » utilise un réservoir sol et un réservoir de transfert racinaire. Ces modèles sont couplés avec des modèles d'écoulement souterrain pour simuler les fluctuations piézométriques sur de longues périodes. La recharge calculée est le principal terme de forçage des modèles hydrogéologiques régionaux." }
        ]}
      ],
      points: ["Zone non saturée (ZNS) : entre surface du sol et nappe phréatique.", "Courbe de rétention θ(ψ) : hystérétique, van Genuchten ou Brooks-Corey.", "Capacité au champ : pF ≈ 2. Point de flétrissement permanent : pF ≈ 4,2.", "K(θ) décroît de plusieurs ordres de grandeur entre saturation et résidu.", "Recharge R = P × Cl_pluie/Cl_sol (méthode des chlorures, CMB).", "DRASTIC évalue la vulnérabilité des aquifères à la contamination.", "HYDRUS-1D/2D : référence pour la modélisation de la ZNS.", "Temps de transfert ZNS = z × θ / R (sans transferts préférentiels).", "Les macropores court-circuitent la ZNS en quelques heures.", "Recharge interannuelle France : 100-300 mm/an (20-40% des précipitations)."],
      formules: [
        { nom: "van Genuchten (courbe de rétention)", expression: "θ(ψ) = θr + (θs-θr) / [1 + (α|ψ|)^n]^m", variables: "θr, θs = teneurs résiduelles et à saturation, α (1/cm), n > 1, m = 1-1/n" },
        { nom: "Mualem-van Genuchten K(Se)", expression: "K(Se) = Ks × Se^0.5 × [1-(1-Se^(1/m))^m]²", variables: "Se = (θ-θr)/(θs-θr) = saturation effective" },
        { nom: "Méthode CMB (Chloride Mass Balance)", expression: "R = P × Cl_P / Cl_sol", variables: "P = précipitation, Cl_P = Cl pluie (mg/L), Cl_sol = Cl eau du sol sous zone racinaire (mg/L)" },
        { nom: "Temps de transfert dans la ZNS", expression: "t_ZNS = z × θ / R", variables: "z = épaisseur de la ZNS (m), θ = teneur en eau moyenne, R = recharge (m/an)" },
        { nom: "Équation de Richards (1D vertical)", expression: "∂θ/∂t = ∂/∂z [K(θ)(∂ψ/∂z + 1)] - S(z,t)", variables: "K(θ) = conductivité non saturée, ψ = succion, S = absorption racinaire" }
      ],
      retenir: "La ZNS contrôle le temps de transit des contaminants et la recharge des aquifères. La courbe de rétention θ(ψ) et K(θ) sont les paramètres fondamentaux, non-linéaires et difficiles à mesurer. La méthode CMB (chlorures) est la méthode de terrain la plus robuste pour estimer la recharge. HYDRUS résout l'équation de Richards pour les études détaillées. La vulnérabilité des aquifères (DRASTIC, EPIK) guide la protection des captages."
    },
    exercices: [
      { id: 1, enonce: "La pluie contient Cl = 1,5 mg/L et le sol à 2 m de profondeur contient Cl = 28 mg/L. P = 650 mm/an. Calculez la recharge par CMB.", correction: "R = P × Cl_P / Cl_sol = 650 × 1,5/28 = 34,8 mm/an. Soit 5,4% des précipitations. Recharge très faible → milieu semi-aride ou aquifère profond à forte concentration en chlorures par évaporation." },
      { id: 2, enonce: "Une ZNS de 8 m a θ = 0,22 et reçoit une recharge R = 180 mm/an. Calculez le temps de transfert sans transferts préférentiels.", correction: "t_ZNS = z × θ / R = 8 × 0,22 / 0,18 = 9,78 ans ≈ 10 ans. Un pesticide appliqué aujourd'hui atteindra la nappe dans ~10 ans (en l'absence de dégradation)." },
      { id: 3, enonce: "Un sol a θs = 0,45, θr = 0,07, α = 0,015 cm⁻¹, n = 1,45. Calculez θ pour ψ = -50 cm.", correction: "m = 1-1/1,45 = 0,310. θ = 0,07 + (0,45-0,07)/[1+(0,015×50)^1,45]^0,310 = 0,07 + 0,38/[1+(0,75)^1,45]^0,310 = 0,07 + 0,38/[1+0,692]^0,310 = 0,07 + 0,38/[1,692]^0,310 = 0,07 + 0,38/1,165 = 0,07 + 0,326 = 0,396." },
      { id: 4, enonce: "Citez les 7 facteurs DRASTIC et leur signification.", correction: "D = Depth to water table (profondeur à la nappe). R = net Recharge (recharge nette). A = Aquifer media (nature de l'aquifère). S = Soil media (texture du sol). T = Topography (pente). I = Impact of vadose zone (nature de la ZNS). C = hydraulic Conductivity (conductivité de l'aquifère). Score pondéré de 1-10 × poids → index de vulnérabilité." },
      { id: 5, enonce: "Expliquez pourquoi les macropores rendent les méthodes d'évaluation de vulnérabilité basées sur le temps de transfert insuffisantes.", correction: "Les macropores (galeries de vers de terre, fissures de retrait, racines mortes) créent des chemins préférentiels court-circuitant la matrice poreuse. Un contaminant peut atteindre la nappe en heures au lieu de décennies, même si la ZNS est épaisse et la recharge faible. Les méthodes d'indice (DRASTIC) ne modélisent pas cet effet. Des traçages sur site ou HYDRUS avec domaine mobile-immobile sont nécessaires pour les sols très macroporeux (argiles, limons à structure grumeleuse)." },
      { id: 6, enonce: "Calculez Se et K/Ks pour θ = 0,30 avec θr = 0,07, θs = 0,45, m = 0,35 (van Genuchten-Mualem).", correction: "Se = (0,30-0,07)/(0,45-0,07) = 0,23/0,38 = 0,605. K/Ks = Se^0,5 × [1-(1-Se^(1/m))^m]² = 0,778 × [1-(1-0,605^(1/0,35))^0,35]² = 0,778 × [1-(1-0,605^2,857)^0,35]². 0,605^2,857 = 0,218. (1-0,218)^0,35 = 0,782^0,35 = 0,920. [1-0,920]² = 0,0064. K/Ks = 0,778 × 0,0064 = 0,00498. K ≈ 0,5% de Ks." },
      { id: 7, enonce: "Qu'est-ce que l'hystérésis de la courbe de rétention et quelles en sont les conséquences pratiques ?", correction: "La courbe θ(ψ) est différente selon que le sol s'humecte (courbe d'humectation) ou se sèche (courbe de drainage). À même succion ψ, θ est plus grand en drainage qu'en humectation (effet d'encre bouteille : petits pores se vident avant les grands). Conséquences : la conductivité K(θ) est différente selon le sens. Les modèles qui ignorent l'hystérésis sous-estiment la teneur en eau lors du drainage et peuvent se tromper de sens des flux. HYDRUS peut modéliser l'hystérésis." },
      { id: 8, enonce: "Un captage d'eau potable est menacé par les pesticides agricoles. Comment délimitez-vous le périmètre de protection rapproché (PPR) ?", correction: "1. Définir le rayon de capture hydraulique par traçage de particules dans un modèle d'écoulement souterrain (MODFLOW + MODPATH). 2. Calculer le temps de transfert dans la ZNS (HYDRUS ou temps piston). 3. Le PPR doit couvrir la zone en amont hydraulique avec t_ZNS + t_aquifère < 50 jours (norme française). 4. L'arrêté de déclaration d'utilité publique (DUP) fige le PPR et impose des servitudes d'usage des sols (interdictions de pesticides, etc.)." }
    ],
    flashcards: [
      { question: "Capacité au champ vs point de flétrissement", reponse: "Capacité au champ : pF ≈ 2 (ψ ≈ -0,1 bar). Eau retenue contre la gravité, non drainée. Point de flétrissement permanent (PWP) : pF ≈ 4,2 (ψ ≈ -15 bar). Les plantes ne peuvent plus extraire l'eau. La réserve utile (RU) = θ(pF2) - θ(pF4,2). Dépend fortement de la texture du sol." },
      { question: "Méthode CMB (Chloride Mass Balance)", reponse: "R = P × Cl_pluie / Cl_sol. Suppose que Cl est conservatif et provient uniquement des pluies. Valide en régions arides (Cl_sol accumulé par évaporation). Simple à mettre en œuvre (analyse d'eau). Limitation : ne tient pas compte des dépôts secs de Cl et des transferts latéraux." },
      { question: "Équation de Richards : pourquoi difficile à résoudre ?", reponse: "Fortement non-linéaire : K(θ) et ψ(θ) varient sur plusieurs ordres de grandeur. Discrétisation fine nécessaire (mm à cm) en temps et espace. Instabilités numériques fréquentes (fronts de saturation raides). Hystérésis complique encore le problème. Codes spécialisés (HYDRUS) nécessaires." },
      { question: "Méthode DRASTIC", reponse: "Index de vulnérabilité = Σ(poids × note) sur 7 paramètres : profondeur nappe, recharge, nature aquifère, sol, topographie, ZNS, conductivité. Score de 23 (peu vulnérable) à 230 (très vulnérable). Utilisé pour zonage réglementaire. Limitation : ne modélise pas les transferts préférentiels." },
      { question: "Qu'est-ce que HYDRUS ?", reponse: "Logiciel de simulation de l'écoulement et du transport de solutés dans la ZNS (Richards 1D/2D/3D + ADE). Paramètres van Genuchten. Modèles de transport : advection-dispersion, réactions, isothermes d'adsorption. Applications : transfert de pesticides, recharge de nappe, périmètres de captage. Open source (USGS)." },
      { question: "Effet des macropores sur la recharge", reponse: "Les macropores court-circuitent la matrice poreuse : eau passe en quelques heures de la surface à la nappe même en sol sec. Recharge rapide après de fortes pluies (bypassing flow). Transport de contaminants sans adsorption sur les argiles. Sous-estimé par les modèles matriciels classiques. HYDRUS avec domaine mobile-immobile représente cet effet." }
    ]
  }
,

  'MASTER-EAU-045': {
    id: 'MASTER-EAU-045',
    titre: 'Relations entre nappes, rivières et zones humides',
    fiche: {
      intro: "Les échanges entre eaux souterraines et eaux de surface constituent un continuum hydrologique fondamental. Ces interactions conditionnent les régimes d'étiage des rivières, le fonctionnement des zones humides et la qualité des eaux. Leur quantification est indispensable pour la gestion intégrée des ressources en eau (GIRE) et la mise en œuvre de la DCE.",
      sections: [
        { titre: "Types d'interactions nappe-rivière", sous_sections: [
          { titre: "Rivières gagnantes et perdantes", contenu: "Une rivière gagnante (effluente) reçoit de l'eau de la nappe : la charge hydraulique de la nappe est supérieure à la charge de la rivière. Elle soutient le débit d'étiage. Une rivière perdante (influente) alimente la nappe : sa charge est supérieure à la nappe. Elle peut être totalement déconnectée (rivière perchée) si une zone non saturée sépare le fond de la rivière de la nappe. L'inversion du gradient peut se produire saisonnièrement ou lors de crues (recharge rapide par infiltration depuis la rivière)." },
          { titre: "Échanges hyporhéiques", contenu: "La zone hyporhéique est la zone de transition sous et autour du lit de la rivière où l'eau de surface et l'eau souterraine se mélangent. Les échanges hyporhéiques sont induits par les variations de pression hydraulique liées à la morphologie du lit (séquences radiers-mouilles). Cette zone joue un rôle écologique majeur (habitat d'invertébrés, dénitrification, thermique) et biogéochimique (réactions d'oxydo-réduction, dégradation des contaminants). Sa modélisation requiert des approches multi-échelles." }
        ]},
        { titre: "Méthodes de quantification des échanges", sous_sections: [
          { titre: "Méthodes hydrologiques et hydrométriques", contenu: "Le bilan de tronçon compare les débits mesurés à deux stations encadrant un tronçon (différence = apports/pertes souterrains). Le débit de base (baseflow) peut être séparé du débit total par des méthodes de décomposition du hydrogramme (séparation graphique, filtrage numérique). Les méthodes de traçage chimique (Cl, Na, ions majeurs) permettent d'estimer la fraction d'eau souterraine dans le débit. La conductivité électrique est un traceur quasi-instantané et peu coûteux." },
          { titre: "Gradients thermiques et thermométrie par fibres optiques", contenu: "La température est un traceur des flux verticaux entre nappe et rivière. L'eau souterraine a une température constante (~12°C en France), proche de la température annuelle moyenne. Les profils thermiques verticaux dans le lit (température vs profondeur) permettent d'inverser les flux verticaux (méthode de Hatch, Anderson, Goto). La fibre optique DTS (Distributed Temperature Sensing) mesure la température en continu le long de km de rivière, identifiant les zones d'exfiltration (eau froide en été, chaude en hiver) avec une résolution spatiale métrique." }
        ]},
        { titre: "Zones humides et nappes superficielles", sous_sections: [
          { titre: "Fonctionnement hydrogéologique des zones humides", contenu: "Les zones humides de nappe (mares permanentes, tourbières, marais alcalins) sont alimentées par les exutoires de nappes phréatiques peu profondes. La position du toit de la nappe par rapport au terrain détermine la présence ou l'absence de la saturation du sol (critère de définition des zones humides). En période d'étiage, la nappe soutient l'eau libre des zones humides. Les zones humides riveraines (ripisylves, forêts alluviales) fonctionnent comme des zones-tampon entre les versants et les cours d'eau (filtration des nitrates, régulation des crues)." },
          { titre: "Impact des prélèvements souterrains sur les zones humides", contenu: "Les pompages dans les aquifères phréatiques peuvent abaisser le niveau piézométrique en dessous du seuil d'alimentation des zones humides, entraînant leur assèchement progressif. Ce phénomène est observé dans de nombreuses régions de France (Beauce, Bretagne, Normandie) et est un contentieux fréquent en droit de l'eau. Les études d'impact des captages AEP intègrent désormais la quantification des effets sur les zones humides (arrêté du 20/06/2014). La modélisation couplée nappe-zone humide permet de définir des seuils de pompage préservant les fonctionnalités écologiques." }
        ]},
        { titre: "Modélisation des échanges nappe-rivière", sous_sections: [
          { titre: "Module RIV et SFR dans MODFLOW", contenu: "MODFLOW propose deux approches pour simuler les échanges rivière-nappe. Le package RIV est simple : flux proportionnel à la différence de charge (QRIV = C×(hriv-h)) avec coupure si h < rbot. Le package SFR (Streamflow Routing) est plus complet : il simule le débit dans le réseau hydrographique, l'échange avec la nappe, l'évaporation depuis la rivière et les pertes par transpiration de la ripisylve. SFR2 permet de simuler des aquifères multi-couches avec des rivières incisées. Ces packages nécessitent la géométrie du lit (largeur, pente, rugosité) et la conductance hydraulique du lit (Clit = Klit × L × W / b_sédiment)." },
          { titre: "Modèles couplés surface-souterrain", contenu: "Les modèles couplés (HydroGeoSphere, MIKE-SHE, ParFlow) résolvent simultanément les équations de Saint-Venant (surface) et de Richards/Darcy (souterrain), avec un terme d'échange à l'interface. Ils permettent de simuler les crues en interaction avec la nappe (inondations des plaines alluviales où la nappe affleure), les recharges rapides lors des crues et les échanges hyporhéiques. Leur complexité et leurs besoins en données sont cependant élevés. Ils sont utilisés pour des études fondamentales et des projets d'aménagement d'envergure." }
        ]}
      ],
      points: ["Rivière gagnante : reçoit la nappe (charge nappe > charge rivière). Rivière perdante : alimente la nappe.", "Zone hyporhéique : mélange eau de surface / souterrain sous et autour du lit.", "Bilan de tronçon : différence de débit entre deux stations = apports/pertes souterrains.", "Fibre optique DTS : profil thermique continu le long de rivières (exfiltration = eau froide en été).", "Le débit de base (baseflow) est soutenu par la décharge de la nappe en étiage.", "Zones humides de nappe : alimentées par exutoires phréatiques, menacées par les pompages.", "Package SFR (MODFLOW) : simulation couplée débit en rivière + échanges nappe.", "HydroGeoSphere : modèle couplé surface-souterrain (Saint-Venant + Richards).", "Impact des pompages sur les zones humides = contentieux fréquent en droit de l'eau.", "Méthode thermique : gradient T dans le lit renseigne sur le sens et l'intensité des flux."],
      formules: [
        { nom: "Flux nappe-rivière (MODFLOW RIV)", expression: "QRIV = C × (hriv - h)  si h > rbot", variables: "C = conductance du lit (m²/s), hriv = cote en rivière, h = charge nappe, rbot = fond lit" },
        { nom: "Conductance hydraulique du lit de rivière", expression: "C = Klit × L × W / b", variables: "Klit = conductivité du sédiment (m/s), L = longueur tronçon, W = largeur, b = épaisseur sédiment" },
        { nom: "Débit de base (filtrage numérique, Lyne-Hollick)", expression: "BFt = α × BFt-1 + (1-α)/2 × (Qt + Qt-1)", variables: "BF = débit de base, Q = débit total, α = facteur de filtrage (0,925 recommandé)" },
        { nom: "Flux par gradient thermique vertical", expression: "qz = -(λ/ρc) × dT/dz + (heat advection)", variables: "λ = conductivité thermique, ρc = capacité calorifique eau, T = température" },
        { nom: "Coefficient d'échange hyporhéique", expression: "α_hyp = Klit / (Δz_lit)",  variables: "α_hyp = conductance volumique (1/s), Δz_lit = épaisseur de la zone hyporhéique" }
      ],
      retenir: "Les échanges nappe-rivière sont bidirectionnels et contrôlés par les gradients de charge hydraulique. Les méthodes hydrologiques (bilan de tronçon, débit de base) et thermiques (DTS) permettent de les quantifier. Les zones humides alimentées par les nappes sont vulnérables aux pompages. La modélisation couplée (MODFLOW/SFR, HydroGeoSphere) est l'état de l'art pour les études d'impact."
    },
    exercices: [
      { id: 1, enonce: "Un tronçon de rivière de 5 km perd 0,8 m³/s entre deux stations hydrologiques. La largeur moyenne est 25 m. Calculez le flux d'infiltration en mm/j.", correction: "Surface = 5000 × 25 = 125000 m². Flux = 0,8/125000 = 6,4×10⁻⁶ m/s = 0,55 m/j = 553 mm/j. Très fort taux d'infiltration, typique d'une rivière perchée sur alluvions grossières." },
      { id: 2, enonce: "La conductance hydraulique du lit d'une rivière est C = 50 m²/j. La cote en rivière est 102,5 m NGF et la charge de la nappe est 103,2 m NGF. Calculez le flux en m³/j par mètre de longueur si W = 15 m.", correction: "QRIV = C/L × (hriv - h) mais h > hriv ici (nappe à 103,2 > rivière à 102,5). La nappe alimente la rivière. QRIV/L = (C/L×W) × Δh = 50/15 × (103,2-102,5) = ... Note : C = 50 m²/j total (longueur définie dans C). Q = 50 × 0,7 = 35 m³/j. La rivière gagne 35 m³/j." },
      { id: 3, enonce: "En été, une fibre DTS mesure un refroidissement de 1,5°C sur un tronçon de 200 m. L'eau souterraine est à 12°C, l'eau de rivière à 18°C. Interprétez.", correction: "Refroidissement de 1,5°C sur 200 m en été = exfiltration d'eau souterraine froide (12°C vs 18°C en surface). Mélange d'environ 25% d'eau souterraine (ΔT/ΔTmax = 1,5/6 = 0,25). Ce tronçon est une zone d'exfiltration active, favorable aux espèces piscicoles fraîches (truite)." },
      { id: 4, enonce: "Citez 3 méthodes pour séparer le débit de base du débit total dans un hydrogramme.", correction: "1. Séparation graphique (ligne droite entre le début de la crue et la décrue). 2. Filtrage numérique récursif (Lyne-Hollick, α = 0,925). 3. Traçage géochimique (mixing model : proportion d'eau souterraine à partir de Cl ou conductivité). La méthode des filtres est la plus couramment automatisée sur les grands réseaux de stations." },
      { id: 5, enonce: "Pourquoi une zone humide alimentée par une nappe phréatique peut-elle être asséchée par un pompage situé à 2 km ?", correction: "Le pompage crée un cône de dépression qui se propage dans la nappe (R = √(2,25Tt/S)). Si la zone humide est au-dessus du niveau de la nappe (surface phréatique affleurant), l'abaissement du niveau piézométrique par le pompage peut descendre le toit de la nappe sous le niveau du sol de la zone humide, interrompant l'alimentation. Sur les grands aquifères (T élevée), le cône peut s'étendre sur plusieurs km en quelques semaines." },
      { id: 6, enonce: "Quelle est la différence entre le package RIV et SFR dans MODFLOW ?", correction: "RIV : charge en rivière hriv fixe (niveau imposé), flux proportionnel à Δh, pas de propagation du débit dans la rivière. Simple mais ne simule pas le débit en rivière. SFR (Streamflow Routing) : simule le débit dans le réseau hydrographique (Saint-Venant simplifié ou cinématique), échange nappe-rivière en fonction du débit et de la géométrie du lit, pertes par évaporation. Plus réaliste mais nécessite la géométrie complète du réseau hydrographique." },
      { id: 7, enonce: "La dénitrification dans la zone hyporhéique est favorisée par quelles conditions ?", correction: "La dénitrification (NO3⁻ → N2 par bactéries anaérobies) requiert : conditions anaérobies (O2 < 1 mg/L), carbone organique dissous (source d'énergie), nitrates (substrat). La zone hyporhéique crée ces conditions : temps de résidence long (quelques heures à jours), matière organique déposée dans les sédiments, eau de nappe anoxique. Les zones hyporhéiques épurées sont estimées dénitrifiant jusqu'à 30-80% de la charge en nitrates entrant." },
      { id: 8, enonce: "Calculez le débit de base par filtrage Lyne-Hollick à t=3 si Qt=3 = 2,8, Qt=2 = 3,5, BFt=2 = 1,2, α = 0,925.", correction: "BFt=3 = α × BFt=2 + (1-α)/2 × (Qt=3 + Qt=2) = 0,925 × 1,2 + (0,075/2) × (2,8 + 3,5) = 1,11 + 0,0375 × 6,3 = 1,11 + 0,236 = 1,346 m³/s. Le débit de base est 1,35 m³/s, soit 48% du débit total de 2,8 m³/s." }
    ],
    flashcards: [
      { question: "Rivière gagnante vs rivière perdante", reponse: "Gagnante (effluente) : nappe alimentant la rivière (h_nappe > h_rivière). Soutient l'étiage. Perdante (influente) : rivière alimentant la nappe (h_rivière > h_nappe). Peut être perchée (zone non saturée entre lit et nappe). Le sens peut s'inverser saisonnièrement." },
      { question: "Zone hyporhéique : définition et rôle", reponse: "Zone de mélange entre eau de surface et eau souterraine sous et autour du lit. Rôles : habitat d'invertébrés (macrobenthos hyporhéique), dénitrification, régulation thermique, dégradation de polluants. Échanges induits par la morphologie du lit (radiers-mouilles). Rôle tampon géochimique." },
      { question: "Méthode DTS (Distributed Temperature Sensing)", reponse: "Fibre optique mesure la température en continu (1 point/m sur des km). En été, eau souterraine froide → taches froides dans la rivière = zones d'exfiltration. En hiver, eau souterraine chaude → zones de réchauffement. Résolution : 1 m spatial, 0,1°C thermique. Révolutionne la cartographie des échanges nappe-rivière." },
      { question: "Impact des pompages sur les zones humides", reponse: "Le pompage abaisse le niveau piézométrique. Si la nappe phréatique alimente la zone humide (niveau phréatique au niveau du sol ou légèrement au-dessus), un abaissement peut couper l'alimentation → assèchement progressif. Obligation d'évaluation dans les études d'impact. Périmètres de protection peuvent inclure des servitudes de non-pompage." },
      { question: "Conductance hydraulique du lit (MODFLOW)", reponse: "C = Klit × L × W / b (m²/s). L = longueur du tronçon, W = largeur, b = épaisseur des sédiments du lit, Klit = conductivité hydraulique des sédiments. Paramètre difficile à mesurer directement (colmatage progressif du lit). Souvent calé lors de l'ajustement du modèle sur les débits observés." },
      { question: "Débit de base : définition et estimation", reponse: "Fraction du débit total provenant de la décharge des nappes (base flow). En étiage = 100% du débit (soutenu par la nappe). En crue = fraction faible. Méthodes d'estimation : filtrage numérique (Lyne-Hollick), séparation graphique, traçage géochimique (conductivité, Cl). Index de débit de base BFI = volume débit base / volume débit total." }
    ]
  },

  'MASTER-EAU-046': {
    id: 'MASTER-EAU-046',
    titre: "Construction d'un modèle numérique d'écoulement souterrain",
    fiche: {
      intro: "La construction d'un modèle numérique d'écoulement souterrain est un processus rigoureux qui transforme le modèle conceptuel en un outil quantitatif de simulation et de prévision. Les étapes clés sont la discrétisation spatiale, l'implémentation des conditions aux limites et des termes sources, puis le calage (calibration) sur les observations de terrain. La qualité du modèle est conditionnée par la qualité des données et la pertinence du modèle conceptuel.",
      sections: [
        { titre: "Discrétisation spatiale et temporelle", sous_sections: [
          { titre: "Construction de la grille MODFLOW", contenu: "MODFLOW utilise une grille tridimensionnelle de cellules rectangulaires (DRW et DCS en MODFLOW 6 pour les grilles non orthogonales). Chaque cellule est définie par ses coordonnées (row, column, layer), ses dimensions (Δr, Δc, Δv) et ses paramètres (K, Sy, Ss). La grille doit être plus fine dans les zones d'intérêt (puits de pompage, frontières) et plus grossière en périphérie. Des règles pratiques : le ratio entre cellules adjacentes ne doit pas dépasser 1,5 à 2, la taille minimale d'une cellule autour d'un puits ≈ 1-2 m (sinon surestimation du rabattement). Les interfaces des couches (tops et bottoms) représentent la géologie." },
          { titre: "Discrétisation temporelle et régime transitoire", contenu: "Le modèle peut être en régime permanent (steady-state) si l'aquifère est à l'équilibre ou en régime transitoire pour simuler les variations temporelles. Les pas de temps sont progressifs (croissance géométrique) pour capturer la dynamique rapide au début puis plus lente. La stabilité numérique requiert : dt < Δx² × S / (2T) (critère de Courant-Friedrichs-Lewy). Les périodes de stress (stress periods dans MODFLOW) délimitent des intervalles où les termes sources (pompages, recharge) sont constants, subdivisées en time steps pour l'intégration temporelle." }
        ]},
        { titre: "Implémentation des données et paramètres", sous_sections: [
          { titre: "Sources de données hydrogéologiques", contenu: "Les données nécessaires incluent : la géologie (cartes géologiques, coupes de forages de la BSS), les niveaux piézométriques de calage (ADES), les débits des sources et des rivières (HYDRO), les prélèvements (AEP, industriels, irrigation), la recharge (Météo-France + modèles bilan hydrique). Le SIG (QGIS, ArcGIS) est l'outil central d'intégration. L'interface FloPy (Python) ou ModelMuse (interface graphique) permet de préparer les fichiers MODFLOW. La qualité du modèle est limitée par la qualité de ses données d'entrée." },
          { titre: "Paramétrage initial et zonation", contenu: "Les paramètres hydrodynamiques (K, T, S, Sy) sont initialisés à partir des essais de pompage disponibles et de la bibliographie. La zonation divise l'aquifère en zones homogènes correspondant aux grandes unités lithologiques. L'interpolation des paramètres entre forages est réalisée par krigeage (si assez de données) ou par jugement d'expert (zonation par polygones de Thiessen ou manuelle). Les conditions aux limites sont définies selon le modèle conceptuel : limites imperméables (pas de flux), charges imposées (Constant Head), échanges rivière-nappe (packages RIV/SFR)." }
        ]},
        { titre: "Calage et validation du modèle", sous_sections: [
          { titre: "Calage manuel et automatique", contenu: "Le calage (calibration) ajuste les paramètres pour minimiser l'écart entre les niveaux piézométriques simulés et observés. Le calage manuel consiste à modifier les zones de paramètres par itérations successives. Le calage automatique (PEST, PEST++, iES) utilise des algorithmes d'optimisation. La fonction objectif est typiquement φ = Σ[(h_obs - h_sim)²] pondérée par les incertitudes de mesure. Les critères de qualité du calage : résidu moyen (bias), RMSE (root mean square error), coefficient de Nash-Sutcliffe (NSE)." },
          { titre: "Validation et analyse de sensibilité", contenu: "La validation consiste à tester le modèle calé sur une période différente de la période de calage, sans ajustement des paramètres. Un modèle qui ne valide pas est surparamétré ou a un modèle conceptuel erroné. L'analyse de sensibilité identifie les paramètres les plus influents sur les prévisions (Sobol, analyse de sensibilité différentielle dans PEST). Les paramètres les plus sensibles doivent être mesurés avec soin. L'analyse d'incertitude (Monte Carlo, inversion ensembliste) quantifie l'incertitude sur les prévisions." }
        ]},
        { titre: "Utilisation et limites du modèle", sous_sections: [
          { titre: "Scénarios de gestion et prévisions", contenu: "Une fois calé et validé, le modèle peut répondre à des questions opérationnelles : quel débit peut-on pomper sans assécher une zone humide ? Quelle est la zone de capture d'un captage AEP ? Comment évoluera la piézométrie avec le changement climatique (scénarios IPCC) ? Les scénarios de gestion comparent différentes stratégies de prélèvements. Les scénarios de changement climatique modifient la recharge et les prélèvements. Ces simulations guident les décisions des SAGE et des contrats de milieu." },
          { titre: "Limites et incertitudes inhérentes", contenu: "Tout modèle est une simplification de la réalité : les incertitudes sur les paramètres (K, S), la géométrie et les termes sources se propagent aux prévisions. Le problème d'équifinalité (voir chapitre 047) rend le modèle non-unique. Les modèles ne prédisent pas les événements rares (étiages extrêmes, crues exceptionnelles) au-delà des conditions de calage. La maintenance du modèle (mise à jour des données) est indispensable. Un modèle n'est pas la réalité : il représente le niveau de compréhension actuel du système." }
        ]}
      ],
      points: ["MODFLOW : grille 3D de cellules rectangulaires, paramètres par cellule.", "Discrétisation temporelle : stress periods (termes sources constants) + time steps.", "Données nécessaires : géologie (BSS), piézométrie (ADES), débits (HYDRO), prélèvements, recharge.", "FloPy (Python) et ModelMuse : interfaces de préparation des fichiers MODFLOW.", "Calage par PEST/PEST++ : optimisation automatique des paramètres.", "Critères de calage : RMSE, biais, NSE (Nash-Sutcliffe).", "Validation : test sur période différente sans réajustement des paramètres.", "Analyse de sensibilité (Sobol) : identifie les paramètres les plus influents.", "Scénarios de gestion : simulations pour guider les SAGE et décisions de prélèvements.", "Equifinalité : plusieurs jeux de paramètres peuvent donner des résultats similaires."],
      formules: [
        { nom: "Critère de Nash-Sutcliffe (NSE)", expression: "NSE = 1 - Σ(h_obs - h_sim)² / Σ(h_obs - h̄_obs)²", variables: "NSE = 1 : modèle parfait. NSE > 0,5 : satisfaisant. NSE < 0 : modèle pire que la moyenne" },
        { nom: "RMSE du calage piézométrique", expression: "RMSE = √[Σ(h_obs - h_sim)² / N]", variables: "N = nombre de mesures piézométriques. RMSE en mètres. Objectif : < incertitude de mesure" },
        { nom: "Critère de stabilité numérique (Neumann)", expression: "Cr = T × dt / (S × Δx²) ≤ 0.5", variables: "Cr = nombre de Courant modifié. dt = pas de temps, Δx = taille de cellule. Si Cr > 0,5 → instabilités" },
        { nom: "Fonction objectif PEST", expression: "Φ = (h_obs - h_sim)ᵀ × W × (h_obs - h_sim)", variables: "W = matrice de poids (inverse des variances d'erreur de mesure). Minimisée par Levenberg-Marquardt" },
        { nom: "Équation de continuité dans une cellule MODFLOW", expression: "ΣQfaces + Qsources = Ss × Vcell × Δh/Δt", variables: "ΣQfaces = flux entrant/sortant par les 6 faces, Qsources = termes puits/sources dans la cellule" }
      ],
      retenir: "La construction d'un modèle MODFLOW suit une démarche rigoureuse : modèle conceptuel → discrétisation → paramétrage initial → calage automatique (PEST) → validation → scénarios. La qualité du calage est mesurée par RMSE et NSE. L'analyse de sensibilité identifie les paramètres critiques. Le modèle est un outil de décision, non une réalité, et ses limites (équifinalité, incertitudes) doivent être clairement communiquées aux décideurs."
    },
    exercices: [
      { id: 1, enonce: "RMSE = 0,85 m sur 42 piézomètres pour un modèle régional d'aquifère. Les mesures sont précises à ±0,05 m. Ce calage est-il satisfaisant ?", correction: "RMSE = 0,85 m >> incertitude de mesure (0,05 m). Le calage n'est pas satisfaisant. L'erreur est principalement liée à l'erreur de modèle (géologie simplifiée, hétérogénéités non représentées, termes sources mal estimés), pas à l'imprécision des mesures. Objectif : RMSE < 1-2% de l'amplitude piézométrique observée." },
      { id: 2, enonce: "NSE = 0,78 pour le calage piézométrique et NSE = 0,43 pour la validation. Que concluez-vous ?", correction: "Le calage est bon (NSE = 0,78 > 0,65). Mais la validation est médiocre (NSE = 0,43 < 0,5). Cela indique un sur-calage (overfitting) : les paramètres ont été sur-ajustés à la période de calage. Le modèle manque de robustesse pour d'autres conditions. Solution : réduire le nombre de zones de paramètres, utiliser une régularisation dans PEST (Tikhonov), allonger la période de calage." },
      { id: 3, enonce: "Un modèle MODFLOW a des cellules de Δx = 500 m. T = 10⁻² m²/s, S = 2×10⁻⁴. Quel pas de temps dt maximal assure la stabilité numérique ?", correction: "Cr = T × dt / (S × Δx²) ≤ 0,5. dt ≤ 0,5 × S × Δx² / T = 0,5 × 2×10⁻⁴ × 500² / 10⁻² = 0,5 × 2×10⁻⁴ × 250000 / 10⁻² = 0,5 × 5 = 2,5 s. Très restrictif pour cellules de 500 m. En pratique MODFLOW utilise un solveur implicite (PCG) qui n'a pas cette contrainte de stabilité." },
      { id: 4, enonce: "Citez 5 données d'entrée nécessaires à la construction d'un modèle MODFLOW régional.", correction: "1. Géologie : tops et bottoms des couches (forages BSS, cartes géologiques). 2. Piézométrie de calage : séries de h(t) sur les piézomètres (ADES). 3. Prélèvements : débits des pompages AEP, industriels, irrigation. 4. Recharge : flux en mm/mois par zone (Météo + bilan hydrique). 5. Conditions aux limites : débits rivières (HYDRO), cotes plans d'eau, frontières géologiques." },
      { id: 5, enonce: "Qu'est-ce que PEST et comment l'utilise-t-on pour caler un modèle hydrogéologique ?", correction: "PEST (Parameter ESTimation) est un logiciel d'optimisation automatique des paramètres. Principe : il fait tourner MODFLOW automatiquement, compare les simulations aux observations, calcule la dérivée de la fonction objectif par rapport à chaque paramètre, ajuste les paramètres via Levenberg-Marquardt, et itère jusqu'à convergence. Il fournit en sortie : paramètres optimisés, incertitudes (intervalles de confiance), analyse de sensibilité. PEST++ propose des méthodes ensemblistes (iES) pour l'analyse d'incertitude." },
      { id: 6, enonce: "Expliquez pourquoi la taille des cellules autour des puits de pompage est critique dans MODFLOW.", correction: "Dans MODFLOW, le rabattement est calculé en tête de cellule. Avec de grandes cellules, le puits est 'noyé' dans une grande cellule dont le niveau moyen sous-estime le rabattement réel. Des cellules trop grandes au niveau des puits → surestimation du débit exploitable, sous-estimation des interférences entre puits. Solution : cellules de ~1-5 m au niveau des puits, raffinement du maillage. Dans MODFLOW 6, le package MAW (Multi-Aquifer Well) gère explicitement la géométrie du puits." },
      { id: 7, enonce: "Quelle est la différence entre régime permanent et régime transitoire dans un modèle MODFLOW ?", correction: "Régime permanent (steady-state) : ∂h/∂t = 0, le stockage ne change pas. Représente un état d'équilibre moyen (bilan entrées = sorties). Utilisé pour le calage initial (élimine S des paramètres à caler). Régime transitoire : ∂h/∂t ≠ 0, les niveaux varient avec le temps (pompages variables, recharge saisonnière). Permet de caler T et S simultanément. Nécessite des séries temporelles de h observés. Les deux régimes sont complémentaires." },
      { id: 8, enonce: "Un scénario de changement climatique prédit une réduction de 15% de la recharge annuelle. Le modèle donne une baisse piézométrique de 2,5 m. Citez 3 limites de cette prévision.", correction: "1. Incertitude sur le scénario climatique lui-même (fourchette IPCC : -10 à -30% selon les modèles). 2. Non-linéarité des processus : les fortes baisses piézométriques peuvent modifier les interactions nappe-rivière (rivière gagnante → rivière perdante) non reproduites par le modèle actuel. 3. Incertitude des paramètres du modèle (K, S) : l'incertitude sur les paramètres se propage à la prévision. La prévision doit être encadrée par une fourchette d'incertitude, pas donnée comme une valeur exacte." }
    ],
    flashcards: [
      { question: "Étapes de construction d'un modèle MODFLOW", reponse: "1. Modèle conceptuel (géologie, piézométrie, bilan). 2. Discrétisation (grille, couches, tops/bottoms). 3. Paramétrage initial (K, T, S par zonation). 4. CL et termes sources (RIV, WEL, RCH). 5. Calage (PEST) sur piézomètres. 6. Validation (période indépendante). 7. Scénarios de gestion." },
      { question: "Critère Nash-Sutcliffe (NSE) : interprétation", reponse: "NSE = 1 - Σres² / Σvar_obs. NSE = 1 : simulation parfaite. NSE = 0 : simulation équivalente à la moyenne des observations. NSE < 0 : simulation moins bonne que la moyenne. Seuils : > 0,65 satisfaisant, > 0,75 bon, > 0,85 excellent (selon Moriasi 2007)." },
      { question: "Qu'est-ce que PEST++ / iES ?", reponse: "PEST++ est la version moderne de PEST incluant des méthodes ensemblistes (iES = iterative Ensemble Smoother). Génère N réalisations de paramètres, les fait toutes tourner dans MODFLOW, puis met à jour l'ensemble par assimilation des observations (type filtre de Kalman). Produit directement une distribution a posteriori des paramètres et des prévisions. Standard actuel pour l'analyse d'incertitude en hydrogéologie." },
      { question: "Stress period dans MODFLOW : définition", reponse: "Intervalle de temps où tous les termes sources (pompages, recharge, cotes de rivière) restent constants. Une stress period peut avoir plusieurs time steps pour l'intégration numérique. Exemple : 12 stress periods annuelles = 12 mois avec prélèvements et recharge mensuels constants, subdivisés en time steps quotidiens. Les stress periods structurent le forçage temporel du modèle." },
      { question: "Sur-calage (overfitting) : symptômes et remèdes", reponse: "Symptômes : NSE de calage excellent, NSE de validation médiocre. Trop de paramètres pour le nombre d'observations. Remèdes : réduire le nombre de zones (simplifier), ajouter une régularisation Tikhonov (PEST), augmenter la période de calage, utiliser iES (ensemble moins sensible au sur-calage). Le modèle parcimonieux est préférable : le minimum de paramètres nécessaires pour un bon calage." },
      { question: "Problème de l'équifinalité en modélisation hydrogéologique", reponse: "Plusieurs jeux de paramètres différents peuvent donner des simulations également satisfaisantes des observations disponibles. Conséquence : le modèle n'est pas unique. Les prévisions peuvent diverger d'un jeu à l'autre (surtout pour les extrapolations hors conditions de calage). L'analyse d'incertitude (iES, Monte Carlo) explore l'espace des paramètres acceptables et quantifie la fourchette des prévisions." }
    ]
  },

  'MASTER-EAU-047': {
    id: 'MASTER-EAU-047',
    titre: "Calage inverse et évaluation des modèles hydrogéologiques",
    fiche: {
      intro: "Le calage (calibration) d'un modèle hydrogéologique est l'ajustement des paramètres pour reproduire les observations de terrain. Le problème inverse consiste à estimer les paramètres à partir des observations, à l'opposé du problème direct (simuler les observations à partir de paramètres connus). L'équifinalité, l'incertitude des données et le manque d'information rendant le problème inverse mal posé sont les défis centraux de la modélisation hydrogéologique.",
      sections: [
        { titre: "Formulation du problème inverse", sous_sections: [
          { titre: "Problème direct vs problème inverse", contenu: "Le problème direct calcule h(x,t) à partir des paramètres K(x), S(x) et des conditions aux limites. Il est toujours bien posé (solution unique). Le problème inverse estime K(x) et S(x) à partir des observations h_obs. Il est mal posé (au sens de Hadamard) : existence non garantie, non-unicité (équifinalité), instabilité (petites perturbations des données → grandes variations des paramètres). La régularisation (a priori sur les paramètres) est indispensable pour obtenir une solution physiquement plausible. Les méthodes d'inversion sont : régression non-linéaire (PEST), méthodes probabilistes (Monte Carlo, filtre de Kalman), inversion géostatistique (gradzone)." },
          { titre: "Équifinalité et non-unicité de la solution", contenu: "L'équifinalité (concept de Beven & Binley, 1992) désigne la situation où de multiples jeux de paramètres distincts simulent les observations avec une qualité identique ou équivalente. Dans les aquifères hétérogènes, différentes distributions spatiales de K peuvent produire le même champ de charge. Conséquence : les prévisions de scénarios doivent être basées sur un ensemble de modèles équifinaux, pas sur un modèle unique 'optimal'. L'approche GLUE (Generalised Likelihood Uncertainty Estimation) quantifie cela." }
        ]},
        { titre: "Méthodes d'inversion", sous_sections: [
          { titre: "Inversion par régression non-linéaire (PEST)", contenu: "PEST minimise φ = Σw_i(h_obs,i - h_sim,i)². L'algorithme de Levenberg-Marquardt calcule les dérivées ∂h_sim/∂pk par différences finies (runs MODFLOW + ε pour chaque paramètre). La matrice Jacobienne J_ij = ∂h_i/∂p_j est construite puis inversée (décomposition SVD). La régularisation de Tikhonov ajoute une pénalité sur la déviation des paramètres par rapport à leurs valeurs a priori : φ_total = φ_data + λ × φ_reg. λ est le poids de la régularisation. Cette méthode est rapide mais locale (peut converger vers un minimum local)." },
          { titre: "Méthodes ensemblistes (iES, EnKF)", contenu: "L'Ensemble Kalman Filter (EnKF) et son descendant iES (iterative Ensemble Smoother) font tourner N réalisations de paramètres simultanément et mettent à jour les paramètres par assimilation des observations (inversion probabiliste). L'ensemble représente directement la distribution a posteriori des paramètres et des prévisions. PEST++ propose iES comme outil standard. L'EnKF est utilisé en temps réel pour l'assimilation de données piézométriques. Ces méthodes explorent l'espace des solutions et capturent l'équifinalité mieux que PEST classique." }
        ]},
        { titre: "Métriques d'évaluation du calage", sous_sections: [
          { titre: "Métriques sur les niveaux piézométriques", contenu: "RMSE = √(Σ(h_obs - h_sim)²/N) : erreur quadratique moyenne (mètres). MAE = Σ|h_obs - h_sim|/N : erreur absolue moyenne. Biais = Σ(h_sim - h_obs)/N : biais systématique (positif = modèle trop haut). Nash-Sutcliffe NSE = 1 - RMSE²/var(h_obs) : efficacité du modèle. R² = corrélation entre observé et simulé. L'objectif est de minimiser RMSE et biais, maximiser NSE et R². Des métriques sur les tendances temporelles (variation piézométrique simulée vs observée) complètent l'évaluation." },
          { titre: "Calage multi-objectifs et contraintes", contenu: "Un bon calage reproduit simultanément les niveaux piézométriques ET les débits des sources ET les échanges nappe-rivière. L'optimisation multi-objectifs (Pareto) minimise les résidus sur plusieurs types d'observations. Les contraintes physiques (K > 0, S entre 0 et 1) sont imposées par des transformations logarithmiques des paramètres. La valeur d'information de chaque observation est mesurée par son influence sur la réduction d'incertitude des prédictions cibles (OPR : Observation Prediction Relationship dans PEST++)." }
        ]},
        { titre: "Analyse d'incertitude des prévisions", sous_sections: [
          { titre: "Propagation de l'incertitude des paramètres", contenu: "L'incertitude sur les paramètres se propage aux prévisions. Par linéarisation (δy = J × δp), l'incertitude des prévisions est σ²_pred = J_pred × (JᵀWJ + R)⁻¹ × J_pred^T. Les prévisions les plus incertaines sont celles qui dépendent fortement de paramètres peu contraints par les observations. L'analyse de Data Worth (DW dans PEST++) calcule la réduction d'incertitude apportée par un nouveau piézomètre ou un nouvel essai de pompage, guidant les stratégies d'investigation." },
          { titre: "Validation et robustesse du modèle", contenu: "La validation consiste à tester le modèle calé sur une période ou un contexte différent sans réajustement. Types de validation : validation temporelle (période différente), validation spatiale (zone non utilisée au calage), validation sur des processus différents (pompages d'essai non utilisés au calage). Un modèle qui valide mal révèle un défaut de modèle conceptuel ou un sur-calage. La robustesse est évaluée par la dégradation de la performance sur différentes périodes (split-sample test, differential split-sample test)." }
        ]}
      ],
      points: ["Problème inverse : estimer K(x), S(x) à partir de h_obs. Mal posé (non-unique, instable).", "Équifinalité (Beven & Binley) : multiples paramètres reproduisent les mêmes observations.", "PEST : inversion par Levenberg-Marquardt + régularisation Tikhonov.", "iES (PEST++) : inversion ensembliste, capture l'équifinalité, distribution a posteriori.", "RMSE, MAE, biais, NSE : métriques de calage piézométrique.", "Calage multi-objectifs : niveaux + débits sources + échanges nappe-rivière.", "Data Worth (PEST++) : valeur d'une nouvelle observation pour réduire l'incertitude.", "Validation temporelle : test sur période différente sans réajustement.", "Split-sample test : robustesse du modèle sur différentes périodes.", "Régularisation Tikhonov : pénalise les déviations des paramètres par rapport à l'a priori."],
      formules: [
        { nom: "Fonction objectif PEST (régularisée)", expression: "Φ_total = Φ_data + λ × Φ_reg = ||W^0.5(h_obs-h_sim)||² + λ||R(p-p_prior)||²", variables: "W = matrice de poids, λ = poids de régularisation, R = matrice de régularisation, p_prior = valeurs a priori" },
        { nom: "Mise à jour EnKF (Ensemble Kalman Filter)", expression: "pₐ = pf + K × (h_obs - H × pf)", variables: "pf = ensemble de paramètres prédit, K = gain de Kalman = Cf × Hᵀ(H×Cf×Hᵀ + R)⁻¹, Cf = covariance" },
        { nom: "Incertitude linéarisée des prévisions", expression: "σ²_pred ≈ J_pred × (JᵀWJ + R)⁻¹ × J_pred^T", variables: "J_pred = sensibilité des prédictions cibles aux paramètres, JᵀWJ = matrice d'information" },
        { nom: "Nash-Sutcliffe (rappel)", expression: "NSE = 1 - Σ(h_obs - h_sim)² / Σ(h_obs - h̄)²", variables: "NSE = 1 parfait, > 0,5 satisfaisant, < 0 pire que la moyenne" },
        { nom: "Dérivée sensibilité (PEST, différences finies)", expression: "∂h_i/∂p_j ≈ [h_i(p_j + δ) - h_i(p_j)] / δ", variables: "δ = perturbation du paramètre j (1%). Chaque dérivée nécessite 1 run MODFLOW supplémentaire" }
      ],
      retenir: "Le calage inverse est un problème mal posé : l'équifinalité est la règle, pas l'exception. PEST et PEST++/iES sont les outils standard. La régularisation Tikhonov contraint les paramètres vers des valeurs physiques. La validation sur une période indépendante est obligatoire. L'analyse d'incertitude (Data Worth, iES) quantifie les limites du modèle et guide les investigations futures."
    },
    exercices: [
      { id: 1, enonce: "PEST cale un modèle sur 60 piézomètres avec 15 paramètres de K. NSE_calage = 0,88. Mais une analyse avec iES (100 réalisations) donne NSE_P5-P95 = [0,42-0,91]. Interprétez.", correction: "NSE de calage élevé (0,88) mais l'ensemble iES montre une forte variabilité (P5 = 0,42). Cela indique une forte équifinalité : de nombreux jeux de K donnent des performances similaires au calage mais avec des prévisions potentiellement très différentes. Le modèle 'optimal' n'est qu'une des nombreuses solutions plausibles. Les prévisions doivent être accompagnées de fourchettes d'incertitude." },
      { id: 2, enonce: "La matrice Jacobienne d'un modèle a 60 observations et 15 paramètres. Combien de runs MODFLOW supplémentaires PEST doit-il effectuer pour calculer les sensibilités par différences finies ?", correction: "15 paramètres × 2 runs par paramètre (différences finies centrées) = 30 runs par itération. Si PEST utilise des différences finies avant (p + δ seulement) : 15 runs par itération. Sur 20 itérations : 300-600 runs MODFLOW totaux (en plus du run de référence). iES avec N=100 réalisations : 100 × N_iterations runs, mais en parallèle." },
      { id: 3, enonce: "Un modèle validé sur 2003-2010 (après calage sur 1990-2003) donne NSE = 0,45. Que signifie-t-il et comment améliorer ?", correction: "NSE validation = 0,45 < 0,5 : validation médiocre. Le modèle calé sur 1990-2003 ne reproduit pas correctement 2003-2010. Causes possibles : changement de régime de prélèvements (nouveaux captages ?), changement de recharge (sécheresse 2003 non représentative), sur-calage sur la période 1990-2003. Améliorations : étendre la période de calage à 1990-2010, investiguer les changements d'usage, simplifier la paramétisation (zonation moins détaillée)." },
      { id: 4, enonce: "Expliquez la régularisation Tikhonov dans PEST et pourquoi elle est nécessaire.", correction: "Sans régularisation, l'inversion de JᵀWJ est mal conditionnée (singulière si plus de paramètres que d'observations informatives). Tikhonov ajoute φ_reg = Σ(pk - pk_prior)². Cela force les paramètres à rester proches des valeurs a priori (initialisées depuis les essais de pompage). La régularisation rend le problème bien posé et évite des solutions physiquement absurdes (K négatifs, valeurs extrêmes). λ est choisi par Pareto : compromis entre ajustement des données et pénalité de régularisation." },
      { id: 5, enonce: "PEST++ Data Worth indique que l'ajout d'un 61ème piézomètre dans la zone A réduit l'incertitude de la prévision cible de 35%, contre 5% pour la zone B. Quelle décision prenez-vous ?", correction: "Installer un piézomètre en zone A. La réduction d'incertitude de 35% vs 5% montre que la zone A est la zone où l'information est la plus 'pauvre' par rapport à la prédiction cible (par exemple, le débit d'étiage d'une rivière). Ce type d'analyse aide à optimiser le coût des campagnes de terrain en focalisant les mesures là où elles apportent le plus d'information pour répondre à la question de gestion posée." },
      { id: 6, enonce: "Qu'est-ce que le problème direct et le problème inverse ? Donnez un exemple hydrogéologique de chacun.", correction: "Problème direct : calculer h(x,t) à partir de K(x), S(x), conditions aux limites → bien posé, solution unique. Exemple : simuler la baisse piézométrique pour un débit de pompage de 100 m³/h dans un aquifère de T connue. Problème inverse : estimer K(x) à partir des h_obs → mal posé, non-unique, instable. Exemple : estimer la distribution de K à partir des mesures piézométriques d'un réseau de 30 piézomètres." },
      { id: 7, enonce: "Calculez NSE si RMSE = 1,2 m et σ_obs = 2,0 m (écart-type des niveaux observés).", correction: "NSE = 1 - RMSE²/σ²_obs = 1 - 1,44/4,0 = 1 - 0,36 = 0,64. NSE légèrement supérieur à 0,65 : calage acceptable. L'écart-type des observations (2 m) reflète la variabilité spatiale ou temporelle des niveaux. RMSE = 1,2 m = 60% de σ_obs → encore une marge d'amélioration possible." },
      { id: 8, enonce: "Citez 3 avantages de iES (PEST++) par rapport à PEST classique pour le calage d'un modèle hydrogéologique.", correction: "1. Capture l'équifinalité : produit un ensemble de paramètres plausibles, pas un seul optimum. 2. Quantifie directement l'incertitude des prévisions (distribution a posteriori). 3. Plus robuste face aux minima locaux (exploration stochastique de l'espace des paramètres). Inconvénient : nécessite N × (nombre d'itérations) runs MODFLOW (100 × 10 = 1000 runs typiques), coût computationnel plus élevé, compensé par la parallélisation." }
    ],
    flashcards: [
      { question: "Problème inverse : pourquoi est-il mal posé ?", reponse: "Selon Hadamard : existence non garantie (observations contradictoires), non-unicité (équifinalité), instabilité (petites erreurs de mesure → grands changements de paramètres). La régularisation (Tikhonov) rend le problème bien posé en ajoutant de l'information a priori sur les paramètres." },
      { question: "Équifinalité : définition et implications", reponse: "Beven & Binley (1992) : multiples jeux de paramètres distincts simulent les observations avec une qualité équivalente. Implication : un seul modèle 'calé' ne suffit pas. Les prévisions doivent être basées sur un ensemble de modèles équifinaux → fourchettes d'incertitude obligatoires pour les décisions de gestion." },
      { question: "PEST : principe de fonctionnement", reponse: "Minimise φ = Σw(h_obs-h_sim)² par Levenberg-Marquardt. Calcule la matrice Jacobienne (sensibilités) par différences finies (N runs MODFLOW). Résout le système linéarisé à chaque itération. Régularisation Tikhonov contraint les paramètres vers les a priori. Fournit les paramètres optimaux + analyse de sensibilité + incertitudes linéarisées." },
      { question: "iES vs PEST : différences clés", reponse: "PEST : optimisation déterministe (Levenberg-Marquardt), converge vers un minimum local, incertitude linéarisée. iES : optimisation ensembliste stochastique (N réalisations), distribution a posteriori complète, robuste face aux minima locaux, capture l'équifinalité. PEST++ propose les deux. iES recommandé pour les modèles complexes." },
      { question: "Data Worth dans PEST++", reponse: "Quantifie la valeur d'une nouvelle observation (piézomètre, essai de pompage) pour réduire l'incertitude sur une prédiction cible. Calculé par différence de variance a posteriori avec/sans cette observation. Guide l'optimisation des campagnes de terrain : instrument là où l'information est la plus 'pauvre' par rapport aux questions de gestion." },
      { question: "Split-sample test : définition et utilité", reponse: "Division de la période de données en deux : calage sur la première moitié, validation sur la seconde (ou vice versa). Évalue la robustesse du modèle hors de la période de calage. Le test différentiel (differential split-sample) utilise des sous-périodes contrastées (sèches vs humides) pour tester la robustesse sur différents régimes hydrologiques." }
    ]
  },

  'MASTER-EAU-048': {
    id: 'MASTER-EAU-048',
    titre: 'Aquifères karstiques et milieux fracturés',
    fiche: {
      intro: "Les aquifères karstiques et fracturés représentent des défis particuliers pour l'hydrogéologie, car leur comportement non-darcien, leur hétérogénéité extrême et leur réponse rapide aux événements pluvieux les distinguent fondamentalement des aquifères poreux. Ces systèmes sont particulièrement vulnérables aux contaminations et nécessitent des approches spécifiques d'investigation et de modélisation.",
      sections: [
        { titre: "Spécificités hydrodynamiques du karst", sous_sections: [
          { titre: "Genèse et structure des systèmes karstiques", contenu: "Le karst résulte de la dissolution de roches carbonatées (calcaires, dolomies) par l'eau chargée de CO2 : CO2 + H2O + CaCO3 → Ca²⁺ + 2HCO3⁻. La dissolution préférentielle le long des discontinuités (joints, failles) crée un réseau de conduits drainants (spéléothèmes, galeries, rivières souterraines) connectant la zone d'infiltration à la zone d'émergence (source karstique). La structure karstique est trimodale : matrice poreuse (faible K, fort stockage), fractures (K intermédiaire, transferts), conduits (K extrême, transport rapide). La spéléologie et les traçages sont les outils d'investigation spécifiques." },
          { titre: "Réponse hydrodynamique aux événements pluvieux", contenu: "Les systèmes karstiques présentent une réponse très rapide aux précipitations (quelques heures à jours), avec des crues de source violentes et des contaminations rapides depuis la surface. Le débit de source varie sur plusieurs ordres de grandeur (Q_max/Q_min > 1000 dans les grands karsts). La courbe de tarissement de la source est multi-phasée (conduits → fractures → matrice). L'analyse des tarissements (courbes de débit vs temps) renseigne sur le volume stocké et les coefficients de tarissement de chaque réservoir." }
        ]},
        { titre: "Méthodes d'investigation des karsts", sous_sections: [
          { titre: "Traçages artificiels et naturels", contenu: "Le traçage artificiel injecte un traceur (fluorescéine, rhodamine B, sulforhodamine B, naphtionate) dans une perte, un puits ou une doline, et mesure sa concentration à la source. Il détermine la connexion hydraulique, la vitesse de transfert (quelques km/j dans les conduits), la dispersion et la dilution. Les traceurs naturels (température, conductivité, NO3⁻, Ca²⁺, Mg²⁺, δ¹⁸O) permettent un traçage permanent (voir chapitre 51). La méthode multi-traceurs simultanés caractérise la variabilité spatiale du réseau karstique." },
          { titre: "Analyse de la courbe de tarissement", contenu: "La source karstique se tarie selon Q(t) = Q0 × exp(-α×t) pour chaque réservoir. L'analyse de la récession (méthode de Mangin, traitement des courbes Q vs t) identifie plusieurs phases de tarissement correspondant aux réservoirs conduits, fractures et matrice. Le coefficient α (j⁻¹) est caractéristique : conduits α ≈ 10⁻¹ j⁻¹, fractures α ≈ 10⁻² j⁻¹, matrice α ≈ 10⁻³ j⁻¹. Le volume stocké V = Q/α est estimé pour chaque réservoir. Ces paramètres guident la gestion des captages karstiques." }
        ]},
        { titre: "Modélisation des systèmes karstiques", sous_sections: [
          { titre: "Approches lumped et semi-distributed", contenu: "Les modèles globaux (lumped) représentent le système karstique par des réservoirs conceptuels (KarstMod, VENSIM) : réservoir de surface → réservoir épikarstique → réservoir non saturé → réservoir saturé de matrice → conduits → source. Les flux entre réservoirs sont calibrés sur les débits de source. Ces modèles sont simples, robustes et adaptés à la gestion. Les modèles semi-distribués (SWMM, MIKE-SHE avec modules karstiques) représentent spatialement le bassin d'alimentation mais simplifier la structure des conduits." },
          { titre: "Modèles d'écoulement dual-poreux (MODFLOW CFP)", contenu: "MODFLOW-CFP (Conduit Flow Process) couple l'équation de Darcy dans la matrice et l'équation de Navier-Stokes-Poiseuille dans les conduits. Les conduits sont représentés par un réseau de tubes circulaires de diamètre variable. L'échange conduit-matrice est modélisé par un terme de transfert (α_exchange × (h_conduit - h_matrice)). Ces modèles distribuent nécessitent la géométrie du réseau de conduits (spéléologie, géophysique) et sont rarement calables avec précision (hétérogénéité extrême). Ils sont adaptés aux études fondamentales et aux captages karstiques stratégiques." }
        ]},
        { titre: "Vulnérabilité et protection des ressources karstiques", sous_sections: [
          { titre: "Vulnérabilité intrinsèque des karsts", contenu: "Les aquifères karstiques sont extrêmement vulnérables à la contamination : transferts rapides (quelques heures depuis la surface via les pertes et dolines), absence de filtration par la zone non saturée (par les conduits), et forte variabilité spatiale de la vulnérabilité (extrême sur les conduits, faible sur la matrice). La méthode EPIK (Epikarst, Protection, Infiltration, Karst) évalue la vulnérabilité spécifiquement pour les karsts, avec des pondérations différentes des méthodes matricielles. Les zones de pertes concentrées sont les points d'entrée privilégiés des contaminants." },
          { titre: "Périmètres de protection des captages karstiques", contenu: "La délimitation des périmètres de protection pour les captages karstiques ne peut pas utiliser les méthodes hydrogéologiques classiques (rayon de capture calculé par traçage de particules dans un modèle Darcy). Le bassin d'alimentation topographique ne coincide pas nécessairement avec le bassin hydrogéologique (connexions souterraines complexes). La méthode de référence est le traçage multi-traceurs : injection en de multiples points puis détection à la source. Le bassin d'alimentation est délimité par les points de traçage positifs, et le temps de transfert guide la délimitation des PPR et PPI." }
        ]}
      ],
      points: ["Triple porosité karstique : matrice (stock) + fractures (transfert) + conduits (drainage rapide).", "Q_max/Q_min > 1000 dans les grands karsts. Réponse en quelques heures.", "Traçage à la fluorescéine/rhodamine : connexion, vitesse, dispersion.", "Tarissement karstique : Q(t) = Q0 exp(-αt), multi-phases (conduits α ≈ 0,1 j⁻¹, matrice α ≈ 0,001 j⁻¹).", "KarstMod : modèle à réservoirs globaux pour gestion des captages karstiques.", "MODFLOW-CFP : modèle distribué dual-poreux (Darcy + Navier-Stokes dans conduits).", "EPIK : méthode de vulnérabilité spécifique aux karsts.", "Bassin karstique ≠ bassin topographique : connexions souterraines complexes.", "Pertes et dolines = points d'entrée prioritaires des contaminants.", "Loi cubique : K_conduit ∝ r⁴ (Poiseuille → très sensible au rayon)."],
      formules: [
        { nom: "Dissolution karstique (calcaire)", expression: "CO₂ + H₂O + CaCO₃ → Ca²⁺ + 2HCO₃⁻", variables: "Réaction contrôlée par la pCO2 du sol et la température. Vitesse ∝ [H2CO3] × surface spécifique" },
        { nom: "Loi de Poiseuille (conduit circulaire)", expression: "Q = (π × r⁴ × ΔP) / (8 × μ × L)", variables: "r = rayon du conduit, ΔP = différence de pression, μ = viscosité dynamique. K_conduit ∝ r²" },
        { nom: "Courbe de tarissement karstique", expression: "Q(t) = Q₀ × exp(-α × t)",  variables: "α = coefficient de tarissement (j⁻¹), Q₀ = débit initial. Volume stocké V = Q₀/α" },
        { nom: "Répartition flux conduits vs matrice", expression: "Q_total = Q_conduits + Q_matrice = α_c × V_c × exp(-α_c t) + α_m × V_m × exp(-α_m t)", variables: "Q_c : débit conduits (rapide), Q_m : débit matrice (lent), V = volumes stockés" },
        { nom: "Nombre de Reynolds pour conduit karstique", expression: "Re = ρ × v × D / μ = Q / (ν × π × r)", variables: "Re > 2300 → régime turbulent (Navier-Stokes), Darcy ne s'applique plus. Typique dans conduits." }
      ],
      retenir: "Les aquifères karstiques se distinguent par leur triple porosité, leurs transferts rapides par conduits et leur vulnérabilité extrême. L'analyse des tarissements et les traçages multi-traceurs sont les méthodes d'investigation de base. La modélisation par réservoirs (KarstMod) est adaptée à la gestion, MODFLOW-CFP pour les études distribuées. La protection des captages karstiques requiert une délimitation par traçage du bassin d'alimentation réel."
    },
    exercices: [
      { id: 1, enonce: "La source karstique de Fontaine-de-Vaucluse a un débit de tarissement modélisé par 3 composantes : conduits (α=0,15 j⁻¹, V=0,8 Mm³), fractures (α=0,02 j⁻¹, V=5 Mm³), matrice (α=0,002 j⁻¹, V=25 Mm³). Calculez Q(t=30j) pour chaque composante.", correction: "Conduits : Q_c = α_c × V_c × exp(-α_c×t) = 0,15 × 0,8 × exp(-0,15×30) = 0,12 × exp(-4,5) = 0,12 × 0,011 = 0,00132 Mm³/j = 1320 m³/j. Fractures : Q_f = 0,02 × 5 × exp(-0,6) = 0,1 × 0,549 = 0,0549 Mm³/j = 54900 m³/j. Matrice : Q_m = 0,002 × 25 × exp(-0,06) = 0,05 × 0,942 = 0,0471 Mm³/j = 47100 m³/j. Total à j30 dominé par la matrice." },
      { id: 2, enonce: "Un traceur injecté dans une perte karstique à 5 km de la source est détecté après 18h. Calculez la vitesse de transfert et évaluez si Darcy est applicable.", correction: "v = 5000/18 = 277 m/h = 4,6 m/min = 0,077 m/s = 7,7 cm/s. Dans un conduit de r = 0,1 m : Re = v×2r/ν = 0,077×0,2/10⁻⁶ = 15400 >> 2300 → régime turbulent. Darcy inapplicable. Navier-Stokes ou équation de Forchheimer nécessaires dans les conduits." },
      { id: 3, enonce: "Expliquez pourquoi la délimitation des PPR par calcul de rayon de capture Darcy est inadaptée aux captages karstiques.", correction: "Le rayon de capture Darcy suppose un milieu homogène et isotrope avec un écoulement continu. Dans un karst : les conduits créent des vitesses très supérieures à Darcy dans des directions préférentielles (souvent indépendantes du gradient hydraulique régional). Le bassin d'alimentation peut être beaucoup plus étendu que le rayon calculé, dans des directions non intuitives (connexions souterraines par des conduits orientés selon les fractures, pas le gradient). Seul le traçage multi-points délimite le bassin réel." },
      { id: 4, enonce: "Calculez le débit dans un conduit karstique circulaire de r = 5 cm, de longueur 1 km, sous une différence de pression ΔP = 500 Pa. ν = 10⁻⁶ m²/s, ρ = 1000 kg/m³.", correction: "Q = πr⁴ΔP/(8μL) = π×(0,05)⁴×500/(8×10⁻³×1000) = π×6,25×10⁻⁶×500/8 = π×3,125×10⁻³/8 = 1,23×10⁻³ m³/s = 1,23 L/s. Re = Q/(ν×π×r) = 1,23×10⁻³/(10⁻⁶×π×0,05) = 1,23×10⁻³/1,57×10⁻⁷ = 7834 >> 2300 → turbulent. La formule de Poiseuille surestime Q." },
      { id: 5, enonce: "Citez 3 indicateurs de terrain permettant d'identifier la présence d'un aquifère karstique.", correction: "1. Sources karstiques avec débit très variable (Q_max/Q_min > 100), eau dure (forte teneur en Ca²⁺ et HCO3⁻). 2. Morphologie karstique en surface : dolines, poljes, lapiés, vallées sèches, pertes (rivières s'infiltrant). 3. Chimie de l'eau : fort TH (Ca²⁺ + Mg²⁺), CO2 agressif, pH 7-8, réponse turbide lors des crues (entraînement de matières en suspension depuis la surface via les conduits)." },
      { id: 6, enonce: "Qu'est-ce que l'épikarst et quel rôle joue-t-il dans la vulnérabilité des captages ?", correction: "L'épikarst est la zone supérieure du massif carbonaté (1-10 m), fortement karstifiée par les eaux d'infiltration et les variations saisonnières humidification/dessiccation. Il fonctionne comme un réservoir transitoire (stock d'eau) et comme un collecteur-redistributeur des infiltrations. L'épikarst capte les infiltrations sur de grandes surfaces et les concentre en points d'entrée préférentiels (chenaux karstiques). Pour la vulnérabilité : l'épikarst accélère et concentre la transmission des contaminants de surface vers les conduits → vulnérabilité maximale dans les zones à épikarst développé." },
      { id: 7, enonce: "Comparez les approches KarstMod (réservoirs globaux) et MODFLOW-CFP (distribué) pour la gestion d'un captage karstique.", correction: "KarstMod : simple, calable sur débits de source, adapté à la gestion opérationnelle (prévision de débit, évaluation des réserves). Ne représente pas la spatialisation. Pas de simulation de la vulnérabilité spatiale. MODFLOW-CFP : distribué, représente la géométrie des conduits (si connue), simule les zones de capture et les temps de transfert. Nécessite des données de spéléologie et de traçage. Très difficile à caler. Adapté aux études fondamentales et aux captages stratégiques. En pratique : KarstMod pour gestion, MODFLOW-CFP pour études de vulnérabilité." },
      { id: 8, enonce: "Un captage karstique alimente 50 000 personnes. 3 injections de traceurs à 3, 7 et 12 km de la source donnent respectivement des détections positives, positive et négative. Délimitez le PPR et PPI.", correction: "Connexions confirmées à 3 km (détection positive) et 7 km (positive) mais pas à 12 km (négative) dans cette direction. Le bassin d'alimentation inclut au moins la zone jusqu'à 7 km dans la direction des injections positives. PPR (< 50 jours de transfert) : délimité par les temps de transfert mesurés (vitesse ≈ quelques km/j dans les conduits) → rayon ~quelques km. PPI (zone élargie) : inclut la zone de 7 km. Zone à 12 km : non connectée dans cette direction. Les 3 injections ne définissent pas le contour complet : traçages complémentaires dans les autres directions nécessaires." }
    ],
    flashcards: [
      { question: "Triple porosité karstique : rôles respectifs", reponse: "Matrice poreuse : fort stockage, faible K → soutient les étiages (tarissement lent, α ≈ 0,001 j⁻¹). Fractures : transfert intermédiaire, stockage modéré (α ≈ 0,01-0,1 j⁻¹). Conduits : drainage rapide, stockage faible, K extrême (non-Darcy) → crues de source, contaminations rapides (α ≈ 0,1-1 j⁻¹)." },
      { question: "Traçage karstique : traceurs et paramètres estimés", reponse: "Fluorescéine, rhodamine B, sulforhodamine B (fluorescents). Naphtionate (UV). Injection en perte/doline, détection à la source (fluorimètre). Paramètres : temps de transit (vitesse = distance/temps), courbe de restitution → dispersion (variance), taux de restitution → pertes par stockage ou dilution. Multi-traceurs : structure spatiale du réseau." },
      { question: "Méthode EPIK pour la vulnérabilité karstique", reponse: "E = Epikarst (développement et protection). P = Protection (couverture du sol et zone non saturée). I = Infiltration (type : concentrée via pertes vs diffuse). K = Karst (développement du réseau karstique). Chaque facteur noté 1-4, pondéré. Score faible → vulnérabilité élevée. Plus spécifique aux karsts que DRASTIC (qui sous-estime la vulnérabilité karstique)." },
      { question: "Loi de Poiseuille vs loi de Darcy : limites de validité", reponse: "Darcy : valide si Re = vd/ν < 1-10 (écoulement laminaire en milieu poreux). Poiseuille (conduit laminaire) : valide si Re < 2300. Au-delà (Re > 2300) → turbulence, Navier-Stokes. Dans les conduits karstiques (vitesses de m/s) : Re >> 2300 → Darcy ET Poiseuille inapplicables. Forchheimer : extension de Darcy aux régimes inertiels." },
      { question: "Courbe de tarissement karstique : interprétation", reponse: "Q(t) = Σ Qi0 × exp(-αi × t). Plusieurs droites en semi-log correspondent aux réservoirs. Pente forte (α grand) = réservoirs à vidange rapide (conduits). Pente faible (α petit) = réservoirs à vidange lente (matrice). Méthode de Mangin : séparation graphique des composantes. Volume stocké V = Q0/α. Guide la gestion de l'alimentation en eau (réserve exploitable)." },
      { question: "Bassin d'alimentation topographique vs karstique", reponse: "Topographique : délimité par les lignes de crête topographiques (versants). Karstique : délimité par les connexions hydrauliques souterraines (conduits, fractures). Ces deux bassins ne coincident généralement pas. Des traçages peuvent montrer que l'eau d'un bassin topographique adjacent s'écoule vers la source d'un autre bassin (captures karstiques). Seul le traçage multi-traceurs délimite le bassin hydrogéologique réel." }
    ]
  },

  'MASTER-EAU-049': {
    id: 'MASTER-EAU-049',
    titre: "Aquifères côtiers et écoulements à densité variable",
    fiche: {
      intro: "Dans les aquifères côtiers, l'eau douce et l'eau salée marine coexistent. L'interface de Ghyben-Herzberg, la dispersion hydrodynamique et les fluctuations de marée régissent la dynamique de cette zone de transition. La surexploitation des aquifères côtiers entraîne l'intrusion saline, menaçant l'alimentation en eau de millions de personnes dans les zones côtières du monde.",
      sections: [
        { titre: "Interface eau douce - eau salée", sous_sections: [
          { titre: "Principe de Ghyben-Herzberg", contenu: "Dans un aquifère côtier libre, l'eau douce (ρf ≈ 1000 kg/m³) flotte sur l'eau salée (ρs ≈ 1025 kg/m³) selon la relation de Ghyben-Herzberg : z = ρf/(ρs-ρf) × h = 40 × h, où h est la charge piézométrique au-dessus du niveau de la mer et z la profondeur de l'interface sous le niveau de la mer. Pour h = 1 m au-dessus de la mer → interface à -40 m sous le niveau de la mer. Cette relation simple indique que chaque mètre d'abaissement piézométrique entraîne une montée de l'interface de 40 m. Elle suppose une interface abrupte (pas de dispersion)." },
          { titre: "Zone de mélange et dispersion", contenu: "En réalité, l'interface n'est pas abrupte mais une zone de mélange de quelques mètres à dizaines de mètres d'épaisseur. La dispersion hydrodynamique (mécanique + moléculaire) crée une transition progressive entre eau douce (Cl < 100 mg/L) et eau salée (Cl ≈ 19 g/L). La zone de mélange est caractérisée par une conductivité électrique intermédiaire (mesurable en forage). Les fluctuations de marée induisent des cycles de mélange accélèrent la dispersion (effet de pompage tidal). Dans les aquifères captifs côtiers, l'interface peut remonter de plusieurs dizaines de mètres sans signe de surface." }
        ]},
        { titre: "Intrusion saline et surexploitation", sous_sections: [
          { titre: "Mécanismes et causes de l'intrusion saline", contenu: "L'intrusion saline résulte d'un déséquilibre entre la recharge (pression hydraulique douce) et les prélèvements (abaissement de la nappe). Causes principales : surpompage (prélèvements > recharge naturelle), sécheresses prolongées (réduction de recharge), élévation du niveau marin (pushing the interface inland), baisse du niveau des terres (subsidence). Dans les deltas (Mekong, Nil, Ganges), la combinaison de subsidence + élévation marine crée une intrusion saline dramatique. En France, les aquifères côtiers du Languedoc et de PACA sont menacés." },
          { titre: "Diagnostic et surveillance de l'intrusion saline", contenu: "La surveillance de l'intrusion saline utilise : des piézomètres côtiers avec mesure de conductivité électrique (CE), des profils verticaux de CE en forage (détection de l'interface), des diagraphies électriques, des sondages électriques de surface (ERT) et électromagnétiques (FDEM, TDEM). Les seuils réglementaires pour l'eau potable : Cl < 250 mg/L (OMS). En France, les prélèvements dans les aquifères côtiers font l'objet d'arrêtés préfectoraux limitatifs et d'une surveillance renforcée." }
        ]},
        { titre: "Modélisation des écoulements à densité variable", sous_sections: [
          { titre: "Équations de transport-diffusion-densité", contenu: "L'écoulement à densité variable est régi par le couplage des équations de Darcy généralisée (avec terme de poussée d'Archimède), de transport de sel et d'état de densité : ρ = ρf + (ρs-ρf)×C/C_s où C est la concentration et C_s la concentration de l'eau de mer. Les équations sont fortement couplées (non-linéaires). Le problème de Henry (1964) et le benchmark SEAWAT (Langevin et al.) sont les références de validation des codes. L'instabilité de Rayleigh-Taylor peut provoquer des doigts de salinité convectifs dans les aquifères très perméables." },
          { titre: "Codes de modélisation (SEAWAT, SUTRA, FEFLOW)", contenu: "SEAWAT (USGS) couple MODFLOW et MT3DMS pour simuler les écoulements à densité variable. SUTRA (USGS) résout les équations couplées par éléments finis en 2D/3D. FEFLOW (DHI) est un code commercial polyvalent gérant la densité variable. Ces codes nécessitent la description de la géométrie de l'aquifère côtier, les conditions aux limites marines (charge imposée + concentration), les taux de recharge et les prélèvements. La calibration utilise les profils de conductivité électrique observés dans les forages." }
        ]},
        { titre: "Gestion des aquifères côtiers", sous_sections: [
          { titre: "Stratégies de lutte contre l'intrusion saline", contenu: "Les stratégies de gestion comprennent : la réduction des prélèvements (limitation des pompages, arrêtés de restriction), la recharge artificielle (injection d'eau douce pour repousser l'interface), les barrières hydrauliques (pompage entre la mer et les puits pour créer un gradient de pression empêchant l'intrusion), la substitution de ressources (transfert depuis des aquifères intérieurs). La recharge artificielle par injection (aquifer storage and recovery, ASR) est la solution la plus durable. En Israël, le plan de gestion de l'aquifère côtier de la plaine côtière a réussi à repousser l'intrusion saline par combinaison recharge + réduction des pompages." },
          { titre: "Impact du changement climatique sur les aquifères côtiers", contenu: "L'élévation du niveau marin (SLR) prévu de 0,3 à 1 m d'ici 2100 (IPCC AR6) va directement pousser l'interface eau douce/eau salée vers l'intérieur des terres. Pour chaque cm d'élévation marine, l'interface monte de 40 cm (Ghyben-Herzberg). La réduction des recharges dans les zones côtières méditerranéennes aggrave l'intrusion. Les aquifères insulaires (petites îles océaniques) sont particulièrement vulnérables : la lentille d'eau douce peut disparaître en quelques décennies (atoll de Maldives, Fidji)." }
        ]}
      ],
      points: ["Ghyben-Herzberg : z = 40 × h. Interface à -40 m pour h = +1 m au-dessus de la mer.", "Zone de mélange : quelques mètres à dizaines de mètres. Dispersion par marées.", "Intrusion saline : surpompage + sécheresses + élévation marine + subsidence.", "Diagnostic : CE en forage, profils verticaux, ERT, TDEM.", "Seuil AEP : Cl < 250 mg/L (OMS).", "SEAWAT (USGS) : couplage MODFLOW + MT3DMS, densité variable.", "SUTRA, FEFLOW : éléments finis pour écoulements à densité variable.", "Barrière hydraulique : pompage côtier pour bloquer l'intrusion.", "SLR = +1 cm → interface monte de 40 cm (Ghyben-Herzberg).", "ASR (Aquifer Storage and Recovery) : recharge artificielle par injection."],
      formules: [
        { nom: "Relation de Ghyben-Herzberg", expression: "z = ρf / (ρs - ρf) × h = 40 × h", variables: "z = profondeur interface sous niveau mer (m), h = charge piézométrique au-dessus de la mer (m)" },
        { nom: "Densité de l'eau en fonction de la salinité", expression: "ρ = ρf + (ρs - ρf) × C / Cs", variables: "C = concentration en sel (kg/m³), Cs = salinité de l'eau de mer (35 kg/m³)" },
        { nom: "Équation couplée de transport salin", expression: "∂(nC)/∂t = ∇·(D·∇C) - ∇·(vC) ± Qsources", variables: "D = tenseur de dispersion hydrodynamique, v = vitesse de pore, C = concentration" },
        { nom: "Débit de décharge de l'eau douce côtière", expression: "Qf = Kf × h × (h + z) / 2 × n",  variables: "Qf = débit de décharge (m²/s par unité de longueur côtière), h = charge piézométrique" },
        { nom: "Profondeur de l'interface après abaissement piézométrique", expression: "Δz = 40 × Δh", variables: "Δh = abaissement piézométrique (m), Δz = montée de l'interface vers la surface (m)" }
      ],
      retenir: "La relation de Ghyben-Herzberg (z = 40h) est le fondement de la gestion des aquifères côtiers : chaque mètre d'abaissement piézométrique provoque une montée de 40 m de l'interface. L'intrusion saline est aggravée par la surexploitation, les sécheresses et l'élévation du niveau marin. La modélisation à densité variable (SEAWAT, SUTRA) est indispensable pour prévoir l'évolution de l'intrusion. La recharge artificielle et les barrières hydrauliques sont les principales stratégies de lutte."
    },
    exercices: [
      { id: 1, enonce: "Un aquifère côtier libre a une charge piézométrique de 2,5 m au-dessus de la mer. L'aquifère est surpompé et la charge tombe à 1,8 m. De combien monte l'interface ?", correction: "Δh = 2,5 - 1,8 = 0,7 m de baisse piézométrique. Δz = 40 × 0,7 = 28 m de montée de l'interface. L'interface passe de -100 m (2,5×40) à -72 m (1,8×40). Montée de 28 m, risque d'atteindre des puits profonds." },
      { id: 2, enonce: "Le niveau marin monte de 50 cm d'ici 2100 (scénario IPCC modéré). La charge piézométrique reste constante à 1,5 m. Calculez la montée de l'interface.", correction: "L'élévation marine de 0,5 m équivaut à une réduction de h de 0,5 m (le niveau marin monte, réduisant la charge relative eau douce). Nouvelles profondeur interface = 40 × (1,5 - 0,5) = 40 × 1,0 = -40 m. Initialement : -60 m. Montée de 20 m d'ici 2100." },
      { id: 3, enonce: "Un profil de CE en forage montre CE = 500 μS/cm à 20 m de profondeur et CE = 45 mS/cm à 60 m (eau de mer ≈ 50 mS/cm). Où se trouve la zone de mélange ?", correction: "CE eau douce typique : 100-800 μS/cm. CE eau de mer : 50 mS/cm = 50 000 μS/cm. La zone de mélange est entre 20 m (CE douce) et environ 55-60 m (CE marine). La zone de mélange s'étend sur environ 35-40 m de profondeur dans ce forage. Interface approximative à ~40 m (CE intermédiaire ≈ 25 mS/cm)." },
      { id: 4, enonce: "Citez 3 avantages et 3 inconvénients de la recharge artificielle par injection (ASR) pour lutter contre l'intrusion saline.", correction: "Avantages : 1. Repousse activement l'interface (recharge directe dans la zone menacée). 2. Peut utiliser des eaux excédentaires en hiver (récupération en été). 3. Solution durable si ressources en eau disponibles. Inconvénients : 1. Coût élevé (forage injecteur + traitement de l'eau). 2. Colmatage progressif des forages (nettoyage régulier). 3. Risque de contamination de l'aquifère si eau injectée non conforme." },
      { id: 5, enonce: "Expliquez le phénomène d'instabilité de Rayleigh-Taylor dans un aquifère côtier.", correction: "Si l'eau salée (dense) surmonte l'eau douce (légère), la configuration est gravitairement instable. Des 'doigts' de salinité plongent vers le bas et de l'eau douce remonte (convection de densité). Ce phénomène se produit dans les aquifères côtiers très perméables où l'eau de mer est infiltrée depuis la surface (inondation, marée). Il accélère fortement le mélange et la salinisation. Visible dans les simulations SEAWAT avec de petites perturbations initiales." },
      { id: 6, enonce: "Calculez la profondeur de l'interface sur une île volcanique (200 m de rayon, h = 3 m au sommet, perméabilité radialement uniforme).", correction: "Ghyben-Herzberg : interface à -40 × h sous le niveau de la mer. Au centre de l'île (h max), z = -120 m. À la côte (h → 0), z → 0 m. La lentille d'eau douce a une forme de 'lentille' biconvexe. Volume approximatif ∝ h_max × R². Sur une petite île, la lentille est fine et vulnérable aux sécheresses et aux pompages." },
      { id: 7, enonce: "Qu'est-ce que SEAWAT et pour quel type de problème l'utilise-t-on ?", correction: "SEAWAT couple MODFLOW (écoulement) et MT3DMS (transport) pour simuler les écoulements à densité variable (eau douce + eau salée). Résout simultanément : équation de flux avec densité variable (terme de poussée gravitaire), équation de transport du sel (advection + dispersion). Utilisations : intrusion saline côtière, estuaires souterrains, aquifères géothermaux (eau chaude-froide), stockage de déchets nucléaires dans des formations salines." },
      { id: 8, enonce: "Un aquifère côtier captif à -80 m a Cl = 350 mg/L (seuil AEP dépassé). Citez les causes probables et les mesures d'urgence.", correction: "Causes : surpompage de l'aquifère captif (baisse de la charge en dessous de la charge marine → intrusion), défaut d'étanchéité de la crépine (court-circuit avec l'eau salée de surface), connexion avec la mer par des failles. Mesures d'urgence : 1. Arrêt immédiat du pompage dans l'aquifère concerné. 2. Pompage depuis un aquifère alternatif (si disponible). 3. Surveillance de la remontée de l'interface (CE en temps réel). 4. Diagnostic hydraulique (essai de pompage avec mesure de salinité)." }
    ],
    flashcards: [
      { question: "Relation de Ghyben-Herzberg : signification", reponse: "z = ρf/(ρs-ρf) × h = 40 × h. L'interface eau douce/eau salée se trouve à 40× la hauteur piézométrique sous le niveau de la mer. Pour h = 1 m NGF → interface à -40 m. Toute baisse de nappe de 1 m remonte l'interface de 40 m. Base de tout raisonnement sur les aquifères côtiers." },
      { question: "Causes de l'intrusion saline", reponse: "1. Surpompage : réduction de h → montée de l'interface (40×Δh). 2. Sécheresses prolongées : réduction de recharge → baisse h. 3. Élévation du niveau marin (SLR) : pousse l'interface vers l'intérieur. 4. Subsidence des terres (pompage eaux souterraines, compaction). 5. Exploitation minière côtière. Combinaison de causes dans les deltas asiatiques (Mekong, Chao Phraya, Huang He)." },
      { question: "SEAWAT vs MODFLOW classique", reponse: "MODFLOW classique : densité constante (eau douce uniquement). Pas de terme de flottabilité. SEAWAT : densité variable, couplage flux-transport-densité. Utilise MODFLOW + MT3DMS. Résout simultanément l'écoulement et le transport. Obligatoire pour : zones côtières, eau géothermale, déchets salins." },
      { question: "Stratégies de lutte contre l'intrusion saline", reponse: "1. Réduction des pompages (restriction réglementaire). 2. Recharge artificielle par injection (ASR). 3. Barrière hydraulique (puits côtier de pompage intercalé entre mer et puits AEP). 4. Substitution de ressources (import eau depuis zones non côtières). 5. Dessalement (eau de mer → eau douce, énergivore). La prévention vaut mieux que la remédiation (l'interface met des décennies à reculer une fois avancée)." },
      { question: "Impact du changement climatique sur les aquifères côtiers", reponse: "SLR : +1 cm → interface monte de 40 cm (Ghyben-Herzberg). Réduction recharge en Méditerranée : baisse h additionnelle. Augmentation des sécheresses : recharge épisodique réduite. Combinaison : aquifères côtiers méditerranéens et insulaires en fort risque. Atoll de Tuvalu : lentille d'eau douce < 10 m d'épaisseur, disparaîtra avant la submersion de l'île." },
      { question: "Zone de mélange eau douce/eau salée", reponse: "Pas une interface abrupte mais une zone de transition de quelques mètres (aquifères homogènes) à dizaines de mètres (aquifères hétérogènes + marées). Caractérisée par la conductivité électrique (CE) : eau douce < 1000 μS/cm, eau de mer ≈ 50 000 μS/cm. Les fluctuations de marée amplifient le mélange (effet de pompage). La dispersion longitudinale Dh = αL × v, dispersion transversale = αT × v." }
    ]
  },

  'MASTER-EAU-050': {
    id: 'MASTER-EAU-050',
    titre: 'Advection, dispersion et transport des solutés',
    fiche: {
      intro: "Le transport des solutés dans les aquifères est régi par l'équation d'advection-dispersion (ADE), qui combine le transport par le flux (advection) et l'étalement par les hétérogénéités de vitesse (dispersion). La compréhension de ces processus est fondamentale pour évaluer la migration des contaminants, dimensionner les procédures de réhabilitation et protéger les captages d'eau potable.",
      sections: [
        { titre: "Mécanismes de transport", sous_sections: [
          { titre: "Advection et dispersion mécanique", contenu: "L'advection transporte les solutés à la vitesse moyenne de pore v = q/ne. La dispersion mécanique résulte des variations de vitesse à différentes échelles : au niveau des pores (chemins différents dans le réseau), à l'échelle de l'échantillon (variations de K dans la zone de mesure), à l'échelle de l'aquifère (hétérogénéités macroscopiques). La dispersion longitudinale (dans la direction du flux) est caractérisée par la dispersivité longitudinale αL : DL = αL × v + D* (D* = diffusion moléculaire effective). La dispersivité transversale αT ≈ αL/10 (règle empirique)." },
          { titre: "Diffusion moléculaire et rétention", contenu: "La diffusion moléculaire D* = Dm × τ (Dm = diffusion en eau libre ≈ 10⁻⁹ m²/s, τ = facteur de tortuosité ≈ 0,1-0,7) est importante à faibles vitesses (Dm/DL > 0,1 si v < 10⁻⁷ m/s). L'adsorption sur les argiles et la matière organique retarde le transport : le facteur de retard R = 1 + (ρb/ne) × Kd, où Kd est le coefficient de partage sol-eau. Pour les pesticides : R de 2 à 100+. La dégradation (biotique ou abiotique) réduit la concentration : ∂C/∂t = -λC (λ = constante de dégradation de premier ordre, demi-vie T½ = ln2/λ)." }
        ]},
        { titre: "Équation d'advection-dispersion (ADE)", sous_sections: [
          { titre: "Formulation de l'ADE et solutions analytiques", contenu: "L'ADE 1D : R×∂C/∂t = DL×∂²C/∂x² - v×∂C/∂x - λ×R×C. Les solutions analytiques existent pour des cas simples : injection en créneau dans un milieu semi-infini (solution d'Ogata-Banks), injection continue (front étalé par erfc). Le nombre de Péclet Pe = v×L/DL caractérise le régime : Pe << 1 : dispersion dominante. Pe >> 1 : advection dominante (front raide). En hydrogéologie, Pe est souvent >> 1 à l'échelle de terrain (advection dominante, front difficile à représenter numériquement)." },
          { titre: "Dispersivité et dépendance à l'échelle", contenu: "La dispersivité longitudinale αL augmente avec l'échelle spatiale d'observation : relation empirique αL ≈ 0,1 × L (10% de la longueur d'investigation). Cette dépendance à l'échelle reflète l'augmentation de l'hétérogénéité vue par le panache à mesure qu'il s'étend. Pour L = 10 m → αL ≈ 1 m. Pour L = 1 km → αL ≈ 100 m. Conséquence : les modèles de transport à petite échelle (laboratoire) sous-estiment considérablement la dispersion à l'échelle de terrain." }
        ]},
        { titre: "Transport des contaminants et réhabilitation", sous_sections: [
          { titre: "Panaches de contaminants et prévision", contenu: "Un panache de contaminant est la zone de concentration > seuil réglementaire. Sa géométrie dépend du débit, de la vitesse de Darcy, de la dispersivité, du facteur de retard et de la biodégradation. La simulation numérique (MT3DMS, FEFLOW transport) résout l'ADE sur la grille MODFLOW. Les instabilités numériques (oscillations) apparaissent si Cr = v×Δt/Δx > 1 ou Pe > 2. Les méthodes de transport des caractéristiques (MOC, random walk) sont stables pour les régimes advectifs dominants." },
          { titre: "Techniques de réhabilitation des aquifères contaminés", contenu: "Pump-and-treat : pompage de l'eau contaminée et traitement en surface. Efficace pour contenir le panache mais lent (effet 'tailing' dû aux contaminants dans la matrice). Monitored natural attenuation (MNA) : suivi de la dégradation naturelle (biodégradation, dilution, adsorption). In situ chemical oxidation (ISCO) : injection d'oxydants (permanganate, Fenton) pour dégrader les contaminants organiques. Biostimulation/bioaugmentation : apport de nutriments ou bactéries dégradantes. Barrières perméables réactives (PRB) : mur de matériau réactif interceptant le panache." }
        ]},
        { titre: "Transport dans les milieux hétérogènes", sous_sections: [
          { titre: "Transport non-Fickien et modèles anomaleux", contenu: "Dans les aquifères hétérogènes, le transport présente des 'queues' de concentration longues (non-Fickien ou 'anomalous transport'). Les contaminants dans les zones de faible conductivité (matrice argileuse, dead-end pores) diffusent lentement et créent une traîne à long terme (tailing). Les modèles CTRW (Continuous Time Random Walk) et MRMT (Multi-Rate Mass Transfer) représentent ce comportement non-Fickien. L'effet de tailing explique pourquoi le pump-and-treat est souvent insuffisant pour atteindre les seuils réglementaires." },
          { titre: "Hétérogénéité et transport stochastique", contenu: "Dans les milieux aléatoirement hétérogènes, le panache de contaminant est aléatoire. L'approche stochastique décrit la macro-dispersion par la dispersivité effective αL_macro >> αL_locale. La variance du front de panache croît linéairement avec la distance (macro-dispersion fickienne asymptotique) : σ²_x = 2 × αL_macro × x. Les simulations stochastiques (Monte Carlo sur les champs de K) produisent des ensembles de réalisations de panaches, permettant une estimation de probabilité de dépassement d'un seuil à un point donné." }
        ]}
      ],
      points: ["ADE : R∂C/∂t = DL∂²C/∂x² - v∂C/∂x - λRC (advection + dispersion + dégradation).", "Dispersivité αL ≈ 0,1 × L (dépendance à l'échelle).", "Facteur de retard R = 1 + (ρb/ne) × Kd.", "Péclet Pe = vL/DL : Pe >> 1 → advection dominante.", "Solution d'Ogata-Banks : créneau d'injection, milieu semi-infini.", "MT3DMS : code de transport couplé à MODFLOW.", "Tailing : queues de concentration longues dues aux hétérogénéités (transport non-Fickien).", "Pump-and-treat : efficace pour contenir, insuffisant seul pour réhabiliter.", "MRMT (Multi-Rate Mass Transfer) : modèle de transport non-Fickien.", "ISCO (oxydation chimique) : permanganate, Fenton pour BTEX/chlorés."],
      formules: [
        { nom: "ADE 1D avec retard et dégradation", expression: "R × ∂C/∂t = DL × ∂²C/∂x² - v × ∂C/∂x - λ × R × C", variables: "R = facteur de retard, DL = D_mec + D*, λ = constante de dégradation (1/s)" },
        { nom: "Coefficient de dispersion longitudinale", expression: "DL = αL × v + D*", variables: "αL = dispersivité longitudinale (m), v = vitesse de pore (m/s), D* = diffusion effective (m²/s)" },
        { nom: "Facteur de retard (linéaire)", expression: "R = 1 + (ρb / ne) × Kd", variables: "ρb = densité apparente du sol (kg/m³), ne = porosité efficace, Kd = coefficient de partage (m³/kg)" },
        { nom: "Nombre de Péclet", expression: "Pe = v × Δx / DL", variables: "Δx = taille de maille numérique. Pe > 2 → instabilités numériques dans les schémas centrés" },
        { nom: "Solution d'Ogata-Banks (front d'advection-dispersion)", expression: "C/C0 = 0.5 × erfc[(x-vt) / (2√(DL×t))]",  variables: "erfc = fonction d'erreur complémentaire, x = position, vt = position du front advectif" }
      ],
      retenir: "Le transport des solutés est régi par l'ADE combinant advection (vitesse de pore), dispersion (hétérogénéités de vitesse) et réactions (adsorption, dégradation). La dispersivité αL augmente avec l'échelle (αL ≈ 0,1×L). Le facteur de retard R ralentit les contaminants adsorbables. Le transport non-Fickien (tailing) dans les milieux hétérogènes limite l'efficacité du pump-and-treat. MT3DMS est le code de transport de référence couplé à MODFLOW."
    },
    exercices: [
      { id: 1, enonce: "Un contaminant a Kd = 0,002 m³/kg, ρb = 1600 kg/m³, ne = 0,25. Calculez R. Si v = 0,5 m/j, quelle est la vitesse de déplacement du front de contaminant ?", correction: "R = 1 + (1600/0,25) × 0,002 = 1 + 6400 × 0,002 = 1 + 12,8 = 13,8. v_contaminant = v/R = 0,5/13,8 = 0,036 m/j. Le contaminant se déplace 13,8× plus lentement que l'eau." },
      { id: 2, enonce: "Calculez αL pour un panache s'étendant sur 500 m (règle empirique).", correction: "αL ≈ 0,1 × L = 0,1 × 500 = 50 m. DL = αL × v = 50 × v. Pour v = 0,3 m/j = 3,5×10⁻⁶ m/s : DL = 50 × 3,5×10⁻⁶ = 1,74×10⁻⁴ m²/s = 15 m²/j. Dispersion très importante à l'échelle de terrain." },
      { id: 3, enonce: "Le nombre de Péclet d'un modèle de transport est Pe = 15 (Δx = 10 m, αL = 1 m). Y a-t-il un risque d'instabilité numérique ? Comment corriger ?", correction: "Pe = v×Δx/DL = Δx/αL = 10/1 = 10 > 2 → risque d'oscillations numériques (sur-dépassement artéfactuel de la concentration). Solutions : réduire Δx (maillage plus fin près du front), augmenter αL artificiel (numérique) jusqu'à Pe ≤ 2 (Δx ≤ 2αL = 2 m), utiliser une méthode de transport des caractéristiques (MOC, TVD) qui est stable pour Pe élevé." },
      { id: 4, enonce: "Un pesticide a T½ = 30 jours. R = 5. v_eau = 0,2 m/j. Après combien de temps et quelle distance la concentration atteint-elle 10% de la valeur initiale (sans dispersion) ?", correction: "λ = ln2/T½ = 0,693/30 = 0,0231 j⁻¹. v_pesticide = v/R = 0,2/5 = 0,04 m/j. C/C0 = exp(-λ_apparent × t) = 0,1 → t = -ln(0,1)/λ_apparent. λ_apparent = λ/R × ... Note : dans l'ADE, avec retard et dégradation : C/C0 = exp(-λ×t) sur le front. t = ln(10)/0,0231 = 99,6 jours. Distance = v_pesticide × t = 0,04 × 99,6 = 3,98 m ≈ 4 m seulement. La dégradation et le retard limitent fortement la migration." },
      { id: 5, enonce: "Expliquez le phénomène de tailing dans la courbe de restitution d'un traçage et ses implications pour le pump-and-treat.", correction: "Le tailing est la traîne de concentration à temps long dans la courbe de restitution (C/C0 décroît très lentement après le pic). Cause : diffusion des contaminants dans les zones de faible perméabilité (argiles, dead-end pores) et relargage lent. Pour le pump-and-treat : même après pompage prolongé, les concentrations restent au-dessus des seuils réglementaires car le contaminant stocké dans la matrice diffuse lentement. L'effacement du tailing peut prendre des décennies, rendant le pump-and-treat très coûteux seul." },
      { id: 6, enonce: "Citez 4 techniques de réhabilitation des eaux souterraines contaminées par des solvants chlorés (TCE, PCE).", correction: "1. Pump-and-treat : pompage + traitement par stripping ou charbon actif. 2. ISCO (In Situ Chemical Oxidation) : injection de permanganate (KMnO4) ou de Fenton (H2O2 + Fe²⁺) pour oxyder TCE/PCE. 3. ERH (Electrical Resistance Heating) : chauffage par résistance pour vaporiser les solvants résiduels. 4. Biostimulation réductrice : injection de substrats carbonés (molasse, lactosérum) pour stimuler la déhalogénation réductrice bactérienne (TCE→DCE→VC→éthylène)." },
      { id: 7, enonce: "Qu'est-ce que le modèle MRMT (Multi-Rate Mass Transfer) et pourquoi est-il plus réaliste que l'ADE classique ?", correction: "MRMT représente l'échange entre la zone mobile (pores drainants) et de multiples zones immobiles (argiles, dead-end pores) avec différentes constantes de taux d'échange. Chaque zone immobile a sa propre cinétique de diffusion. L'ADE classique suppose une distribution gaussienne du front → queue gaussienne qui ne reproduit pas le tailing long. MRMT produit des queues en loi puissance (non-Fickien), beaucoup plus réalistes dans les aquifères hétérogènes. Utilisé pour modéliser les systèmes pump-and-treat et les traçages à queue longue." },
      { id: 8, enonce: "Un puits de pompage capte de l'eau avec Cl = 180 mg/L (< 250 mg/L seuil AEP). En amont à 200 m, une décharge industrielle a Cl = 2500 mg/L. v = 0,8 m/j, αL = 20 m. Estimez la concentration à atteindre au puits après 1 an.", correction: "Temps de transit : t = 200/0,8 = 250 j < 1 an (365 j). Le front advectif arrive au puits en 250 j. Après 1 an (365 j), le panache a largement atteint le puits. La dispersion étale le front : σ_x = √(2×αL×x) = √(2×20×200) = √8000 = 89 m. Le front diffus s'étend sur ~200 m. La concentration attendue au puits ≈ Cl_source × facteur de dilution + Cl_fond. Sans calcul précis, C ≈ 500-1500 mg/L selon la dilution. Le seuil AEP (250 mg/L) sera dépassé." }
    ],
    flashcards: [
      { question: "Équation ADE : signification des termes", reponse: "R×∂C/∂t = DL×∂²C/∂x² - v×∂C/∂x - λ×R×C. R = facteur de retard (adsorption). DL×∂²C/∂x² = dispersion (étalement). v×∂C/∂x = advection (transport avec le flux). λ×R×C = dégradation de premier ordre. Chaque terme peut ralentir ou accélérer la migration du contaminant." },
      { question: "Dispersivité et dépendance à l'échelle", reponse: "αL ≈ 0,1 × L (règle de Gelhar). Exemple : L = 100 m → αL ≈ 10 m. L = 1 km → αL ≈ 100 m. Explication : à grande échelle, les hétérogénéités (chenaux sableux, lentilles argileuses) produisent des vitesses très variables → plus forte dispersion effective. Les valeurs de labo (αL ≈ cm) sous-estiment massivement la dispersion de terrain." },
      { question: "Facteur de retard : signification et calcul", reponse: "R = 1 + (ρb/ne)×Kd. R = rapport de vitesse eau/vitesse contaminant. Kd = coefficient de partage entre sol et eau (m³/kg). R = 1 → non retenu (traceur parfait). R = 10 → le contaminant avance 10× moins vite que l'eau. Dépend fortement du % en carbone organique du sol : Koc = Kd/foc (Koc = constante de partage sol organique-eau)." },
      { question: "MT3DMS : que fait-il ?", reponse: "Code de transport des solutés (Modular 3D Multi-Species Transport) couplé à MODFLOW. Résout l'ADE 3D : advection (TVD), dispersion (différences finies centrées), réactions (sorption, dégradation). Supporte multi-espèces et réactions géochimiques de base. Standard de facto pour le transport dans les aquifères. MODPATH fait le traçage de particules (advection pure, temps de transit)." },
      { question: "Pump-and-treat : limites", reponse: "Efficace pour contenir le panache (pas de migration vers l'aval) mais insuffisant seul pour atteindre les seuils réglementaires. Raisons : tailing (contaminants dans la matrice diffusent lentement), zones NAPL résiduelles (sources permanentes), coûts énergétiques élevés sur des décennies. Associer P&T à des techniques actives (ISCO, biostimulation) ou MNA pour l'objectif de réhabilitation finale." },
      { question: "Nombre de Péclet numérique et instabilités", reponse: "Pe = v×Δx/DL (numérique). Pe > 2 → oscillations/sur-dépassements (artefacts de concentration négative ou > C0). Remèdes : maillage fin (Δx ≤ 2αL), décentrage amont (upwinding, perd de la précision), méthodes TVD (Total Variation Diminishing), transport des caractéristiques (MOC). Le décentrage amont ajoute une dispersion numérique artificielle = αL_num = Δx/2." }
    ]
  },

  'MASTER-EAU-051': {
    id: 'MASTER-EAU-051',
    titre: 'Traçages, isotopes et temps de résidence',
    fiche: {
      intro: "Les traçages hydrologiques et les outils isotopiques permettent de caractériser les temps de résidence des eaux souterraines, les connexions hydrauliques et la vulnérabilité des aquifères. Ces méthodes sont complémentaires à la modélisation numérique et apportent des informations uniques sur les processus de transport et la dynamique des aquifères à différentes échelles temporelles (jours à millions d'années).",
      sections: [
        { titre: "Traçages artificiels en hydrogéologie", sous_sections: [
          { titre: "Traceurs fluorescents et leurs propriétés", contenu: "Les traceurs fluorescents (fluorescéine = uranine, rhodamine B, sulforhodamine B, naphtionate) sont injectés en bolus ou en créneau dans un puits/perte et détectés à la source ou dans des puits d'observation. La fluorescéine est le traceur le plus utilisé : détectable à 10⁻⁶ mg/L, conservatif dans les eaux souterraines (faible adsorption), fluoresce en vert sous UV. L'analyse en continu par fluorimètre submersible ou en laboratoire (spectrofluorimètre) permet de tracer la courbe de restitution C(t). La courbe de restitution fournit : temps de premier arrivée (vitesse maximale), temps de pic (vitesse modale), dispersion (étalement), taux de récupération (connexion et pertes)." },
          { titre: "Interprétation des courbes de restitution", contenu: "La courbe de restitution (Breakthrough Curve, BTC) est analysée par des modèles analytiques (ADE, CTRW) pour estimer les paramètres de transport (dispersivité, facteur de retard, vitesse). Le moment 1 (centroïde de la courbe) donne le temps de transit moyen. La variance (moment 2) donne la dispersivité. La queue longue indique un transport non-Fickien (échanges matrice-conduit dans les karsts, transfert dans les argiles). Le taux de récupération (masse récupérée/masse injectée) indique les pertes par adsorption ou dilution dans des volumes d'eau non interceptés." }
        ]},
        { titre: "Isotopes stables : δ¹⁸O et δ²H", sous_sections: [
          { titre: "Fractionnement isotopique et droite météorique", contenu: "Les molécules d'eau ¹H₂¹⁶O, ¹H₂¹⁸O et ¹H²HO (HDO) ont des pressions de vapeur différentes → fractionnement lors de l'évaporation et de la condensation. La droite météorique mondiale (GMWL : Global Meteoric Water Line, Craig 1961) : δ²H = 8 × δ¹⁸O + 10. Les eaux de pluie se répartissent selon leur altitude, latitude et saison : effet d'altitude (-0,2 à -0,5‰ δ¹⁸O par 100 m), effet de continent (enrichissement en isotopes lourds), effet saisonnier (pluies hivernales plus légères). Ces effets permettent d'identifier l'altitude de recharge et la saisonnalité de la pluie alimentant l'aquifère." },
          { titre: "Applications aux eaux souterraines", contenu: "La composition isotopique d'une eau souterraine reflète la signature des pluies de recharge (après fractionnement et mélange). Les eaux souterraines de grande profondeur (paléoeaux) ont des signatures plus négatives (pluies de l'ère glaciaire, altitude de recharge plus haute). L'écart à la GMWL révèle l'évaporation (eaux de surfaces enrichies en isotopes lourds). Les mélange d'eaux d'origines différentes sont décelés par la position sur ou hors GMWL. Les isotopes stables tracent l'origine des eaux (montagne vs plaine, surface vs profond) et permettent de distinguer les composantes de débit dans les rivières (séparation des hydrogrammes)." }
        ]},
        { titre: "Isotopes radioactifs et datation des eaux", sous_sections: [
          { titre: "Tritium ³H : eaux jeunes (< 50 ans)", contenu: "Le tritium (³H, T½ = 12,32 ans) est produit naturellement par les rayons cosmiques et artificiellement par les essais nucléaires atmosphériques (pic de 1963). La détection d'eau présentant une forte teneur en ³H indique une recharge récente (< 30 ans). Les eaux sans ³H (< 0,1 TU) ont une recharge antérieure à 1950. Problème actuel : le ³H atmosphérique est retombé à des niveaux proches du fond naturel → difficile de dater les eaux des années 1980-1990. Combiné au ³H/³He (mesure de l'hélium-3 radiogénique), il permet une datation précise des eaux jeunes (5-50 ans)." },
          { titre: "Carbone 14 et Chlorure 36 : eaux anciennes", contenu: "Le carbone 14 (¹⁴C, T½ = 5730 ans) dissous sous forme de bicarbonate date les eaux souterraines jusqu'à ~40 000 ans. Les eaux de l'ère glaciaire (20 000 BP) ont une activité ¹⁴C réduite de 80% par rapport aux eaux modernes. Des corrections sont nécessaires pour les dilutions par du CO2 d'origine profonde (géothermale, dissolution de calcaire mort). Le ³⁶Cl (T½ = 301 000 ans, produit par neutrons cosmiques ou tests nucléaires) et l'argon 39 (³⁹Ar, T½ = 269 ans) complètent les datations pour des gammes temporelles intermédiaires." }
        ]},
        { titre: "Gaz dissous et traceurs environnementaux", sous_sections: [
          { titre: "CFC et SF6 pour les eaux jeunes", contenu: "Les chlorofluorocarbones (CFC-11, CFC-12, CFC-113) et l'hexafluorure de soufre (SF6) sont des traceurs anthropogéniques dont la concentration atmosphérique est connue depuis les années 1950. La mesure de leur concentration dans l'eau souterraine permet de dater les eaux de 0 à 50 ans par comparaison avec les courbes d'évolution atmosphérique. Problèmes : les CFC sont dégradés en conditions anaérobies, contaminés par des sources locales (agricultures, industries). SF6 est plus stable. Ces traceurs sont utilisés pour estimer les temps de résidence dans les zones non saturées et les aquifères exploités." },
          { titre: "Hélium et néon : eaux très anciennes", contenu: "L'hélium 4 (⁴He) est produit par la radioactivité naturelle (désintégration U/Th). Son accumulation dans les eaux souterraines permet d'estimer des âges de millions d'années (grandes nappes fossiles comme le Sahara, Arabie). L'argon 40 (⁴⁰Ar) a une application similaire. Le néon est utilisé pour les températures de recharge (solubilité T-dépendante). Le krypton 85 (⁸⁵Kr, T½ = 10,8 ans) est un traceur anthropogénique (retraitements nucléaires) pour les eaux de 0-30 ans. Ces outils multi-traceurs permettent de construire un 'âge' de l'eau souterraine couvrant du jour au million d'années." }
        ]}
      ],
      points: ["Fluorescéine : traceur de référence, détectable à 10⁻⁶ mg/L, conservatif.", "GMWL : δ²H = 8 × δ¹⁸O + 10. Déviation → évaporation ou recharge ancienne.", "Effet altitude : -0,3‰ δ¹⁸O par 100 m de gain d'altitude.", "³H (T½ = 12,32 ans) : eau < 50 ans. Sans ³H → recharge antérieure à 1950.", "¹⁴C (T½ = 5730 ans) : datation 1 000 à 40 000 ans BP.", "CFC et SF6 : traceurs anthropogéniques pour datation 0-50 ans.", "⁴He : indicateur d'eaux très anciennes (> 10 000 à millions d'années).", "BTC (courbe de restitution) → moment 1 (temps transit), moment 2 (dispersivité).", "Séparation d'hydrogrammes : δ¹⁸O ou conductivité pour distinguer ruissellement et eau de nappe.", "³H/³He : datation précise des eaux jeunes (5-50 ans)."],
      formules: [
        { nom: "Droite météorique mondiale (GMWL)", expression: "δ²H = 8 × δ¹⁸O + 10 (‰ SMOW)", variables: "δ¹⁸O et δ²H exprimés en ‰ par rapport au Standard Mean Ocean Water" },
        { nom: "Désintégration radioactive (datation ¹⁴C)", expression: "A(t) = A₀ × exp(-λ × t) → t = -ln(A/A₀) / λ", variables: "A = activité mesurée (% moderne), A₀ = activité initiale, λ = ln2/T½ = ln2/5730 an⁻¹" },
        { nom: "Temps de résidence par ³H/³He", expression: "t = T½/ln2 × ln(1 + ³He*/³H)", variables: "³He* = hélium-3 tritiogénique (mesuré par spectrométrie de masse), ³H = tritium résiduel" },
        { nom: "Mélange de deux sources (mixing model)", expression: "C_mélange = f × C₁ + (1-f) × C₂", variables: "f = fraction de la source 1 (0-1), C = isotope ou traceur conservatif" },
        { nom: "Moment 1 de la courbe de restitution (temps de transit moyen)", expression: "τ = ∫₀^∞ t × C(t) dt / ∫₀^∞ C(t) dt", variables: "C(t) = concentration mesurée en fonction du temps, τ = temps de transit moyen" }
      ],
      retenir: "Les traçages et isotopes fournissent une information complémentaire irremplaçable à la modélisation numérique. Les isotopes stables (δ¹⁸O, δ²H) identifient l'origine et la saisonnalité de la recharge. Les isotopes radioactifs (³H, ¹⁴C, CFC, SF6) datent les eaux de quelques mois à des millénaires. Les traçages artificiels (fluorescéine) caractérisent les connexions et les vitesses dans les karsts. L'approche multi-traceurs est la plus robuste pour caractériser un système aquifère complexe."
    },
    exercices: [
      { id: 1, enonce: "Une eau souterraine a δ¹⁸O = -9,5‰ et δ²H = -68‰. Vérifiez si elle est sur la GMWL et interprétez.", correction: "GMWL : δ²H = 8 × δ¹⁸O + 10 = 8 × (-9,5) + 10 = -76 + 10 = -66‰. Mesuré : -68‰. Déviation = -68 - (-66) = -2‰. L'eau est légèrement sous la GMWL, indiquant une légère évaporation (eau enrichie en ¹⁸O relative à ²H). Typique d'une eau de surface partiellement évaporée avant infiltration." },
      { id: 2, enonce: "Une eau a une activité ¹⁴C de 42 pmC (% moderne). Calculez son âge apparent (T½ = 5730 ans, A₀ = 100 pmC).", correction: "λ = ln2/5730 = 1,21×10⁻⁴ an⁻¹. t = -ln(42/100)/λ = -ln(0,42)/1,21×10⁻⁴ = 0,8676/1,21×10⁻⁴ = 7170 ans. L'eau a environ 7200 ans BP. Recharge durant l'Holocène moyen." },
      { id: 3, enonce: "Un traceur fluorescéine est injecté en perte karstique à 3,5 km d'une source. La courbe de restitution montre : premier arrivée t1 = 6h, pic tp = 14h, temps à C = 10% du pic t90 = 48h. Calculez les vitesses min, modale et de transit à 90% de la masse.", correction: "v_max = 3500/6 = 583 m/h. v_pic = 3500/14 = 250 m/h. v_90% = 3500/48 = 73 m/h. L'eau circule en partie par des conduits rapides (v > 500 m/h) et en partie par des chemins plus lents (matrice fracturée). La dispersion sur une distance de 3,5 km est très forte (facteur 8 entre v_max et v_90%)." },
      { id: 4, enonce: "Citez 3 avantages des traceurs isotopiques naturels (δ¹⁸O, δ²H, ³H) par rapport aux traceurs artificiels (fluorescéine).", correction: "1. Pas d'injection nécessaire : sont présents naturellement dans toutes les eaux (surveillance continue sans manipulation de terrain). 2. Intègrent le signal sur de longues périodes (saisonnalité, interannuel). 3. Caractérisent l'origine de l'eau (altitude de recharge, mélange surface-profond), information inaccessible aux traceurs artificiels (qui tracent seulement les connexions)." },
      { id: 5, enonce: "Les CFC-11 mesuré dans une eau est de 1200 pptv. La courbe d'évolution atmosphérique montre que cette concentration correspond à l'atmosphère de 1985. Interprétez et citez 2 limitations.", correction: "L'eau est en équilibre avec l'atmosphère de 1985 → temps de résidence depuis la recharge ≈ 2026-1985 = 41 ans. Limitations : 1. Dégradation des CFC en conditions anaérobies (méthanogène, sulfatogénique) → sous-estimation de la concentration → surestimation de l'âge. 2. Contamination locale par des sources anthropiques (CFC d'une décharge, activité industrielle) → surestimation de la concentration → sous-estimation de l'âge." },
      { id: 6, enonce: "Une rivière a δ¹⁸O = -7,5‰ en étiage et -6,2‰ en crue (après une forte pluie avec δ¹⁸O_pluie = -4,8‰). Calculez la fraction de pluie dans le débit de crue.", correction: "Mélange : C_mélange = f × C_pluie + (1-f) × C_nappe. -6,2 = f × (-4,8) + (1-f) × (-7,5). -6,2 = -4,8f - 7,5 + 7,5f. -6,2 + 7,5 = 2,7f. 1,3 = 2,7f. f = 0,48 = 48%. Environ 48% du débit de crue provient de la pluie directe (ruissellement), 52% de la nappe. La nappe contribue plus de la moitié même en crue." },
      { id: 7, enonce: "Que signifie l'âge 'apparent' en datation ¹⁴C des eaux souterraines et pourquoi faut-il des corrections ?", correction: "L'âge apparent suppose A₀ = 100 pmC (activité initiale de l'eau de pluie en contact avec l'atmosphère). En réalité, A₀ peut être inférieure à 100 pmC car : 1. Dissolution de calcaire 'mort' (sans ¹⁴C car > 100 000 ans) : dilue le ¹⁴C → sur-estime l'âge. 2. CO2 profond d'origine magmatique/géothermale sans ¹⁴C. Correction de Fontes-Garnier ou de Mook corrige A₀ à partir de la chimie du bicarbonate (δ¹³C) pour obtenir l'âge corrigé." },
      { id: 8, enonce: "Citez et expliquez 4 traceurs environnementaux et leurs gammes temporelles de datation.", correction: "1. CFC/SF6 : 0-50 ans. Concentration atmosphérique croissante depuis 1950. 2. ³H : 5-30 ans (pic 1963 de retombées nucléaires). ³H/³He : 5-50 ans. 3. ¹⁴C : 1 000-40 000 ans. T½ = 5730 ans. Bicarbonate dissous. Corrections nécessaires. 4. ⁴He radiogénique : > 10 000 ans (accumulation de ⁴He par désintégration U/Th de la matrice rocheuse). Nappes fossiles (Sahara : 10 000-1 000 000 ans). Combinaison multi-traceurs = datation robuste couvrant du jour au million d'années." }
    ],
    flashcards: [
      { question: "Droite météorique mondiale (GMWL) : utilité", reponse: "GMWL : δ²H = 8×δ¹⁸O + 10. Référence pour les eaux météoriques. Déviation sous GMWL = évaporation (enrichissement en ¹⁸O relatif à ²H). Déviation sur GMWL = impossible physiquement. Pente locale de la droite météorique (Local MWL) varie selon le régime climatique. Utilisée pour : identifier les eaux évaporées, tracer les mélanges, détecter les recharges fossiles (paléoeaux sous GMWL par évaporation glaciaire)." },
      { question: "³H pour dater les eaux souterraines", reponse: "T½ = 12,32 ans. Pic de 1963 (essais nucléaires). Eau avec ³H > 1 TU = recharge post-1950. Eau sans ³H = recharge pré-1950 (> 60 ans). ³H seul difficile à quantifier aujourd'hui (retombé au fond naturel). ³H/³He : âge = T½/ln2 × ln(1 + ³He*/³H). Précision : ±1-5 ans pour eaux de 10-50 ans." },
      { question: "Traceurs de transport : fluorescéine vs ¹⁸O", reponse: "Fluorescéine : traceur artificiel, injection ponctuelle, courbe de restitution = connexion + vitesse + dispersion. Spécifique au karst et aux traçages de captages. ¹⁸O : traceur naturel, signal saisonnier, intègre sur des mois-années. Séparation d'hydrogrammes : fraction nappe vs pluie. Pas d'injection, surveillance continue. Complémentaires : fluorescéine pour connexions, ¹⁸O pour dynamique saisonnière." },
      { question: "CFC et SF6 : principes et limitations", reponse: "Traceurs anthropogéniques dans l'atmosphère depuis 1950-1960. Concentration dans l'eau souterraine = équilibre avec l'atmosphère à l'époque de la recharge. CFC-12 : traçage 1965-2000. SF6 : 1980-présent. Limitations : CFC dégradés en anaérobie (trop vieux), contamination locale industrielle/agricole. SF6 plus stable mais aussi contaminable. Âge apparent = temps depuis équilibre avec atmosphère. Mélange avec eau ancienne = sous-estimation de l'âge." },
      { question: "Datation ¹⁴C : problème de la dilution", reponse: "A₀ théorique = 100 pmC (eau neuve en contact avec CO2 atmosphérique). En aquifère carbonaté : dissolution de calcaire 'mort' (¹⁴C = 0) dilue le ¹⁴C → A₀ apparent < 100 pmC → âge sur-estimé. Correction : modèle géochimique de mélange calcite-CO2 (Fontes-Garnier, NETPATH). δ¹³C guide la correction. Âges corrigés peuvent différer de plusieurs millénaires de l'âge apparent." },
      { question: "Approche multi-traceurs pour caractériser un aquifère", reponse: "Chaque traceur couvre une gamme temporelle et un processus différent. Exemple : ³H/³He (5-50 ans) + CFC (0-50 ans) + ¹⁴C (1000-40000 ans) + δ¹⁸O (origine de la recharge) + fluorescéine (connexions). La cohérence entre traceurs valide l'interprétation. Les contradictions (un traceur indique eau vieille, un autre eau jeune) révèlent des mélanges ou des artefacts à investiguer." }
    ]
  },

  'MASTER-EAU-052': {
    id: 'MASTER-EAU-052',
    titre: 'Gestion quantitative, vulnérabilité et protection des captages',
    fiche: {
      intro: "La gestion quantitative des eaux souterraines vise à concilier les prélèvements (AEP, irrigation, industrie) avec la préservation des niveaux piézométriques, des zones humides et du débit d'étiage des cours d'eau. La vulnérabilité des aquifères et la protection des captages d'eau potable constituent le volet préventif de la gestion. Ces enjeux sont au cœur de la politique de l'eau en France et en Europe.",
      sections: [
        { titre: "Cadre réglementaire de la gestion quantitative", sous_sections: [
          { titre: "DCE et bon état quantitatif des eaux souterraines", contenu: "La Directive Cadre sur l'Eau (DCE, 2000/60/CE) fixe l'objectif de bon état quantitatif des masses d'eau souterraines : les prélèvements ne doivent pas dépasser la recharge renouvelable de manière à ne pas entraîner de dommages pour les écosystèmes terrestres associés (zones humides). L'évaluation est basée sur les tendances piézométriques (Mann-Kendall sur ADES) et les impacts sur les rivières et zones humides. L'état quantitatif se décline en 'bon état' et 'mauvais état' (deux classes, contrairement aux 5 classes chimiques). En France, environ 20% des masses d'eau souterraine sont en mauvais état quantitatif." },
          { titre: "SAGE et gestion des prélèvements", contenu: "Le Schéma d'Aménagement et de Gestion des Eaux (SAGE) est l'outil de planification locale de la gestion de l'eau (bassin versant ou aquifère). Il fixe les objectifs et les orientations de gestion. Les SAGE des grands aquifères (Beauce, Crau, Bas-Rhône) ont défini des volumes prélevables maximum (volumes de référence). Les arrêtés-cadre sécheresse fixent des seuils de vigilance, d'alerte et de crise déclenchant des restrictions de prélèvements. En période de tension quantitative sévère, les tribunaux administratifs ont suspendu des autorisations de pompage insuffisamment justifiées (jurisprudence 2021-2023)." }
        ]},
        { titre: "Méthodes d'évaluation des ressources renouvelables", sous_sections: [
          { titre: "Volumes prélevables et réserve d'ajustement", contenu: "Le Volume Prélevable (VP) est le volume maximum qui peut être extrait annuellement sans compromettre le bon état quantitatif. Il est défini comme : VP = Recharge - Décharge naturelle minimale (soutien d'étiage des rivières, alimentation des zones humides). En France, la méthode de l'IRSTEA/INRAE calcule le VP par simulation sur modèle hydrogéologique calé sur les chroniques piézométriques de 30-50 ans. La réserve d'ajustement (RA) représente le tampon entre VP et prélèvements actuels : si RA > 0, des prélèvements supplémentaires sont possibles." },
          { titre: "Bilans hydrogéologiques et incertitudes", contenu: "Le bilan d'un aquifère intègre des termes difficiles à estimer (recharge spatiale, échanges nappe-rivière, transferts latéraux). Les incertitudes sont souvent de ±20-50% sur la recharge. Cette incertitude se répercute directement sur le Volume Prélevable. La méthode de Monte Carlo sur les modèles hydrogéologiques quantifie l'incertitude du VP. En période de déficit (années sèches), le VP peut être nul ou négatif : même sans prélèvements supplémentaires, l'aquifère se déstocke. La gestion de crise (restrictions d'urgence) est alors inévitable." }
        ]},
        { titre: "Protection des captages d'eau potable", sous_sections: [
          { titre: "Périmètres de protection réglementaires", contenu: "Le Code de la Santé Publique (R.1321-6 à R.1321-16) définit 3 périmètres de protection autour des captages AEP : PPP (Périmètre de Protection Immédiate, quelques mètres, clôture obligatoire), PPR (Périmètre de Protection Rapproché, défini par le temps de transfert < 50 jours depuis la surface jusqu'au captage), PPE (Périmètre de Protection Éloigné, bassin d'alimentation sans seuil de temps). Ces périmètres sont définis par un hydrogéologue agréé et sont institués par un arrêté de déclaration d'utilité publique (DUP). En 2022, 68% des 33 000 captages AEP français étaient protégés par un arrêté DUP." },
          { titre: "Zones à Préserver pour le Futur (ZPF) et AAC", contenu: "Les Zones de Protection de l'Alimentation en eau potable (ZPAE ou AAC : Aire d'Alimentation des Captages) sont délimitées conformément aux Grenelle 1 et 2 (2007-2010). Pour les 1000 captages prioritaires (liste établie par les agences de l'eau), le plan d'action territorial (PAT) définit les changements de pratiques agricoles nécessaires pour atteindre les seuils de qualité. Les captages prioritaires pour les nitrates et pesticides font l'objet de mesures agro-environnementales (MAE) et de contractualisation avec les agriculteurs." }
        ]},
        { titre: "Recharge artificielle et solutions innovantes", sous_sections: [
          { titre: "Infiltration dirigée et recharge gérée", contenu: "La recharge artificielle (Managed Aquifer Recharge, MAR) consiste à injecter ou à infiltrer de l'eau dans les aquifères pour reconstituer les stocks. Les techniques incluent : bassins d'infiltration, puits d'injection (ASR), canaux d'infiltration (Spreading), épandage sur alluvions (réalimentation par gravité). Les sources d'eau sont : eau pluviale excédentaire (hiver), eau de rivière (en crue), eau recyclée (après traitement avancé). En Provence, le Schéma de Mise en Valeur des Eaux de la Durance utilise des bassins d'infiltration pour recharger l'aquifère de la Crau." },
          { titre: "Gestion de crise et partage des ressources", contenu: "La gestion de crise en période de sécheresse (arrêtés de restriction, tours d'eau entre irrigants) requiert une organisation préalable entre les usagers (structures collectives, Organismes Uniques de Gestion Collective, OUGC). En France, les OUGC gèrent les droits de prélèvement entre irrigants d'un même aquifère (système de volumes alloués). Les conflits d'usage (agriculteurs vs AEP vs environnement) sont arbitrés par les préfets. La jurisprudence administrative montre une tendance croissante à limiter les prélèvements agricoles en faveur des usages AEP et de l'environnement (critère de préservation des zones humides DCE)." }
        ]}
      ],
      points: ["DCE : bon état quantitatif = prélèvements < recharge renouvelable. 20% des MES en mauvais état en France.", "VP (Volume Prélevable) = Recharge - Décharge naturelle minimale.", "SAGE : outil de planification locale avec volumes de référence.", "Arrêtés sécheresse : 4 niveaux (vigilance, alerte, alerte renforcée, crise).", "PPP (clôture), PPR (< 50 jours), PPE (bassin d'alimentation) : 3 périmètres réglementaires.", "68% des captages AEP français avaient un arrêté DUP en 2022.", "1000 captages prioritaires français pour nitrates et pesticides (plan Grenelle).", "MAR (Managed Aquifer Recharge) : bassins d'infiltration, ASR, épandage.", "OUGC : gestionnaires des droits de prélèvement entre irrigants.", "Recharge de la Crau (SMVDA) : réalimentation par les eaux de la Durance."],
      formules: [
        { nom: "Volume Prélevable (VP) simplifié", expression: "VP = Recharge - D_min_rivières - D_min_zones_humides", variables: "D_min = décharge naturelle minimale à maintenir pour le bon état écologique" },
        { nom: "Coefficient d'exploitation", expression: "τ = Prélèvements_actuels / Recharge_renouvelable × 100%", variables: "τ < 50% : ressource bien gérée. τ > 80% : aquifère surexploité (risque de mauvais état DCE)" },
        { nom: "Temps de transit dans l'aquifère (PPR)", expression: "t = L × ne / (K × I)", variables: "L = longueur du chemin de flux (m), ne = porosité efficace, K = conductivité, I = gradient" },
        { nom: "Débit de soutien d'étiage", expression: "Q_étiage = Q_captage × (1 - f_captage)", variables: "f_captage = fraction du débit de base capté par les pompages. Q_étiage minimal = débit de survie biologique" },
        { nom: "Volume de recharge par bassin d'infiltration", expression: "V_recharge = Klit × A × Δh / b_sol × Δt",  variables: "A = superficie du bassin, Δh = charge hydraulique au fond du bassin, b_sol = épaisseur sol" }
      ],
      retenir: "La gestion quantitative des eaux souterraines intègre l'évaluation des ressources renouvelables (VP), le cadre réglementaire DCE/SAGE et les restrictions de crise. La protection des captages AEP repose sur 3 périmètres réglementaires (PPP, PPR, PPE) définis par des hydrogéologues agréés. La recharge artificielle (MAR) est une solution de gestion durable en zones déficitaires. Les conflits d'usage (agriculture/AEP/environnement) sont croissants et arbitrés par les SAGE et la jurisprudence administrative."
    },
    exercices: [
      { id: 1, enonce: "Un aquifère a une recharge R = 120 Mm³/an. La décharge minimale vers les rivières est 45 Mm³/an et vers les zones humides 15 Mm³/an. Les prélèvements actuels sont 70 Mm³/an. Calculez le VP et le coefficient τ.", correction: "VP = R - D_min = 120 - 45 - 15 = 60 Mm³/an. τ = 70/120 = 58%. Le VP est 60 Mm³/an mais les prélèvements actuels sont 70 Mm³/an > VP → dépassement de 10 Mm³/an. L'aquifère est en mauvais état quantitatif (prélèvements > VP). Réduction de 10 Mm³/an nécessaire." },
      { id: 2, enonce: "Le PPR d'un captage est défini par t < 50 jours. T = 2×10⁻³ m²/s, ne = 0,15, épaisseur b = 20 m, gradient I = 5×10⁻³. Calculez la distance maximale du PPR.", correction: "K = T/b = 2×10⁻³/20 = 10⁻⁴ m/s. v = K×I/ne = 10⁻⁴ × 5×10⁻³ / 0,15 = 3,33×10⁻⁶ m/s = 0,288 m/j. L_PPR = v × t_PPR = 0,288 × 50 = 14,4 m. PPR de seulement 14 m ! Aquifère peu perméable, gradient faible. En réalité le PPR comprend aussi une zone amont géographique plus large pour tenir compte des incertitudes." },
      { id: 3, enonce: "Citez les 4 niveaux d'alerte sécheresse et les types de restrictions associées.", correction: "1. Vigilance : information et sensibilisation (pas de restriction). 2. Alerte : réduction de 25% des prélèvements agricoles, irrigation nocturne. 3. Alerte renforcée : réduction de 50% des prélèvements agricoles, restriction loisirs. 4. Crise : interdiction de tous les prélèvements sauf AEP et sécurité, réduction minimale des pompages agricoles (arrosage santé des animaux uniquement). Déclenchés par arrêtés préfectoraux selon les seuils piézométriques et les débits de référence." },
      { id: 4, enonce: "Qu'est-ce qu'un OUGC et quel est son rôle dans la gestion des prélèvements ?", correction: "Organisme Unique de Gestion Collective (OUGC) : structure (chambre d'agriculture, syndicat d'irrigants) mandatée par le préfet pour gérer collectivement les autorisations de prélèvements entre irrigants d'un même sous-bassin ou aquifère. L'OUGC reçoit une autorisation globale de prélèvement et la répartit entre ses membres (tours d'eau, volumes individuels). Il déclenche les restrictions en cas de déficit. Avantage : gestion collective plus efficace qu'une multitude d'autorisations individuelles. Obligation dans les bassins en déséquilibre quantitatif chronique." },
      { id: 5, enonce: "La recharge artificielle par bassin d'infiltration injecte 5 Mm³/an dans un aquifère déficitaire. Citez 3 contraintes techniques ou réglementaires de cette technique.", correction: "1. Qualité de l'eau injectée : conforme aux critères de réinjection (absence de pathogènes, MES < 2 mg/L pour éviter le colmatage). 2. Risque de colmatage du fond des bassins (MES, MO biologique) nécessitant un entretien régulier (curage, retournement du fond). 3. Autorisation de recharge : dossier loi sur l'eau nécessaire (rubrique 1.1.1.0), étude d'impact hydrogéologique sur les aquifères et les puits voisins, évaluation des risques de migration de contaminants depuis les bassins." },
      { id: 6, enonce: "20% des masses d'eau souterraine françaises sont en mauvais état quantitatif. Citez 3 facteurs expliquant ce taux.", correction: "1. Surexploitation agricole (irrigants): aquifères de Beauce, Poitou-Charentes, Bretagne → prélèvements > recharge en années sèches. 2. Changement climatique : réduction de la recharge (pluies efficaces en baisse de 5-10% sur 30 ans dans le Sud et l'Est). 3. Augmentation des prélèvements AEP (croissance démographique périurbaine) et industriels dans les zones à faible ressource renouvelable (calcaires karstiques surexploités du Languedoc)." },
      { id: 7, enonce: "Expliquez la différence entre PPR, PPE et AAC d'un captage AEP.", correction: "PPR (Périmètre de Protection Rapproché) : zone pour laquelle t_transfert < 50 jours depuis la surface jusqu'au captage. Servitudes réglementaires imposées : interdiction d'épandage, de forage, d'activités à risque. Défini par un hydrogéologue agréé. PPE (Périmètre de Protection Éloigné) : bassin d'alimentation complet du captage. Recommandations (non obligatoires) sur les pratiques agricoles et l'urbanisme. AAC (Aire d'Alimentation des Captages prioritaires Grenelle) : périmètre plus large, défini pour les 1000 captages prioritaires, avec plans d'action agro-environnementaux obligatoires." },
      { id: 8, enonce: "Un captage AEP alimente 10 000 habitants (200 L/j/hab). T = 10⁻² m²/s, S = 2×10⁻⁴. Calculez le débit de pompage requis, le rayon d'influence après 1 an, et commentez si l'aquifère peut subvenir à ce besoin avec une recharge de 150 mm/an sur 50 km².", correction: "Q_besoin = 10 000 × 0,2 = 2000 m³/j = 0,023 m³/s. R_influence = √(2,25×10⁻²×365×86400/(2×10⁻⁴)) = √(2,25×0,01×31536000/0,0002) = √(708000000) = 26600 m = 26,6 km. Recharge = 150 mm × 50×10⁶ m² = 7,5×10⁶ m³/an = 7,5 Mm³/an = 20 548 m³/j. Besoin = 2000 m³/j << Recharge (20 548 m³/j). L'aquifère peut subvenir au besoin : τ = 2000/20548 = 10%. Ressource très bien gérée." }
    ],
    flashcards: [
      { question: "Bon état quantitatif DCE : définition", reponse: "État d'une masse d'eau souterraine où les prélèvements n'entraînent pas : de tendances piézométriques à la baisse chroniques, de dommages aux écosystèmes terrestres associés (zones humides), d'intrusion saline. Évalué par tendances Mann-Kendall sur ADES et impacts sur les rivières (étiages). En France : 20% des MEP en mauvais état quantitatif." },
      { question: "3 périmètres de protection des captages AEP", reponse: "PPP (immédiat) : quelques m, clôturé, aucune activité humaine. PPR (rapproché) : délimité par t < 50 jours, servitudes réglementaires (interdictions d'épandage, forage, activités à risque). PPE (éloigné) : bassin d'alimentation complet, recommandations non obligatoires. Définis par hydrogéologue agréé, institués par arrêté DUP." },
      { question: "Volume Prélevable (VP) : calcul et utilisation", reponse: "VP = Recharge - Décharge naturelle minimale (soutien d'étiage des rivières + alimentation des zones humides). VP donne le volume annuel extractible sans compromettre le bon état quantitatif. τ = Prélèvements/Recharge : si τ > 80% → risque de mauvais état. VP calculé par modèle hydrogéologique sur longue période climatique (30-50 ans)." },
      { question: "SAGE et gestion quantitative", reponse: "Schéma d'Aménagement et de Gestion des Eaux : outil de planification locale approuvé par le préfet. Définit les volumes prélevables maximum par secteur. Peut être rendu opposable aux tiers. Exemples : SAGE Beauce (limitant l'irrigation), SAGE Nappes profondes de Gironde (artésianisme). Outils de mise en œuvre : arrêtés-cadre sécheresse, OUGC, contrats de milieu." },
      { question: "Recharge artificielle (MAR) : définition et méthodes", reponse: "Managed Aquifer Recharge : introduction intentionnelle d'eau dans les aquifères pour accroître les réserves. Méthodes : bassins d'infiltration (facile, peu coûteux, colmatage à gérer), puits d'injection ASR (aquifer storage and recovery), épandage sur alluvions, digues de rétention. Eau source : excédent hivernal, eau de crue, eau recyclée (après traitement tertiaire). Objectif : stocker l'eau excédentaire pour l'utiliser en été." },
      { question: "1000 captages prioritaires Grenelle : enjeux", reponse: "Liste des captages AEP les plus menacés par les pesticides et nitrates (établie par agences de l'eau, BRGM). Pour chaque captage : délimitation de l'AAC, diagnostic des sources de contamination, plan d'action territorial (PAT) avec MAE pour réduire les pressions agricoles. Objectif : atteindre les normes AEP à horizon 10-15 ans. Outil contractuel (agriculteurs volontaires) + réglementaire (captages à enjeux prioritaires)." }
    ]
  }
};
